std::string attribution_metric_label(const std::string& name) {
  static const std::unordered_map<std::string, std::string> labels{
      {"vm_pu", "Vm"}, {"va_rad", "Va"}, {"vdc_pu", "Vdc"},
      {"p_mw", "P"}, {"q_mvar", "Q"}, {"soc", "SOC"},
      {"loss_mw", "Loss"}, {"p_schedule_mw", "P schedule"},
      {"p_initial_mw", "P initial"}, {"p_rated_kw", "P rated"}};
  if (const auto it = labels.find(name); it != labels.end()) return it->second;
  return name;
}

std::string attribution_quantity(const std::string& name,
                                 const std::string& unit) {
  if (unit == "MW" || name.find("p_") != std::string::npos ||
      name.find("_pf_") != std::string::npos ||
      name.find("_pt_") != std::string::npos)
    return "p";
  if (unit == "MVar" || name.find("q_") != std::string::npos) return "q";
  return "scalar";
}

json rich_attribution_to_component_results(
    const hacdcpf::projection::RichResultAttribution& attribution) {
  json rows = json::array();
  for (const auto& component : attribution.components) {
    json metrics = json::array();
    for (const auto& value : component.values) {
      double displayed = value.value;
      std::string unit = value.unit;
      std::string label = attribution_metric_label(value.name);
      if (value.name == "va_rad") {
        displayed *= 180.0 / M_PI;
        unit = "deg";
      }
      metrics.push_back(json{{"label", label}, {"name", value.name},
                             {"value", displayed}, {"unit", unit},
                             {"quantity", attribution_quantity(value.name, unit)},
                             {"precision", 4}});
    }
    json terminals = json::array();
    for (const auto& terminal : component.terminals) {
      const std::string prefix =
          component.component_type == "vsc_converter"
              ? (terminal.is_dc ? "dc" : "ac")
          : component.component_type == "dcdc_converter"
              ? terminal.name
          : terminal.name == "from" ? "f"
          : terminal.name == "to" ? "t"
                                    : terminal.name;
      if (terminal.has_p)
        metrics.push_back(json{{"label", "P" + prefix},
                               {"name", "terminal." + terminal.name + ".p_mw"},
                               {"value", terminal.p_mw}, {"unit", "MW"},
                               {"quantity", "p"}, {"precision", 4}});
      if (terminal.has_q)
        metrics.push_back(json{{"label", "Q" + prefix},
                               {"name", "terminal." + terminal.name + ".q_mvar"},
                               {"value", terminal.q_mvar}, {"unit", "MVar"},
                               {"quantity", "q"}, {"precision", 4}});
      terminals.push_back(
          json{{"name", terminal.name}, {"bus", terminal.bus},
               {"domain", terminal.is_dc ? "DC" : "AC"},
               {"sign_convention", "positive_injection_into_network"},
               {"p_mw", terminal.has_p ? json(terminal.p_mw) : json(nullptr)},
               {"q_mvar", terminal.has_q ? json(terminal.q_mvar) : json(nullptr)},
               {"v_pu", terminal.has_v ? json(terminal.v_pu) : json(nullptr)}});
    }
    json sources = json::array();
    for (const auto& source : component.canonical_sources)
      sources.push_back(json{{"component_type", source.component_type},
                             {"component_index", source.component_index},
                             {"participation_factor", source.participation_factor}});
    rows.push_back(
        json{{"canvas_type", component.component_type},
             {"canvas_index", component.component_index},
             {"index", component.component_index},
             {"position", component.position}, {"domain", component.domain},
             {"name", component.name},
             {"status", component.in_service ? "已求解" : "停运"},
             {"in_service", component.in_service},
             {"recovery_class",
              hacdcpf::projection::recovery_class_name(component.recovery)},
             {"recovery_reason", component.recovery_reason},
             {"canonical_sources", std::move(sources)},
             {"terminals", std::move(terminals)},
             {"metrics", std::move(metrics)}});
  }
  return rows;
}

json rich_attribution_coverage_json(
    const hacdcpf::projection::AttributionCoverage& coverage) {
  return json{{"rich_components", coverage.rich_components},
              {"attributed_components", coverage.attributed_components},
              {"total", coverage.total()},
              {"strong", coverage.strong_components},
              {"approximate", coverage.approximate_components},
              {"audit_only", coverage.audit_only_components},
              {"unsupported", coverage.unsupported_components}};
}

json attributed_power_balance_diagnostics(
    const hacdcpf::HybridPowerSystem& sys,
    const hacdcpf::projection::RichResultAttribution& attribution) {
  struct Ledger {
    double injection_p{0.0};
    double injection_q{0.0};
    double export_p{0.0};
    double export_q{0.0};
    json details = json::array();
  };
  std::unordered_map<int, Ledger> ac;
  std::unordered_map<int, Ledger> dc;
  const std::unordered_set<std::string> network_types{
      "ac_branch", "dc_branch", "transformer_2w", "transformer_3w",
      "switch", "circuit_breaker"};
  auto add_detail = [](Ledger& ledger, const std::string& label, double p,
                       double q, bool injection) {
    ledger.details.push_back(json{{"label", label}, {"p_mw", p},
                                  {"q_mvar", q},
                                  {"role", injection ? "injection" : "export"}});
  };
  for (const auto& row : attribution.components) {
    if (!row.in_service || row.terminals.empty()) continue;
    const bool network = network_types.count(row.component_type) > 0;
    for (const auto& terminal : row.terminals) {
      if (!terminal.has_p && !terminal.has_q) continue;
      auto& ledger = terminal.is_dc ? dc[terminal.bus] : ac[terminal.bus];
      const double p = terminal.has_p ? terminal.p_mw : 0.0;
      const double q = terminal.has_q ? terminal.q_mvar : 0.0;
      const std::string label = row.name + " / " + terminal.name;
      if (network) {
        ledger.export_p += p;
        ledger.export_q += q;
      } else {
        ledger.injection_p += p;
        ledger.injection_q += q;
      }
      add_detail(ledger, label, p, q, !network);
    }
  }
  auto value = [&](const std::string& type, const std::string& domain,
                   int index, const std::string& name, double fallback) {
    const auto row = std::find_if(
        attribution.components.begin(), attribution.components.end(),
        [&](const auto& item) {
          return item.component_type == type && item.domain == domain &&
                 item.component_index == index;
        });
    if (row == attribution.components.end()) return fallback;
    const auto item = std::find_if(row->values.begin(), row->values.end(),
                                   [&](const auto& v) { return v.name == name; });
    return item == row->values.end() ? fallback : item->value;
  };
  auto inject_ac = [&](int bus, double p, double q, const std::string& label) {
    auto& ledger = ac[bus];
    ledger.injection_p += p;
    ledger.injection_q += q;
    add_detail(ledger, label, p, q, true);
  };
  auto inject_dc = [&](int bus, double p, const std::string& label) {
    auto& ledger = dc[bus];
    ledger.injection_p += p;
    add_detail(ledger, label, p, 0.0, true);
  };
  std::unordered_map<int, double> ac_vm;
  for (const auto& b : sys.ac.buses) {
    if (!b.in_service) continue;
    const double vm = [&]() {
      const auto row = std::find_if(attribution.components.begin(), attribution.components.end(),
          [&](const auto& item) { return item.component_type == "ac_bus" && item.component_index == b.index; });
      if (row == attribution.components.end()) return b.vm_pu;
      const auto item = std::find_if(row->values.begin(), row->values.end(),
          [](const auto& v) { return v.name == "vm_pu"; });
      return item == row->values.end() ? b.vm_pu : item->value;
    }();
    ac_vm[b.index] = vm;
    inject_ac(b.index, -b.pd_mw - b.gs_mw * vm * vm,
              -b.qd_mvar + b.bs_mvar * vm * vm, "母线固定注入");
  }
  for (const auto& load : sys.ac.loads)
    if (load.in_service) inject_ac(load.bus, -load.p_mw * load.scaling,
                                   -load.q_mvar * load.scaling,
                                   load.name.empty() ? "负荷" : load.name);
  for (const auto& load : sys.ac.flexible_loads)
    if (load.in_service) inject_ac(load.bus,
        -value("flexible_load", "AC", load.index, "p_mw", load.p_mw),
        -value("flexible_load", "AC", load.index, "q_mvar", load.q_mvar),
        load.name.empty() ? "柔性负荷" : load.name);
  for (const auto& load : sys.ac.asymmetric_loads)
    if (load.in_service) inject_ac(load.bus,
        -value("asymmetric_load", "AC", load.index, "p_mw",
               load.pa_mw + load.pb_mw + load.pc_mw),
        -value("asymmetric_load", "AC", load.index, "q_mvar",
               load.qa_mvar + load.qb_mvar + load.qc_mvar),
        load.name.empty() ? "不对称负荷" : load.name);
  for (const auto& source : sys.ac.static_generators)
    if (source.in_service) inject_ac(source.bus,
        value("static_generator", "AC", source.index, "p_mw", source.p_mw * source.scaling),
        value("static_generator", "AC", source.index, "q_mvar", source.q_mvar * source.scaling),
        source.name.empty() ? "静态电源" : source.name);
  for (const auto& source : sys.ac.renewable_gens)
    if (source.in_service) inject_ac(source.bus,
        value("renewable_generator", "AC", source.index, "p_mw", source.p_mw),
        value("renewable_generator", "AC", source.index, "q_mvar", source.q_mvar),
        source.name.empty() ? "新能源" : source.name);
  for (const auto& source : sys.ac.pv_systems)
    if (source.in_service) inject_ac(source.bus,
        value("pv_system", "AC", source.index, "p_mw", source.p_mw),
        value("pv_system", "AC", source.index, "q_mvar", source.q_mvar),
        source.name.empty() ? "光伏" : source.name);
  for (const auto& shunt : sys.ac.shunts) {
    if (!shunt.in_service) continue;
    const double v2 = ac_vm.count(shunt.bus) ? ac_vm[shunt.bus] * ac_vm[shunt.bus] : 1.0;
    const double bs = shunt.switchable && shunt.n_steps > 0
        ? shunt.bs_per_step * shunt.current_step : shunt.bs_mvar;
    inject_ac(shunt.bus, -shunt.gs_mw * v2, bs * v2,
              shunt.name.empty() ? "并联元件" : shunt.name);
  }
  for (const auto& motor : sys.ac.motors) {
    if (!motor.in_service) continue;
    const double p = motor.efficiency > 1e-9
        ? motor.sn_mva * motor.cos_phi / motor.efficiency
        : motor.sn_mva * motor.cos_phi;
    const double shaft_p = motor.sn_mva * motor.cos_phi;
    const double q = std::sqrt(std::max(0.0, motor.sn_mva * motor.sn_mva - shaft_p * shaft_p));
    inject_ac(motor.bus, -p, -q, motor.name.empty() ? "电动机" : motor.name);
  }
  for (const auto& station : sys.ac.charging_stations) {
    if (!station.in_service) continue;
    const double p = station.p_total_kw > 0.0
        ? station.p_total_kw / 1000.0
        : station.max_power_kw * station.utilization_rate *
              station.simultaneity_factor / 1000.0;
    inject_ac(station.bus, -p, -station.q_total_kvar / 1000.0,
              station.name.empty() ? "充电站" : station.name);
  }
  for (const auto& storage : sys.mobile_storage)
    if (storage.in_service) inject_ac(storage.bus,
        value("mobile_storage", "AC", storage.index, "p_mw", storage.p_mw),
        value("mobile_storage", "AC", storage.index, "q_mvar", storage.q_mvar),
        storage.name.empty() ? "移动储能" : storage.name);
  for (const auto& vpp : sys.vpps)
    if (vpp.in_service) inject_ac(vpp.pcc_bus,
        value("vpp", "AC", vpp.index, "p_mw", vpp.p_output_mw),
        value("vpp", "AC", vpp.index, "q_mvar", vpp.q_output_mvar),
        vpp.name.empty() ? "虚拟电厂" : vpp.name);
  for (const auto& microgrid : sys.microgrids)
    if (microgrid.in_service) inject_ac(microgrid.pcc_bus,
        -value("microgrid", "AC", microgrid.index, "p_mw", microgrid.p_exchange_mw),
        0.0, microgrid.name.empty() ? "微网" : microgrid.name);
  for (const auto& b : sys.dc.buses)
    if (b.in_service) inject_dc(b.index, -b.pd_mw, "DC母线固定负荷");
  for (const auto& load : sys.dc.loads)
    if (load.in_service) inject_dc(load.bus, -load.p_mw * load.scaling,
                                   load.name.empty() ? "DC负荷" : load.name);
  for (const auto& source : sys.dc.pv_arrays)
    if (source.in_service) inject_dc(source.bus,
        value("dc_pv_array", "DC", source.index, "p_mw", source.p_set_mw),
        source.name.empty() ? "DC光伏" : source.name);
  for (const auto& source : sys.dc.static_generators)
    if (source.in_service) inject_dc(source.bus,
        value("static_generator", "DC", source.index, "p_mw", source.p_mw * source.scaling),
        source.name.empty() ? "DC静态电源" : source.name);
  for (const auto& source : sys.dc.dc_static_generators)
    if (source.in_service) inject_dc(source.bus,
        value("dc_static_generator", "DC", source.index, "p_mw",
              source.p_set_mw * source.scaling),
        source.name.empty() ? "DC静态电源" : source.name);

  json out{{"basis", "canonical_projection_with_rich_terminal_attribution"},
           {"tolerance_kw", 1.0}, {"ordinary", json::array()},
           {"sources", json::array()}, {"all_buses", json::array()}};
  auto add_row = [&](const std::string& domain, int bus, const std::string& type,
                     const std::string& name, Ledger ledger, bool slack) {
    if (slack) {
      const double correction_p = ledger.export_p - ledger.injection_p;
      const double correction_q = ledger.export_q - ledger.injection_q;
      if (std::abs(correction_p) > 1e-6 || std::abs(correction_q) > 1e-6) {
        ledger.injection_p += correction_p;
        ledger.injection_q += correction_q;
        add_detail(ledger,
                   domain == "DC" ? "DC_V平衡修正" : "Slack数值闭合修正",
                   correction_p, correction_q, true);
      }
    }
    const double rp = ledger.injection_p - ledger.export_p;
    const double rq = ledger.injection_q - ledger.export_q;
    json row{{"kind", domain}, {"domain", domain}, {"id", bus}, {"bus", bus},
             {"type", type}, {"bus_type", type}, {"name", name},
             {"residual_mw", rp}, {"residual_kw", rp * 1000.0},
             {"residual_mvar", rq}, {"residual_kvar", rq * 1000.0},
             {"net_injection_mw", ledger.injection_p},
             {"net_injection_mvar", ledger.injection_q},
             {"terminal_export_mw", ledger.export_p},
             {"terminal_export_mvar", ledger.export_q}, {"details", ledger.details}};
    out["all_buses"].push_back(row);
    if (!slack && (std::abs(rp) > 1e-3 || std::abs(rq) > 1e-3))
      out["ordinary"].push_back(row);
    if (slack && (std::abs(ledger.injection_p) > 1e-3 ||
                  std::abs(ledger.injection_q) > 1e-3)) {
      json source = row;
      source["source_mw"] = ledger.injection_p;
      source["source_kw"] = ledger.injection_p * 1000.0;
      source["source_mvar"] = ledger.injection_q;
      source["source_kvar"] = ledger.injection_q * 1000.0;
      out["sources"].push_back(std::move(source));
    }
  };
  for (const auto& b : sys.ac.buses) {
    if (!b.in_service) continue;
    const bool slack = b.bus_type == hacdcpf::BusType::SLACK ||
        std::any_of(sys.ac.external_grids.begin(), sys.ac.external_grids.end(),
                    [&](const auto& grid) { return grid.in_service && grid.bus == b.index; });
    add_row("AC", b.index, hacdcpf::bus_type_str(b.bus_type),
            b.name.empty() ? "Bus " + std::to_string(b.index) : b.name,
            ac[b.index], slack);
  }
  for (const auto& b : sys.dc.buses) {
    if (!b.in_service) continue;
    add_row("DC", b.index,
            b.bus_type == hacdcpf::DCBusType::DC_V ? "DC_V" : "DC_P",
            b.name.empty() ? "DC Bus " + std::to_string(b.index) : b.name,
            dc[b.index], b.bus_type == hacdcpf::DCBusType::DC_V);
  }
  out["ordinary_bad_count"] = out["ordinary"].size();
  out["source_count"] = out["sources"].size();
  return out;
}

std::optional<double> attributed_active_power_mw(
    const hacdcpf::projection::RichComponentResult& row) {
  const auto value = std::find_if(
      row.values.begin(), row.values.end(), [](const auto& item) {
        return item.name == "p_mw";
      });
  if (value != row.values.end()) return value->value;
  const auto terminal = std::find_if(
      row.terminals.begin(), row.terminals.end(), [](const auto& item) {
        return item.has_p &&
               (item.name == "ac" || item.name == "dc" ||
                item.name == "from");
      });
  if (terminal != row.terminals.end()) return terminal->p_mw;
  return std::nullopt;
}

json rich_component_power_series_json(
    const std::vector<hacdcpf::projection::RichResultAttribution>& steps,
    const std::unordered_set<std::string>& component_types) {
  struct Series {
    std::string component_type;
    std::string domain;
    int component_index{0};
    std::string name;
    std::string recovery_class;
    std::vector<double> values;
  };
  std::map<std::string, Series> series;
  for (size_t t = 0; t < steps.size(); ++t) {
    for (const auto& row : steps[t].components) {
      if (!component_types.count(row.component_type)) continue;
      const auto p_mw = attributed_active_power_mw(row);
      if (!p_mw) continue;
      const std::string key = row.component_type + "\n" + row.domain + "\n" +
                              std::to_string(row.component_index);
      auto& target = series[key];
      if (target.values.empty()) {
        target.component_type = row.component_type;
        target.domain = row.domain;
        target.component_index = row.component_index;
        target.name = row.name;
        target.recovery_class =
            hacdcpf::projection::recovery_class_name(row.recovery);
        target.values.assign(steps.size(), 0.0);
      }
      target.values[t] = *p_mw;
    }
  }
  json out = json::array();
  for (auto& [key, item] : series) {
    (void)key;
    out.push_back(json{{"canvas_type", item.component_type},
                       {"domain", item.domain},
                       {"canvas_index", item.component_index},
                       {"name", item.name},
                       {"recovery_class", item.recovery_class},
                       {"quantity", "p_mw"},
                       {"sign_convention", "positive_injection_into_network"},
                       {"values", std::move(item.values)}});
  }
  return out;
}

struct VoltageQualificationMetrics {
  std::size_t ac_samples{0};
  std::size_t ac_qualified{0};
  std::size_t dc_samples{0};
  std::size_t dc_qualified{0};

  std::size_t samples() const { return ac_samples + dc_samples; }
  std::size_t qualified() const { return ac_qualified + dc_qualified; }
};

void accumulate_voltage_qualification(
    VoltageQualificationMetrics& metrics,
    const hacdcpf::HybridPowerSystem& sys,
    const std::vector<double>& vm,
    const std::vector<double>& vdc) {
  for (std::size_t i = 0; i < sys.ac.buses.size() && i < vm.size(); ++i) {
    const auto& bus = sys.ac.buses[i];
    if (!bus.in_service || !std::isfinite(vm[i])) continue;
    ++metrics.ac_samples;
    if (vm[i] >= bus.vmin_pu && vm[i] <= bus.vmax_pu) ++metrics.ac_qualified;
  }
  for (std::size_t i = 0; i < sys.dc.buses.size() && i < vdc.size(); ++i) {
    const auto& bus = sys.dc.buses[i];
    if (!bus.in_service || !std::isfinite(vdc[i])) continue;
    ++metrics.dc_samples;
    if (vdc[i] >= bus.vmin_pu && vdc[i] <= bus.vmax_pu) ++metrics.dc_qualified;
  }
}

json voltage_qualification_json(const VoltageQualificationMetrics& metrics) {
  const auto rate = [](std::size_t qualified, std::size_t samples) -> json {
    return samples ? json(100.0 * static_cast<double>(qualified) /
                          static_cast<double>(samples))
                   : json(nullptr);
  };
  return json{{"qualified_samples", metrics.qualified()},
              {"total_samples", metrics.samples()},
              {"rate_pct", rate(metrics.qualified(), metrics.samples())},
              {"ac_qualified_samples", metrics.ac_qualified},
              {"ac_total_samples", metrics.ac_samples},
              {"ac_rate_pct", rate(metrics.ac_qualified, metrics.ac_samples)},
              {"dc_qualified_samples", metrics.dc_qualified},
              {"dc_total_samples", metrics.dc_samples},
              {"dc_rate_pct", rate(metrics.dc_qualified, metrics.dc_samples)}};
}

double elapsed_seconds(std::chrono::steady_clock::time_point started) {
  return std::chrono::duration<double>(std::chrono::steady_clock::now() - started).count();
}

std::string sc_fault_type_name(hacdcpf::analysis::FaultType ft) {
  switch (ft) {
    case hacdcpf::analysis::FaultType::ThreePhase: return "ThreePhase";
    case hacdcpf::analysis::FaultType::SinglePhaseGround: return "SinglePhaseGround";
    case hacdcpf::analysis::FaultType::TwoPhase: return "TwoPhase";
    case hacdcpf::analysis::FaultType::TwoPhaseGround: return "TwoPhaseGround";
  }
  return "ThreePhase";
}

std::string sc_calc_type_name(hacdcpf::analysis::SCCalcType ct) {
  return ct == hacdcpf::analysis::SCCalcType::Min ? "Min" : "Max";
}

std::string sc_kappa_method_name(hacdcpf::analysis::SCKappaMethod km) {
  switch (km) {
    case hacdcpf::analysis::SCKappaMethod::A: return "A";
    case hacdcpf::analysis::SCKappaMethod::B: return "B";
    case hacdcpf::analysis::SCKappaMethod::C: return "C";
  }
  return "C";
}

std::string sc_topology_name(hacdcpf::analysis::SCTopology top) {
  return top == hacdcpf::analysis::SCTopology::Radial ? "Radial" : "Meshed";
}

json sc_options_to_json(const hacdcpf::analysis::SCDetailedOptions& opt) {
  return json{
      {"fault_type", sc_fault_type_name(opt.fault_type)},
      {"calc_type", sc_calc_type_name(opt.calc_type)},
      {"kappa_method", sc_kappa_method_name(opt.kappa_method)},
      {"topology", sc_topology_name(opt.topology)},
      {"c_factor", opt.c_factor},
      {"fault_impedance_pu", opt.fault_impedance_pu},
      {"breaking_time_s", opt.breaking_time_s},
      {"base_frequency_hz", opt.base_frequency_hz},
      {"default_xdpp", opt.default_xdpp},
      {"compute_branch_flows", opt.compute_branch_flows},
      {"compute_voltage_drops", opt.compute_voltage_drops},
      {"compute_ith", opt.compute_ith},
      {"ith_duration_s", opt.ith_duration_s},
  };
}

json dc_sc_options_to_json(const hacdcpf::analysis::DCFaultOptions& opt) {
  return json{
      {"fault_resistance_pu", opt.fault_resistance_pu},
      {"source_voltage_pu", opt.source_voltage_pu},
      {"consider_dc_breakers", opt.consider_dc_breakers},
      {"dc_breakers_control_branches", opt.dc_breakers_control_branches},
      {"add_unassigned_closed_breaker_edges", opt.add_unassigned_closed_breaker_edges},
      {"min_closed_breaker_resistance_pu", opt.min_closed_breaker_resistance_pu},
  };
}

void apply_dc_sc_request_options(const json& root,
                                 hacdcpf::analysis::DCFaultOptions& opt) {
  const json* o = &root;
  if (root.contains("options") && root["options"].is_object()) {
    o = &root["options"];
  }
  if (o->contains("fault_resistance_pu") && (*o)["fault_resistance_pu"].is_number()) {
    opt.fault_resistance_pu = (*o)["fault_resistance_pu"].get<double>();
  }
  if (o->contains("source_voltage_pu") && (*o)["source_voltage_pu"].is_number()) {
    opt.source_voltage_pu = (*o)["source_voltage_pu"].get<double>();
  }
  if (o->contains("consider_dc_breakers") && (*o)["consider_dc_breakers"].is_boolean()) {
    opt.consider_dc_breakers = (*o)["consider_dc_breakers"].get<bool>();
  }
  if (o->contains("dc_breakers_control_branches") &&
      (*o)["dc_breakers_control_branches"].is_boolean()) {
    opt.dc_breakers_control_branches = (*o)["dc_breakers_control_branches"].get<bool>();
  }
  if (o->contains("add_unassigned_closed_breaker_edges") &&
      (*o)["add_unassigned_closed_breaker_edges"].is_boolean()) {
    opt.add_unassigned_closed_breaker_edges =
        (*o)["add_unassigned_closed_breaker_edges"].get<bool>();
  }
  if (o->contains("min_closed_breaker_resistance_pu") &&
      (*o)["min_closed_breaker_resistance_pu"].is_number()) {
    opt.min_closed_breaker_resistance_pu =
        (*o)["min_closed_breaker_resistance_pu"].get<double>();
  }
}

void apply_sc_request_options(const json& root,
                              hacdcpf::analysis::SCDetailedOptions& opt) {
  const json* o = &root;
  if (root.contains("options") && root["options"].is_object()) {
    o = &root["options"];
  }

  const std::string ft = o->value("fault_type", std::string("ThreePhase"));
  if (ft == "SinglePhaseGround") opt.fault_type = hacdcpf::analysis::FaultType::SinglePhaseGround;
  else if (ft == "TwoPhase") opt.fault_type = hacdcpf::analysis::FaultType::TwoPhase;
  else if (ft == "TwoPhaseGround") opt.fault_type = hacdcpf::analysis::FaultType::TwoPhaseGround;
  else opt.fault_type = hacdcpf::analysis::FaultType::ThreePhase;

  const std::string calc = o->value("calc_type", o->value("calculation_type", std::string("Max")));
  if (calc == "Min" || calc == "min" || calc == "Minimum" || calc == "minimum") {
    opt.calc_type = hacdcpf::analysis::SCCalcType::Min;
  } else {
    opt.calc_type = hacdcpf::analysis::SCCalcType::Max;
  }

  const std::string kappa =
      o->value("kappa_method", o->value("kappa", std::string("C")));
  if (kappa == "A" || kappa == "a" || kappa == "MethodA" || kappa == "method_a") {
    opt.kappa_method = hacdcpf::analysis::SCKappaMethod::A;
  } else if (kappa == "C" || kappa == "c" || kappa == "MethodC" || kappa == "method_c") {
    opt.kappa_method = hacdcpf::analysis::SCKappaMethod::C;
  } else {
    opt.kappa_method = hacdcpf::analysis::SCKappaMethod::B;
  }

  const std::string topology = o->value("topology", std::string("Meshed"));
  if (topology == "Radial" || topology == "radial" || topology == "Tree" || topology == "tree") {
    opt.topology = hacdcpf::analysis::SCTopology::Radial;
  } else {
    opt.topology = hacdcpf::analysis::SCTopology::Meshed;
  }

  if (o->contains("c_factor") && (*o)["c_factor"].is_number()) {
    opt.c_factor = (*o)["c_factor"].get<double>();
  }
  if (o->contains("fault_impedance_pu") && (*o)["fault_impedance_pu"].is_number()) {
    opt.fault_impedance_pu = (*o)["fault_impedance_pu"].get<double>();
  }
  if (o->contains("breaking_time_s") && (*o)["breaking_time_s"].is_number()) {
    opt.breaking_time_s = (*o)["breaking_time_s"].get<double>();
  }
  if (o->contains("base_frequency_hz") && (*o)["base_frequency_hz"].is_number()) {
    opt.base_frequency_hz = (*o)["base_frequency_hz"].get<double>();
  }
  if (o->contains("default_xdpp") && (*o)["default_xdpp"].is_number()) {
    opt.default_xdpp = (*o)["default_xdpp"].get<double>();
  }
  if (o->contains("compute_branch_flows") && (*o)["compute_branch_flows"].is_boolean()) {
    opt.compute_branch_flows = (*o)["compute_branch_flows"].get<bool>();
  }
  if (o->contains("compute_voltage_drops") && (*o)["compute_voltage_drops"].is_boolean()) {
    opt.compute_voltage_drops = (*o)["compute_voltage_drops"].get<bool>();
  }
  if (o->contains("compute_ith") && (*o)["compute_ith"].is_boolean()) {
    opt.compute_ith = (*o)["compute_ith"].get<bool>();
  }
  if (o->contains("ith_duration_s") && (*o)["ith_duration_s"].is_number()) {
    opt.ith_duration_s = (*o)["ith_duration_s"].get<double>();
  }
}

void apply_replay_zip_and_solver_flags(hacdcpf::powerflow::SolverData& data,
                                       const hacdcpf::PowerFlowOptions& opt) {
  for (int k = 0; k < 3; ++k) {
    data.zip_pw[k] = opt.zip_pw[k];
    data.zip_qw[k] = opt.zip_qw[k];
  }
  data.enable_coupled_jacobian = opt.enable_coupled_jacobian;
  data.enable_augmented_equations = opt.enable_augmented_equations;
  data.enable_semi_smooth_newton = opt.enable_semi_smooth_newton;
}

std::string pf_loss_model_name(hacdcpf::LossModelType loss_model) {
  return loss_model == hacdcpf::LossModelType::CurrentBased ? "current_based" : "linear";
}

std::string pf_globalization_name(hacdcpf::PowerFlowOptions::GlobalizationStrategy strategy) {
  using GS = hacdcpf::PowerFlowOptions::GlobalizationStrategy;
  switch (strategy) {
    case GS::TrustRegion: return "trust_region";
    case GS::PseudoTransient: return "pseudo_transient";
    case GS::LineSearch: return "line_search";
  }
  return "line_search";
}

void set_if_bool(const json& o, const char* key, bool& target) {
  if (o.contains(key) && o[key].is_boolean()) target = o[key].get<bool>();
}

void set_if_int(const json& o, const char* key, int& target) {
  if (o.contains(key) && o[key].is_number()) target = o[key].get<int>();
}

void set_if_double(const json& o, const char* key, double& target) {
  if (o.contains(key) && o[key].is_number()) target = o[key].get<double>();
}

void apply_pf_robust_options(const json& o,
                             hacdcpf::powerflow::RobustNonlinearOptions& opt) {
  set_if_bool(o, "enable_residual_scaling", opt.enable_residual_scaling);
  set_if_bool(o, "enable_variable_scaling", opt.enable_variable_scaling);
  set_if_bool(o, "enable_jacobian_row_col_equilibration",
              opt.enable_jacobian_row_col_equilibration);
  set_if_bool(o, "enable_condition_monitor", opt.enable_condition_monitor);
  set_if_bool(o, "enable_nonmonotone_linesearch", opt.enable_nonmonotone_linesearch);
  set_if_bool(o, "enable_smooth_ncp", opt.enable_smooth_ncp);
  set_if_bool(o, "enable_activity_hysteresis", opt.enable_activity_hysteresis);
  set_if_bool(o, "enable_lm_trust_region_fallback",
              opt.enable_lm_trust_region_fallback);
  set_if_bool(o, "enable_ptc_ser", opt.enable_ptc_ser);
  set_if_bool(o, "enable_homotopy", opt.enable_homotopy);
  set_if_bool(o, "enable_log_voltage", opt.enable_log_voltage);
  set_if_bool(o, "auto_enable_log_voltage_on_failure",
              opt.auto_enable_log_voltage_on_failure);
  set_if_bool(o, "enable_newton_krylov_fallback",
              opt.enable_newton_krylov_fallback);
  set_if_bool(o, "enable_schur_preconditioner", opt.enable_schur_preconditioner);
  set_if_bool(o, "enable_auto_fallback_scheduling",
              opt.enable_auto_fallback_scheduling);

  set_if_double(o, "min_scale", opt.min_scale);
  set_if_double(o, "max_scale", opt.max_scale);
  set_if_double(o, "min_vm_pu", opt.min_vm_pu);
  set_if_double(o, "min_branch_x_pu", opt.min_branch_x_pu);
  set_if_double(o, "bad_condition_threshold", opt.bad_condition_threshold);
  set_if_double(o, "tiny_pivot_threshold", opt.tiny_pivot_threshold);
  set_if_int(o, "nonmonotone_window", opt.nonmonotone_window);
  set_if_double(o, "armijo_c", opt.armijo_c);
  set_if_double(o, "line_search_beta", opt.line_search_beta);
  set_if_int(o, "max_line_search_trials", opt.max_line_search_trials);
  set_if_double(o, "ncp_mu0", opt.ncp_mu0);
  set_if_double(o, "ncp_mu_min", opt.ncp_mu_min);
  set_if_double(o, "ncp_mu_factor", opt.ncp_mu_factor);
  set_if_double(o, "ncp_mu_factor_coarse", opt.ncp_mu_factor_coarse);
  set_if_double(o, "ncp_mu_phase_transition", opt.ncp_mu_phase_transition);
  set_if_int(o, "min_active_set_hold_iters", opt.min_active_set_hold_iters);
  set_if_double(o, "q_limit_hysteresis", opt.q_limit_hysteresis);
  set_if_double(o, "lm_lambda0", opt.lm_lambda0);
  set_if_double(o, "lm_lambda_min", opt.lm_lambda_min);
  set_if_double(o, "lm_lambda_max", opt.lm_lambda_max);
  set_if_double(o, "trust_region_radius0", opt.trust_region_radius0);
  set_if_double(o, "trust_region_radius_min", opt.trust_region_radius_min);
  set_if_double(o, "trust_region_radius_max", opt.trust_region_radius_max);
  set_if_double(o, "ptc_dt0", opt.ptc_dt0);
  set_if_double(o, "ptc_dt_min", opt.ptc_dt_min);
  set_if_double(o, "ptc_dt_max", opt.ptc_dt_max);
  set_if_double(o, "ptc_gamma", opt.ptc_gamma);
  set_if_double(o, "homotopy_step0", opt.homotopy_step0);
  set_if_double(o, "homotopy_step_min", opt.homotopy_step_min);
  set_if_double(o, "homotopy_step_max", opt.homotopy_step_max);
  set_if_int(o, "homotopy_max_steps", opt.homotopy_max_steps);
  set_if_double(o, "nk_condition_trigger", opt.nk_condition_trigger);
  set_if_int(o, "gmres_restart", opt.gmres_restart);
  set_if_int(o, "gmres_max_outer", opt.gmres_max_outer);
  set_if_double(o, "gmres_tol", opt.gmres_tol);
}

void apply_power_flow_request_options(const json& root, hacdcpf::PowerFlowOptions& opt) {
  const json* o = &root;
  if (root.contains("options") && root["options"].is_object()) {
    o = &root["options"];
  }

  set_if_int(*o, "max_iter", opt.max_iter);
  set_if_double(*o, "tol", opt.tol);
  set_if_int(*o, "fdpf_max_iter", opt.fdpf_max_iter);
  set_if_bool(*o, "enable_pv_pq_conversion", opt.enable_pv_pq_conversion);
  set_if_bool(*o, "enable_auto_swing_selection", opt.enable_auto_swing_selection);
  set_if_bool(*o, "enable_converter_mode_switching",
              opt.enable_converter_mode_switching);
  set_if_bool(*o, "enable_converter_coordination_check",
              opt.enable_converter_coordination_check);
  set_if_bool(*o, "enforce_converter_physical_limits",
              opt.enforce_converter_physical_limits);
  set_if_bool(*o, "enable_rigid_vdc_former", opt.enable_rigid_vdc_former);
  set_if_bool(*o, "verbose", opt.verbose);
  set_if_bool(*o, "enable_solver_profiling", opt.enable_solver_profiling);
  set_if_bool(*o, "enable_iteration_log", opt.enable_iteration_log);
  set_if_int(*o, "ac_eval_threads", opt.ac_eval_threads);

  set_if_double(*o, "pv_q_hysteresis_pu", opt.pv_q_hysteresis_pu);
  set_if_double(*o, "pv_recover_vm_tol_pu", opt.pv_recover_vm_tol_pu);
  set_if_double(*o, "max_delta_va_rad", opt.max_delta_va_rad);
  set_if_double(*o, "max_delta_vm_pu", opt.max_delta_vm_pu);
  set_if_double(*o, "max_delta_vdc_pu", opt.max_delta_vdc_pu);
  set_if_int(*o, "max_line_search_steps", opt.max_line_search_steps);
  set_if_int(*o, "max_regularization_steps", opt.max_regularization_steps);
  set_if_double(*o, "regularization_lambda0", opt.regularization_lambda0);
  set_if_double(*o, "regularization_growth", opt.regularization_growth);
  set_if_double(*o, "converter_vdc_switch_high_pu",
                opt.converter_vdc_switch_high_pu);
  set_if_double(*o, "converter_vdc_switch_low_pu",
                opt.converter_vdc_switch_low_pu);
  set_if_int(*o, "mode_hysteresis_iters", opt.mode_hysteresis_iters);
  set_if_bool(*o, "enable_coupled_jacobian", opt.enable_coupled_jacobian);
  set_if_bool(*o, "enable_augmented_equations", opt.enable_augmented_equations);
  set_if_bool(*o, "enable_semi_smooth_newton", opt.enable_semi_smooth_newton);

  if (o->contains("loss_model") && (*o)["loss_model"].is_string()) {
    const std::string lm = (*o)["loss_model"].get<std::string>();
    opt.loss_model = lm == "current_based"
        ? hacdcpf::LossModelType::CurrentBased
        : hacdcpf::LossModelType::Linear;
  }

  if (o->contains("globalization") && (*o)["globalization"].is_string()) {
    const std::string glob = (*o)["globalization"].get<std::string>();
    using GS = hacdcpf::PowerFlowOptions::GlobalizationStrategy;
    if (glob == "trust_region") opt.globalization = GS::TrustRegion;
    else if (glob == "pseudo_transient") opt.globalization = GS::PseudoTransient;
    else opt.globalization = GS::LineSearch;
  }
  set_if_double(*o, "trust_region_radius0", opt.trust_region_radius0);
  set_if_double(*o, "trust_region_max", opt.trust_region_max);
  set_if_double(*o, "ptc_delta0", opt.ptc_delta0);
  set_if_double(*o, "ptc_growth", opt.ptc_growth);

  if (o->contains("zip_pw") && (*o)["zip_pw"].is_array()) {
    const auto& arr = (*o)["zip_pw"];
    for (size_t k = 0; k < arr.size() && k < 3; ++k)
      if (arr[k].is_number()) opt.zip_pw[k] = arr[k].get<double>();
  }
  if (o->contains("zip_qw") && (*o)["zip_qw"].is_array()) {
    const auto& arr = (*o)["zip_qw"];
    for (size_t k = 0; k < arr.size() && k < 3; ++k)
      if (arr[k].is_number()) opt.zip_qw[k] = arr[k].get<double>();
  }

  if (o->contains("robust_nonlinear") && (*o)["robust_nonlinear"].is_object()) {
    apply_pf_robust_options((*o)["robust_nonlinear"], opt.robust_nonlinear);
  }
}

