const json* parameter_json_path(const json& root, const std::string& path) {
  const json* current = &root;
  size_t begin = 0;
  while (begin < path.size()) {
    const size_t end = path.find('.', begin);
    const std::string key = path.substr(begin, end - begin);
    if (!current->is_object() || !current->contains(key)) return nullptr;
    current = &current->at(key);
    if (end == std::string::npos) break;
    begin = end + 1;
  }
  return current;
}

std::string parameter_field_group(const std::string& field) {
  const std::string lower = [&] {
    std::string value = field;
    std::transform(value.begin(), value.end(), value.begin(),
                   [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
    return value;
  }();
  if (lower == "index" || lower == "name" || lower.find("bus") != std::string::npos ||
      lower.find("terminal") != std::string::npos || lower.find("winding") != std::string::npos)
    return "identity_connection";
  if (lower.find("reliab") != std::string::npos || lower.find("failure") != std::string::npos ||
      lower.find("outage") != std::string::npos || lower.find("mttr") != std::string::npos ||
      lower.find("mtbf") != std::string::npos || lower.find("repair") != std::string::npos)
    return "reliability";
  if (lower.rfind("dynamic_model", 0) == 0 || lower.find("inertia") != std::string::npos ||
      lower.find("damping") != std::string::npos || lower.find("time_constant") != std::string::npos)
    return "dynamics";
  if (lower.find("control") != std::string::npos || lower.find("tap") != std::string::npos ||
      lower.find("mode") != std::string::npos || lower.find("closed") != std::string::npos ||
      lower.find("enabled") != std::string::npos || lower.find("in_service") != std::string::npos ||
      lower.find("status") != std::string::npos || lower.find("dispatch") != std::string::npos)
    return "operation_control";
  if (lower.find("rated") != std::string::npos || lower.find("rate_") != std::string::npos ||
      lower.find("capacity") != std::string::npos || lower.find("max") != std::string::npos ||
      lower.find("min") != std::string::npos || lower.find("limit") != std::string::npos)
    return "rating_limits";
  if (lower.find("cost") != std::string::npos || lower.find("price") != std::string::npos ||
      lower.find("emission") != std::string::npos || lower.find("carbon") != std::string::npos)
    return "cost_carbon";
  return "electrical_physical";
}

std::string parameter_field_unit(const std::string& field) {
  const auto ends_with = [&](const std::string& suffix) {
    return field.size() >= suffix.size() &&
           field.compare(field.size() - suffix.size(), suffix.size(), suffix) == 0;
  };
  if (field.find("tco2_mwh") != std::string::npos) return "tCO2/MWh";
  if (field.find("kg_mwh") != std::string::npos) return "kg/MWh";
  if (field.find("mwh_per_km") != std::string::npos) return "MWh/km";
  if (field.find("mw_per_h") != std::string::npos) return "MW/h";
  if (field.find("per_mwh") != std::string::npos) return "currency/MWh";
  if (field == "cost_c0") return "currency/h";
  if (field == "cost_c1") return "currency/MWh";
  if (field == "cost_c2") return "currency/(MW^2 h)";
  if (field.find("failure_rate_per_year") != std::string::npos ||
      field == "failure_rate") return "occ/year";
  if (field.find("probability") != std::string::npos ||
      field.find("fraction") != std::string::npos ||
      field.find("efficiency") != std::string::npos ||
      field.find("forced_outage_rate") != std::string::npos ||
      field.rfind("eta", 0) == 0) return "pu";
  if (ends_with("_mvar")) return "MVar";
  if (ends_with("_mva")) return "MVA";
  if (ends_with("_mwh")) return "MWh";
  if (ends_with("_mw")) return "MW";
  if (ends_with("_kv")) return "kV";
  if (ends_with("_ka")) return "kA";
  if (ends_with("_amps") || ends_with("_a")) return "A";
  if (ends_with("_hz")) return "Hz";
  if (ends_with("_ohm")) return "ohm";
  if (ends_with("_km")) return "km";
  if (ends_with("_deg")) return "deg";
  if (ends_with("_percent") || ends_with("_pct")) return "%";
  if (ends_with("_hours") || ends_with("_hr")) return "h";
  if (ends_with("_ms")) return "ms";
  if (ends_with("_s")) return "s";
  if (ends_with("_pu") || field == "eta" || field.rfind("soc_", 0) == 0)
    return "pu";
  return "";
}

void flatten_parameter_fields(const json& value, const std::string& prefix,
                              json& fields) {
  if (value.is_object()) {
    for (auto it = value.begin(); it != value.end(); ++it) {
      const std::string name = prefix.empty() ? it.key() : prefix + "." + it.key();
      flatten_parameter_fields(it.value(), name, fields);
    }
    return;
  }
  json display_value = value;
  std::string value_type = value.type_name();
  if (value.is_array()) {
    display_value = value.dump();
    value_type = "array";
  }
  fields.push_back({{"field", prefix},
                    {"value", std::move(display_value)},
                    {"value_type", value_type},
                    {"group", parameter_field_group(prefix)},
                    {"unit", parameter_field_unit(prefix)},
                    {"source", "authored_system_json"},
                    {"editable", false}});
}

json parameter_model_catalog_json(
    const hacdcpf::StandardParameterLibrary& library) {
  json catalog = json::array();
  for (const auto& descriptor : parameter_model_descriptors()) {
    json entry{{"id", descriptor.component_type},
               {"component_type", descriptor.component_type},
               {"title", descriptor.title},
               {"model_scope", descriptor.scope},
               {"equivalent_circuit_family", descriptor.circuit_family},
               {"equivalent_circuit_caption", descriptor.circuit_caption},
               {"domain", descriptor.domain},
               {"component_kind", descriptor.component_kind},
               {"rule_ids", json::array()}};
    for (const auto& rule : library.rules) {
      if (rule.component_type == descriptor.component_type)
        entry["rule_ids"].push_back(rule.id);
    }
    catalog.push_back(std::move(entry));
  }
  return catalog;
}

json parameter_model_instances_json(const hacdcpf::HybridPowerSystem* system,
                                    const hacdcpf::StandardParameterLibrary& library) {
  json instances = json::array();
  if (system == nullptr) return instances;
  const json root = json::parse(hacdcpf::io::to_json(*system, -1));

  const auto append = [&](const ParameterModelDescriptor& descriptor,
                          const json& authored, size_t position,
                          const std::string& component_type = "") {
    const int index = authored.value("index", static_cast<int>(position));
    const std::string type = component_type.empty()
                                 ? descriptor.component_type : component_type;
    const std::string name = authored.value("name", type + " " + std::to_string(index));
    json model_parameters = json::array();
    flatten_parameter_fields(authored, "", model_parameters);
    json values = json::object();
    for (const auto& rule : library.rules) {
      if (rule.component_type != type) continue;
      const auto found = std::find_if(model_parameters.begin(), model_parameters.end(),
                                      [&](const auto& field) {
                                        return field.value("field", "") == rule.parameter;
                                      });
      if (found != model_parameters.end()) values[rule.id] = found->at("value");
    }
    instances.push_back({
        {"identity", std::string(descriptor.domain) + ":" + descriptor.component_kind +
                         ":" + std::to_string(index)},
        {"component_type", type},
        {"component_kind", descriptor.component_kind},
        {"reliability_kind", descriptor.reliability_kind},
        {"domain", descriptor.domain},
        {"component_index", index},
        {"component_position", position},
        {"component_name", name},
        {"in_service", authored.value("in_service", authored.value("enabled", true))},
        {"values", std::move(values)},
        {"model_parameters", std::move(model_parameters)},
        {"reliability_modes", json::array()},
    });
  };

  const auto& descriptors = parameter_model_descriptors();
  append(descriptors.front(), json{{"base_mva", system->base_mva},
                                    {"frequency_hz", system->ac.freq_hz},
                                    {"name", system->name}, {"index", 0}}, 0);
  for (size_t d = 1; d < descriptors.size(); ++d) {
    const auto* rows = parameter_json_path(root, descriptors[d].json_path);
    if (rows == nullptr || !rows->is_array()) continue;
    for (size_t position = 0; position < rows->size(); ++position) {
      const auto& authored = rows->at(position);
      std::string type;
      if (std::string(descriptors[d].component_type) == "AC branch" &&
          (authored.value("sn_mva", 0.0) > 1e-12 ||
           authored.value("vn_hv_kv", 0.0) > 1e-12 ||
           authored.value("vn_lv_kv", 0.0) > 1e-12)) {
        type = "Transformer";
      }
      append(descriptors[d], authored, position, type);
    }
  }
  return instances;
}

static json reliability_configuration_to_json(
    const hacdcpf::HybridPowerSystem& sys,
    const hacdcpf::analysis::ReliabilityConfiguration& configuration);

json parameter_library_to_json(
    const hacdcpf::StandardParameterLibrary& library,
    bool include_profiles = true,
    const hacdcpf::HybridPowerSystem* system = nullptr,
    const hacdcpf::analysis::ReliabilityConfiguration* reliability_configuration = nullptr) {
  json rules = json::array();
  for (const auto& rule : library.rules) {
    rules.push_back(parameter_rule_to_json(rule));
  }
  json out{{"profile_id", library.profile_id},
           {"name", library.name},
           {"version", library.version},
           {"description", library.description},
           {"rules", std::move(rules)}};
  out["effective_parameters"] = effective_parameter_library_json(library);
  out["model_catalog"] = parameter_model_catalog_json(library);
  out["parameter_instances"] = parameter_model_instances_json(system, library);
  out["reliability_parameter_schema"] = json::array();
  if (system != nullptr) {
    const hacdcpf::analysis::ReliabilityConfiguration empty_configuration;
    const auto& configuration = reliability_configuration != nullptr
                                    ? *reliability_configuration
                                    : empty_configuration;
    const json reliability = reliability_configuration_to_json(*system, configuration);
    out["reliability_parameter_schema"] = reliability.at("schema").at("mode_fields");
    for (auto& instance : out["parameter_instances"]) {
      for (const auto& mode : reliability.at("effective_modes")) {
        if (mode.value("component_kind", "") == instance.value("reliability_kind", "") &&
            mode.value("component_index", -1) == instance.value("component_index", -2)) {
          instance["reliability_modes"].push_back(mode);
        }
      }
    }
  }
  out["parameter_contract"] = {
      {"registered_count", library.rules.size()},
      {"default_config", true},
      {"external_json_override", true},
      {"api_effective", true},
      {"gui_editable", true},
      {"effective_parameters_echo", true},
      {"model_catalog_count", parameter_model_descriptors().size()},
      {"reliability_integrated_by_component", true},
      {"instance_parameters_source", "hacdcpf_system_json"},
      {"sensitivity_test", "per_rule_missing_field_fill"}};
  if (include_profiles) {
    out["profiles"] = json::array();
    for (const auto& profile : hacdcpf::standard_parameter_profiles()) {
      out["profiles"].push_back(json{{"id", profile.id},
                                      {"name", profile.name},
                                      {"description", profile.description}});
    }
  }
  out["library_validation"] = parameter_validation_to_json(
      hacdcpf::validate_standard_parameter_library(library));
  return out;
}

hacdcpf::StandardParameterLibrary parameter_library_from_json(
    const json& input,
    const hacdcpf::StandardParameterLibrary& current) {
  const json& body = input.contains("library") ? input.at("library") : input;
  hacdcpf::StandardParameterLibrary library = current;
  library.name = body.value("name", library.name);
  library.version = body.value("version", library.version);
  library.description = body.value("description", library.description);
  if (!body.contains("rules") || !body.at("rules").is_array()) {
    throw std::runtime_error("Parameter library update requires a rules array");
  }
  std::unordered_set<std::string> updated;
  for (const auto& source : body.at("rules")) {
    const std::string id = source.value("id", "");
    auto* target = library.find(id);
    if (target == nullptr) {
      throw std::runtime_error("Unknown parameter rule ID: " + id);
    }
    if (!target->editable) continue;
    target->default_value = source.value("default_value", target->default_value);
    target->has_min = source.value("has_min", target->has_min);
    target->min_value = source.value("min_value", target->min_value);
    target->has_max = source.value("has_max", target->has_max);
    target->max_value = source.value("max_value", target->max_value);
    target->severity = hacdcpf::parameter_issue_severity_from_string(
        source.value("severity", std::string(hacdcpf::to_string(target->severity))));
    target->unit = source.value("unit", target->unit);
    target->source = source.value("source", target->source);
    target->description = source.value("description", target->description);
    updated.insert(id);
  }
  if (updated.size() != library.rules.size()) {
    throw std::runtime_error(
        "Parameter library update must include every rule in the active profile");
  }
  const auto validation = hacdcpf::validate_standard_parameter_library(library);
  if (!validation.ok()) {
    throw std::runtime_error(
        "Parameter library contains defaults or bounds outside its valid ranges");
  }
  return library;
}

struct Session {
  std::mutex mu;
  std::optional<hacdcpf::HybridPowerSystem> current_system;
  std::string current_name{"(none)"};
  std::optional<hacdcpf::ThreePhaseACSystem> preserved_three_phase_ac;
  std::string preserved_three_phase_source_path;
  hacdcpf::TimeSeriesData ts_data;     // time-series profile store
  std::atomic<bool> busy{false};       // true while a heavy computation runs
  std::atomic<bool> cancel{false};     // set by cancel endpoint
  // Last power flow result for carbon analysis reuse
  std::optional<hacdcpf::PowerFlowResult> last_pf_result;
  std::optional<hacdcpf::HybridPowerSystem> last_pf_system;
  std::string last_pf_method;
  std::optional<hacdcpf::TimeSeriesPFResult> last_tspf_result;
  hacdcpf::TimeSeriesData last_tspf_data;
  bool last_tspf_skip_uc{true};
  bool last_tspf_run_opf{false};
  int last_tspf_num_steps{0};
  // Serialized rich-space dynamic result used by the lazy Canvas frame API.
  // Keeping the JSON avoids retaining a second copy of large Eigen snapshots.
  std::optional<json> last_transient_result;
  // Persistent time-series binding spec — re-applied at every run_ts_pf call.
  // Survives system replacement (e.g. canvas resync via load_json_string)
  // so per-load profile mappings are not lost between set_ts_config and run.
  struct TsLoadBindingRow {
    std::string kind{"AC_LOAD"};
    int profile_id{-1};
    int load_position{-1};
    int load_index{-1};
    int bus{-1};
  };
  struct TsBindingSpec {
    bool valid = false;
    std::vector<TsLoadBindingRow> load_profile_map;
    int assign_all_loads_to = -1;
    int assign_all_pv_to = -1;
    int assign_all_renewables_to = -1;
    int assign_all_prices_to = -1;
  };
  TsBindingSpec ts_binding;
  struct ExternalGridCarbonProfile {
    int index{0};
    int bus{0};
    std::string name;
    std::vector<double> values_tco2_mwh;
  };
  std::vector<ExternalGridCarbonProfile> external_grid_carbon_profiles;
  hacdcpf::StandardParameterLibrary parameter_library{
      hacdcpf::make_standard_parameter_library()};
  hacdcpf::analysis::ReliabilityConfiguration reliability_configuration{};
};
Session g_session;

void clear_cached_analysis(Session& s) {
  s.last_pf_result.reset();
  s.last_pf_system.reset();
  s.last_pf_method.clear();
  s.last_tspf_result.reset();
  s.last_tspf_data = hacdcpf::TimeSeriesData{};
  s.last_tspf_skip_uc = true;
  s.last_tspf_run_opf = false;
  s.last_tspf_num_steps = 0;
  s.last_transient_result.reset();
}

void cache_last_power_flow(Session& s,
                           const hacdcpf::PowerFlowResult& pf,
                           const std::string& method,
                           const hacdcpf::HybridPowerSystem& sys) {
  s.last_pf_result = pf;
  s.last_pf_system = sys;
  s.last_pf_method = method;
}

void clear_preserved_three_phase(Session& s) {
  s.preserved_three_phase_ac.reset();
  s.preserved_three_phase_source_path.clear();
}

std::string gui_lower_ascii(std::string text) {
  std::transform(text.begin(), text.end(), text.begin(), [](unsigned char ch) {
    return static_cast<char>(std::tolower(ch));
  });
  return text;
}

struct GuiOpenDSSUploadProject {
  std::filesystem::path root;
  std::filesystem::path master_path;
  int file_count{0};
  std::vector<std::string> warnings;
};

std::optional<std::filesystem::path> safe_gui_upload_relative_path(
    std::string raw) {
  std::replace(raw.begin(), raw.end(), '\\', '/');
  while (!raw.empty() && raw.front() == '/') raw.erase(raw.begin());
  if (raw.empty()) return std::nullopt;

  std::filesystem::path in(raw);
  if (in.is_absolute()) return std::nullopt;

  std::filesystem::path out;
  for (const auto& part : in) {
    const std::string token = part.string();
    if (token.empty() || token == ".") continue;
    if (token == "..") return std::nullopt;
    out /= token;
  }
  if (out.empty()) return std::nullopt;
  return out;
}

std::string gui_json_string_field(const json& j,
                                  std::initializer_list<const char*> keys) {
  for (const char* key : keys) {
    auto it = j.find(key);
    if (it != j.end() && it->is_string()) return it->get<std::string>();
  }
  return {};
}

std::optional<GuiOpenDSSUploadProject> materialize_gui_opendss_upload_project(
    const json& request) {
  const json* files_json = nullptr;
  for (const char* key : {"project_files", "opendss_files", "files"}) {
    auto it = request.find(key);
    if (it != request.end() && it->is_array() && !it->empty()) {
      files_json = &*it;
      break;
    }
  }
  if (files_json == nullptr) return std::nullopt;

  struct UploadedFile {
    std::filesystem::path rel;
    std::string name;
    std::string content;
  };
  std::vector<UploadedFile> files;
  files.reserve(files_json->size());
  std::vector<std::string> warnings;

  for (const auto& item : *files_json) {
    if (!item.is_object()) continue;
    std::string raw_path =
        gui_json_string_field(item, {"path", "relative_path", "webkitRelativePath", "name"});
    std::string content =
        gui_json_string_field(item, {"content", "text", "dss_string"});
    if (raw_path.empty()) {
      warnings.push_back("OpenDSS upload entry skipped because it has no path/name.");
      continue;
    }
    auto rel = safe_gui_upload_relative_path(raw_path);
    if (!rel.has_value()) {
      warnings.push_back("OpenDSS upload entry skipped because its path is unsafe: " +
                         raw_path);
      continue;
    }
    UploadedFile file;
    file.rel = *rel;
    file.name = file.rel.filename().string();
    file.content = std::move(content);
    files.push_back(std::move(file));
  }
  if (files.empty()) return std::nullopt;

  static std::atomic<unsigned long long> upload_counter{0};
  const auto stamp = std::chrono::steady_clock::now().time_since_epoch().count();
  const auto root = std::filesystem::temp_directory_path() /
                    ("hacdcpf_opendss_gui_" + std::to_string(stamp) + "_" +
                     std::to_string(upload_counter.fetch_add(1)));
  std::error_code ec;
  std::filesystem::create_directories(root, ec);
  if (ec) {
    throw std::runtime_error("Unable to create temporary OpenDSS project directory: " +
                             root.string() + " (" + ec.message() + ")");
  }

  std::unordered_map<std::string, std::filesystem::path> lower_rel_to_path;
  lower_rel_to_path.reserve(files.size());
  for (const auto& file : files) {
    const auto target = (root / file.rel).lexically_normal();
    const auto parent = target.parent_path();
    std::filesystem::create_directories(parent, ec);
    if (ec) {
      throw std::runtime_error("Unable to create OpenDSS upload subdirectory: " +
                               parent.string() + " (" + ec.message() + ")");
    }
    std::ofstream out(target, std::ios::binary);
    if (!out) {
      throw std::runtime_error("Unable to write uploaded OpenDSS file: " +
                               target.string());
    }
    out << file.content;
    lower_rel_to_path[gui_lower_ascii(file.rel.generic_string())] = target;
  }

  auto requested_master =
      safe_gui_upload_relative_path(gui_json_string_field(
          request, {"master_path", "master", "filename", "name"}));
  std::filesystem::path master;
  if (requested_master.has_value()) {
    const std::string key = gui_lower_ascii(requested_master->generic_string());
    auto it = lower_rel_to_path.find(key);
    if (it != lower_rel_to_path.end()) master = it->second;
  }

  if (master.empty()) {
    int best_score = -1;
    for (const auto& file : files) {
      const std::string lower_rel = gui_lower_ascii(file.rel.generic_string());
      const std::string lower_name = gui_lower_ascii(file.name);
      const bool is_dss = file.rel.extension() == ".dss" ||
                          gui_lower_ascii(file.rel.extension().string()) == ".dss";
      int score = -1;
      if (lower_name == "master.dss") score = 1000;
      else if (lower_name.find("master") != std::string::npos && is_dss) score = 900;
      else if (lower_name.find("main") != std::string::npos && is_dss) score = 850;
      else if (lower_rel.find("ieee") != std::string::npos && is_dss) score = 800;
      else if (is_dss && gui_lower_ascii(file.content).find("new circuit.") != std::string::npos) score = 700;
      else if (is_dss) score = 500;
      if (score > best_score) {
        best_score = score;
        master = root / file.rel;
      }
    }
  }
  if (master.empty()) master = root / files.front().rel;

  GuiOpenDSSUploadProject project;
  project.root = root;
  project.master_path = master.lexically_normal();
  project.file_count = static_cast<int>(files.size());
  project.warnings = std::move(warnings);
  return project;
}

std::filesystem::path project_root_path() {
#ifdef HACDCPF_PROJECT_ROOT
  return std::filesystem::path(HACDCPF_PROJECT_ROOT);
#else
  return std::filesystem::current_path();
#endif
}

std::optional<std::filesystem::path> canonical_existing_path(
    const std::filesystem::path& path) {
  std::error_code ec;
  if (!path.empty() && std::filesystem::exists(path, ec) && !ec) {
    return std::filesystem::canonical(path, ec);
  }
  return std::nullopt;
}

std::optional<std::filesystem::path> resolve_gui_opendss_master_path(
    const json& request,
    const std::string& dss_text) {
  std::vector<std::filesystem::path> candidates;
  auto add_candidate = [&](const std::filesystem::path& path) {
    if (!path.empty()) candidates.push_back(path);
  };

  const std::string explicit_path =
      request.value("dss_path", request.value("path", std::string{}));
  if (!explicit_path.empty()) {
    const std::filesystem::path p(explicit_path);
    add_candidate(p);
    if (p.is_relative()) add_candidate(project_root_path() / p);
  }

  const std::string file_name =
      request.value("filename", request.value("name", std::string{}));
  const std::string lower_name = gui_lower_ascii(file_name);
  if (lower_name == "ieee13nodeckt.dss" ||
      dss_text.find("IEEE 13 Node") != std::string::npos ||
      dss_text.find("IEEE13Nodeckt") != std::string::npos) {
    add_candidate(project_root_path() / "external_data" / "opendss_ieee_pes" /
                  "opendss_reference" / "13_node" / "official_full" /
                  "IEEE13Nodeckt.dss");
  }

  if (!file_name.empty()) {
    add_candidate(project_root_path() / file_name);
    add_candidate(project_root_path() / "external_data" / "opendss_ieee_pes" /
                  "opendss_reference" / "13_node" / "official_full" /
                  file_name);
    add_candidate(project_root_path() / "tests" / "data" / "phase_domain_julia" /
                  file_name);
  }

  for (const auto& candidate : candidates) {
    if (auto resolved = canonical_existing_path(candidate)) return resolved;
  }
  return std::nullopt;
}

json phase_mask_json(const hacdcpf::PhaseMask& mask) {
  std::string phases;
  if (mask.has(0)) phases.push_back('A');
  if (mask.has(1)) phases.push_back('B');
  if (mask.has(2)) phases.push_back('C');
  return phases;
}

json phase_jpc_bus_results_to_json(
    const hacdcpf::analysis::ThreePhaseJPCPhase& jpc) {
  json rows = json::array();
  for (std::size_t row_idx = 0; row_idx < jpc.bus_abc.size(); ++row_idx) {
    const auto& row = jpc.bus_abc[row_idx];
    const std::string name =
        jpc.bus_id_to_name.count(row.bus_id) ? jpc.bus_id_to_name.at(row.bus_id)
                                             : ("Bus " + std::to_string(row.bus_id));
    json item{{"bus_id", row.bus_id},
              {"name", name},
              {"base_kv", row.base_kv},
              {"bus_type", hacdcpf::bus_type_str(row.bus_type)},
              {"phases", std::string{}}};
    std::string phase_text;
    const std::array<const char*, 3> phase_names = {"a", "b", "c"};
    for (int phase = 0; phase < 3; ++phase) {
      const bool has_phase = row.has_phase[static_cast<std::size_t>(phase)];
      if (has_phase) phase_text.push_back(static_cast<char>('A' + phase));
      const auto idx = row_idx * 3 + static_cast<std::size_t>(phase);
      const auto v = idx < jpc.v_abc.size()
                         ? jpc.v_abc[idx]
                         : std::polar(row.vm_pu[static_cast<std::size_t>(phase)],
                                      row.va_deg[static_cast<std::size_t>(phase)] *
                                          M_PI / 180.0);
      item[std::string("has_") + phase_names[phase]] = has_phase;
      const std::string vm_key = std::string("vm_") + phase_names[phase] + "_pu";
      const std::string va_key = std::string("va_") + phase_names[phase] + "_deg";
      if (has_phase) {
        item[vm_key] = std::abs(v);
        item[va_key] = std::arg(v) * 180.0 / M_PI;
      } else {
        item[vm_key] = nullptr;
        item[va_key] = nullptr;
      }
      item[std::string("pd_") + phase_names[phase] + "_mw"] =
          row.pd_mw[static_cast<std::size_t>(phase)];
      item[std::string("qd_") + phase_names[phase] + "_mvar"] =
          row.qd_mvar[static_cast<std::size_t>(phase)];
      item[std::string("pg_") + phase_names[phase] + "_mw"] =
          row.pg_mw[static_cast<std::size_t>(phase)];
      item[std::string("qg_") + phase_names[phase] + "_mvar"] =
          row.qg_mvar[static_cast<std::size_t>(phase)];
    }
    item["phases"] = phase_text;
    rows.push_back(std::move(item));
  }
  return rows;
}

double wrap_deg_diff(double lhs, double rhs) {
  double diff = lhs - rhs;
  while (diff > 180.0) diff -= 360.0;
  while (diff < -180.0) diff += 360.0;
  return diff;
}

json compare_phase_voltage_results(
    const hacdcpf::analysis::ThreePhaseJPCPhase& lhs,
    const hacdcpf::analysis::ThreePhaseJPCPhase& rhs) {
  double max_vm_error = 0.0;
  double max_angle_error = 0.0;
  double sum_vm_error = 0.0;
  double sum_angle_error = 0.0;
  int count = 0;
  json worst = json::object();
  for (const auto& [bus_name, bus_id] : lhs.bus_name_to_id) {
    auto lhs_row_it = std::find_if(
        lhs.bus_abc.begin(), lhs.bus_abc.end(),
        [&](const auto& row) { return row.bus_id == bus_id; });
    if (lhs_row_it == lhs.bus_abc.end()) continue;
    const std::string wanted = gui_lower_ascii(bus_name);
    const auto rhs_name_it = std::find_if(
        rhs.bus_name_to_id.begin(), rhs.bus_name_to_id.end(),
        [&](const auto& item) { return gui_lower_ascii(item.first) == wanted; });
    if (rhs_name_it == rhs.bus_name_to_id.end()) continue;
    auto rhs_row_it = std::find_if(
        rhs.bus_abc.begin(), rhs.bus_abc.end(),
        [&](const auto& row) { return row.bus_id == rhs_name_it->second; });
    if (rhs_row_it == rhs.bus_abc.end()) continue;
    for (int phase = 0; phase < 3; ++phase) {
      const std::size_t slot = static_cast<std::size_t>(phase);
      if (!lhs_row_it->has_phase[slot] || !rhs_row_it->has_phase[slot]) continue;
      const double vm_error = std::abs(lhs_row_it->vm_pu[slot] -
                                       rhs_row_it->vm_pu[slot]);
      const double angle_error =
          std::abs(wrap_deg_diff(lhs_row_it->va_deg[slot],
                                 rhs_row_it->va_deg[slot]));
      if (vm_error > max_vm_error || angle_error > max_angle_error) {
        worst = json{{"bus", bus_name},
                     {"phase", std::string(1, static_cast<char>('A' + phase))},
                     {"vm_error_pu", vm_error},
                     {"angle_error_deg", angle_error},
                     {"vm_ours_pu", lhs_row_it->vm_pu[slot]},
                     {"vm_opendss_pu", rhs_row_it->vm_pu[slot]},
                     {"va_ours_deg", lhs_row_it->va_deg[slot]},
                     {"va_opendss_deg", rhs_row_it->va_deg[slot]}};
      }
      max_vm_error = std::max(max_vm_error, vm_error);
      max_angle_error = std::max(max_angle_error, angle_error);
      sum_vm_error += vm_error;
      sum_angle_error += angle_error;
      ++count;
    }
  }
  return json{{"ran", true},
              {"count", count},
              {"max_vm_error_pu", max_vm_error},
              {"avg_vm_error_pu", count > 0 ? sum_vm_error / count : 0.0},
              {"max_angle_error_deg", max_angle_error},
              {"avg_angle_error_deg", count > 0 ? sum_angle_error / count : 0.0},
              {"within_gui_tolerance",
               count > 0 && max_vm_error < 1.0e-3 && max_angle_error < 0.1},
              {"worst", worst}};
}

struct GuiPhaseDomainSettings {
  hacdcpf::analysis::RunPFPhaseOptions solver;
  std::string algorithm{"compact"};
  std::string scope{"ac_only"};
  bool compare_opendss{true};
};

GuiPhaseDomainSettings phase_domain_settings_from_request(
    const json& root,
    int default_max_iter,
    double default_tol,
    bool default_verbose,
    std::string default_scope = "ac_only") {
  const json* o = nullptr;
  if (root.contains("three_phase") && root["three_phase"].is_object()) {
    o = &root["three_phase"];
  } else if (root.contains("options") && root["options"].is_object() &&
             root["options"].contains("three_phase") &&
             root["options"]["three_phase"].is_object()) {
    o = &root["options"]["three_phase"];
  }

  GuiPhaseDomainSettings settings;
  settings.solver.max_iter = default_max_iter;
  settings.solver.tol = default_tol;
  settings.solver.verbose = default_verbose;
  settings.scope = std::move(default_scope);
  settings.solver.algorithm = hacdcpf::analysis::PhaseDomainSolverAlgorithm::Compact;
  if (o == nullptr) return settings;

  settings.algorithm = o->value("algorithm", settings.algorithm);
  if (settings.algorithm == "newton") {
    settings.solver.algorithm = hacdcpf::analysis::PhaseDomainSolverAlgorithm::Newton;
  } else if (settings.algorithm == "fixed_point") {
    settings.solver.algorithm = hacdcpf::analysis::PhaseDomainSolverAlgorithm::FixedPoint;
  } else if (settings.algorithm == "compact") {
    settings.solver.algorithm = hacdcpf::analysis::PhaseDomainSolverAlgorithm::Compact;
  } else {
    throw std::invalid_argument("Unsupported three-phase solver algorithm: " +
                                settings.algorithm);
  }

  settings.scope = o->value("scope", settings.scope);
  if (settings.scope != "auto" && settings.scope != "ac_only" &&
      settings.scope != "staged_hybrid") {
    throw std::invalid_argument("Unsupported three-phase analysis scope: " +
                                settings.scope);
  }
  settings.solver.max_iter = std::clamp(
      o->value("max_iter", settings.solver.max_iter), 1, 100000);
  settings.solver.max_control_iter = std::clamp(
      o->value("max_control_iter", settings.solver.max_control_iter), 1, 100000);
  settings.solver.tol = std::clamp(
      o->value("tol", settings.solver.tol), 1.0e-14, 1.0);
  settings.solver.verbose = o->value("verbose", settings.solver.verbose);
  settings.solver.include_shunts =
      o->value("include_shunts", settings.solver.include_shunts);
  settings.solver.vmin_pu = std::clamp(
      o->value("vmin_pu", settings.solver.vmin_pu), 1.0e-3, 2.0);
  settings.compare_opendss =
      o->value("compare_opendss", settings.compare_opendss);
  return settings;
}

json phase_domain_settings_to_json(const GuiPhaseDomainSettings& settings,
                                   const std::string& effective_scope) {
  return json{{"algorithm", settings.algorithm},
              {"scope", settings.scope},
              {"scope_effective", effective_scope},
              {"max_iter", settings.solver.max_iter},
              {"max_control_iter", settings.solver.max_control_iter},
              {"tol", settings.solver.tol},
              {"verbose", settings.solver.verbose},
              {"include_shunts", settings.solver.include_shunts},
              {"vmin_pu", settings.solver.vmin_pu},
              {"compare_opendss", settings.compare_opendss}};
}

json phase_solution_metrics(
    const hacdcpf::analysis::ThreePhaseJPCPhase& solution) {
  constexpr double kTwoPiOverThree = 2.0943951023931954923;
  const std::complex<double> a = std::polar(1.0, kTwoPiOverThree);
  const std::complex<double> a2 = a * a;
  double min_vm = std::numeric_limits<double>::infinity();
  double max_vm = 0.0;
  double max_vuf = 0.0;
  int active_nodes = 0;
  for (std::size_t row_index = 0; row_index < solution.bus_abc.size(); ++row_index) {
    const auto& row = solution.bus_abc[row_index];
    std::array<std::complex<double>, 3> voltage{};
    bool complete = true;
    for (int phase = 0; phase < 3; ++phase) {
      const std::size_t slot = static_cast<std::size_t>(phase);
      if (!row.has_phase[slot]) {
        complete = false;
        continue;
      }
      const std::size_t flat = row_index * 3 + slot;
      voltage[slot] = flat < solution.v_abc.size()
                          ? solution.v_abc[flat]
                          : std::polar(row.vm_pu[slot],
                                       row.va_deg[slot] * M_PI / 180.0);
      const double vm = std::abs(voltage[slot]);
      min_vm = std::min(min_vm, vm);
      max_vm = std::max(max_vm, vm);
      ++active_nodes;
    }
    if (!complete) continue;
    const auto v1 = (voltage[0] + a * voltage[1] + a2 * voltage[2]) / 3.0;
    const auto v2 = (voltage[0] + a2 * voltage[1] + a * voltage[2]) / 3.0;
    if (std::abs(v1) > 1.0e-12) {
      max_vuf = std::max(max_vuf, 100.0 * std::abs(v2) / std::abs(v1));
    }
  }
  if (!std::isfinite(min_vm)) min_vm = 0.0;
  return json{{"active_phase_nodes", active_nodes},
              {"min_vm_pu", min_vm},
              {"max_vm_pu", max_vm},
              {"max_vuf_percent", max_vuf}};
}

json phase_solution_to_json(
    const hacdcpf::analysis::ThreePhaseJPCPhase& solution,
    const GuiPhaseDomainSettings& settings) {
  return json{{"ran", true},
              {"converged", solution.success},
              {"iterations", solution.iterations},
              {"residual", solution.residual},
              {"algorithm", settings.algorithm},
              {"solver_used", solution.solver_used},
              {"primary_solver", solution.primary_solver},
              {"result_source", solution.result_source},
              {"fallback_used", solution.fallback_used},
              {"primary_solver_failed_reason", solution.primary_solver_failed_reason},
              {"metrics", phase_solution_metrics(solution)},
              {"bus_results", phase_jpc_bus_results_to_json(solution)}};
}

void attach_phase_opendss_reference(
    json& destination,
    const hacdcpf::ThreePhaseACSystem& phase_system,
    const GuiPhaseDomainSettings& settings,
    const std::string& dss_source_path,
    const hacdcpf::analysis::ThreePhaseJPCPhase& solution) {
  if (!settings.compare_opendss) {
    destination["opendss_reference"] =
        json{{"ran", false}, {"reason", "disabled_by_request"}};
    return;
  }
  if (dss_source_path.empty()) {
    destination["opendss_reference"] =
        json{{"ran", false},
             {"reason", "OpenDSS master path is not available for this session"}};
    return;
  }
  try {
    auto reference_options = settings.solver;
    reference_options.algorithm = hacdcpf::analysis::PhaseDomainSolverAlgorithm::OpenDSS;
    reference_options.dss_file_path = dss_source_path;
    const auto reference =
        hacdcpf::analysis::runpf_phase(phase_system, reference_options);
    destination["opendss_reference"] =
        json{{"ran", true},
             {"converged", reference.success},
             {"iterations", reference.iterations},
             {"residual", reference.residual},
             {"source_path", dss_source_path},
             {"comparison", compare_phase_voltage_results(solution, reference)}};
  } catch (const std::exception& ex) {
    destination["opendss_reference"] =
        json{{"ran", false},
             {"source_path", dss_source_path},
             {"error", ex.what()}};
  }
}

int append_balanced_vsc_injection(
    hacdcpf::ThreePhaseACSystem& phase_system,
    int bus_id,
    double p_ac_injection_mw,
    double q_ac_injection_mvar,
    const std::string& name) {
  const auto bus_it = std::find_if(
      phase_system.buses.begin(), phase_system.buses.end(),
      [&](const auto& bus) { return bus.index == bus_id && bus.in_service; });
  if (bus_it == phase_system.buses.end() || bus_it->phase_mask.count() == 0) return 0;

  int next_index = 1;
  for (const auto& load : phase_system.loads) {
    next_index = std::max(next_index, load.index + 1);
  }
  hacdcpf::ThreePhaseLoad load;
  load.index = next_index;
  load.bus = bus_id;
  load.name = name;
  load.phase_mask = bus_it->phase_mask;
  load.connection = "wye";
  load.const_p_percent = 100.0;
  const double count = static_cast<double>(bus_it->phase_mask.count());
  const double p_per_phase = -p_ac_injection_mw / count;
  const double q_per_phase = -q_ac_injection_mvar / count;
  if (bus_it->phase_mask.has(0)) {
    load.p_a_mw = p_per_phase;
    load.q_a_mvar = q_per_phase;
  }
  if (bus_it->phase_mask.has(1)) {
    load.p_b_mw = p_per_phase;
    load.q_b_mvar = q_per_phase;
  }
  if (bus_it->phase_mask.has(2)) {
    load.p_c_mw = p_per_phase;
    load.q_c_mvar = q_per_phase;
  }
  phase_system.loads.push_back(std::move(load));
  return 1;
}

struct GuiPhaseHybridGeneratorBinding {
  int component_index{0};
  int bus_id{0};
  int phase{0};
  std::string name;
  std::string source_type{"three_phase_generator"};
};

struct GuiPhaseHybridModel {
  hacdcpf::opf::phase_hybrid::ThreePhaseHybridOPFCase opf;
  hacdcpf::powerflow::ThreePhaseHybridPFCase pf;
  std::vector<std::array<int, 3>> bus_nodes;
  std::vector<int> dc_bus_ids;
  std::vector<int> vsc_positions;
  std::vector<GuiPhaseHybridGeneratorBinding> generator_bindings;
  std::vector<std::string> limitations;
};

std::array<double, 3> gui_phase_values(double a, double b, double c) {
  return {a, b, c};
}

GuiPhaseHybridModel build_gui_phase_hybrid_model(
    const hacdcpf::HybridPowerSystem& sys,
    bool include_shunts,
    bool enforce_converter_capacity,
    bool enforce_converter_current,
    double vuf_max) {
  using hacdcpf::opf::phase_hybrid::PhaseGenerator;
  using hacdcpf::opf::phase_hybrid::PhaseVSC;
  using hacdcpf::opf::phase_hybrid::PhaseVSCControlMode;
  using hacdcpf::powerflow::ThreePhaseHybridPFControlMode;
  using hacdcpf::powerflow::ThreePhaseHybridPFConverter;

  if (!sys.three_phase_ac.has_value()) {
    throw std::invalid_argument(
        "Monolithic three-phase hybrid analysis requires three_phase_ac");
  }
  if (sys.dc.buses.empty() || sys.vsc_converters.empty()) {
    throw std::invalid_argument(
        "Monolithic three-phase hybrid analysis requires a DC network and VSC converter");
  }
  if (!sys.dc.dcdc_converters.empty()) {
    throw std::invalid_argument(
        "Monolithic three-phase hybrid GUI adapter does not yet support DC/DC converters");
  }
  if (!sys.energy_routers.empty()) {
    throw std::invalid_argument(
        "Monolithic three-phase hybrid GUI adapter does not yet expand energy routers");
  }

  const auto& tp = *sys.three_phase_ac;
  GuiPhaseHybridModel model;
  auto& opf = model.opf;
  auto& pf = model.pf;
  opf.name = sys.name + "_gui_phase_hybrid_opf";
  opf.base_mva = tp.base_mva > 0.0 ? tp.base_mva
                                    : (sys.base_mva > 0.0 ? sys.base_mva : 100.0);
  opf.vuf_max = std::clamp(vuf_max, 0.0, 1.0);

  const int full_n = static_cast<int>(tp.buses.size()) * 3;
  std::vector<int> full_to_node(static_cast<std::size_t>(full_n), -1);
  model.bus_nodes.resize(tp.buses.size(), std::array<int, 3>{-1, -1, -1});
  int node_count = 0;
  for (std::size_t bus_pos = 0; bus_pos < tp.buses.size(); ++bus_pos) {
    const auto& bus = tp.buses[bus_pos];
    if (!bus.in_service) continue;
    for (int phase = 0; phase < 3; ++phase) {
      if (!bus.phase_mask.has(phase)) continue;
      full_to_node[bus_pos * 3 + static_cast<std::size_t>(phase)] = node_count;
      model.bus_nodes[bus_pos][static_cast<std::size_t>(phase)] = node_count++;
    }
  }
  if (node_count == 0) {
    throw std::invalid_argument("three_phase_ac has no in-service phase nodes");
  }

  opf.y_ac.resize(node_count, node_count);
  std::vector<Eigen::Triplet<std::complex<double>>> ac_triplets;
  auto phase_network = tp;
  // The hybrid kernels represent an external grid as fixed reference voltage
  // plus dispatchable source power. Do not also stamp its Norton impedance.
  phase_network.external_grids.clear();
  for (const auto& entry :
       hacdcpf::analysis::build_full_ybus_phase_entries(
           phase_network, include_shunts)) {
    if (entry.row < 0 || entry.row >= full_n ||
        entry.col < 0 || entry.col >= full_n) continue;
    const int row = full_to_node[static_cast<std::size_t>(entry.row)];
    const int col = full_to_node[static_cast<std::size_t>(entry.col)];
    if (row >= 0 && col >= 0) ac_triplets.emplace_back(row, col, entry.value);
  }
  opf.y_ac.setFromTriplets(ac_triplets.begin(), ac_triplets.end());
  opf.y_ac.makeCompressed();
  opf.i_ac_fixed = Eigen::VectorXcd::Zero(node_count);
  opf.p_load_pu = Eigen::VectorXd::Zero(node_count);
  opf.q_load_pu = Eigen::VectorXd::Zero(node_count);
  opf.v_min_pu = Eigen::VectorXd::Constant(node_count, 0.9);
  opf.v_max_pu = Eigen::VectorXd::Constant(node_count, 1.1);
  opf.voltage_start = Eigen::VectorXcd::Ones(node_count);
  opf.ac_phase_index.assign(static_cast<std::size_t>(node_count), 0);
  Eigen::VectorXcd fixed_generation = Eigen::VectorXcd::Zero(node_count);

  std::unordered_map<int, int> tp_bus_pos;
  for (std::size_t pos = 0; pos < tp.buses.size(); ++pos) {
    tp_bus_pos[tp.buses[pos].index] = static_cast<int>(pos);
    const auto& bus = tp.buses[pos];
    const auto vm = gui_phase_values(bus.vm_a_pu, bus.vm_b_pu, bus.vm_c_pu);
    const auto va = gui_phase_values(bus.va_a_deg, bus.va_b_deg, bus.va_c_deg);
    const auto pd = gui_phase_values(bus.pd_a_mw, bus.pd_b_mw, bus.pd_c_mw);
    const auto qd = gui_phase_values(bus.qd_a_mvar, bus.qd_b_mvar, bus.qd_c_mvar);
    std::vector<int> complete_bus;
    for (int phase = 0; phase < 3; ++phase) {
      const int node = model.bus_nodes[pos][static_cast<std::size_t>(phase)];
      if (node < 0) continue;
      opf.p_load_pu[node] += pd[static_cast<std::size_t>(phase)] / opf.base_mva;
      opf.q_load_pu[node] += qd[static_cast<std::size_t>(phase)] / opf.base_mva;
      opf.v_min_pu[node] = bus.vmin_pu > 0.0 ? bus.vmin_pu : 0.9;
      opf.v_max_pu[node] = bus.vmax_pu > 0.0 ? bus.vmax_pu : 1.1;
      opf.voltage_start[node] = std::polar(
          vm[static_cast<std::size_t>(phase)] > 0.0
              ? vm[static_cast<std::size_t>(phase)] : 1.0,
          va[static_cast<std::size_t>(phase)] * M_PI / 180.0);
      opf.ac_phase_index[static_cast<std::size_t>(node)] = phase;
      complete_bus.push_back(node);
    }
    if (complete_bus.size() == 3) opf.three_phase_bus_nodes.push_back(complete_bus);
  }

  for (const auto& load : tp.loads) {
    if (!load.in_service) continue;
    std::string connection = load.connection;
    std::transform(connection.begin(), connection.end(), connection.begin(),
                   [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
    if (connection == "delta") {
      throw std::invalid_argument(
          "Monolithic three-phase hybrid GUI adapter currently requires wye phase loads");
    }
    if (load.const_z_percent > 1.0e-9 || load.const_i_percent > 1.0e-9 ||
        load.p_const_z_percent > 1.0e-9 || load.p_const_i_percent > 1.0e-9 ||
        load.q_const_z_percent > 1.0e-9 || load.q_const_i_percent > 1.0e-9) {
      throw std::invalid_argument(
          "Monolithic three-phase hybrid GUI adapter currently requires constant-power phase loads");
    }
    const auto bus_it = tp_bus_pos.find(load.bus);
    if (bus_it == tp_bus_pos.end()) continue;
    const auto p = gui_phase_values(load.p_a_mw, load.p_b_mw, load.p_c_mw);
    const auto q = gui_phase_values(load.q_a_mvar, load.q_b_mvar, load.q_c_mvar);
    for (int phase = 0; phase < 3; ++phase) {
      if (!load.phase_mask.has(phase)) continue;
      const int node = model.bus_nodes[static_cast<std::size_t>(bus_it->second)]
                                      [static_cast<std::size_t>(phase)];
      if (node < 0) continue;
      opf.p_load_pu[node] += p[static_cast<std::size_t>(phase)] / opf.base_mva;
      opf.q_load_pu[node] += q[static_cast<std::size_t>(phase)] / opf.base_mva;
    }
  }

  const double total_load_mw = std::max(1.0, opf.p_load_pu.cwiseMax(0.0).sum() * opf.base_mva);
  for (const auto& generator : tp.generators) {
    if (!generator.in_service) continue;
    const auto bus_it = tp_bus_pos.find(generator.bus);
    if (bus_it == tp_bus_pos.end()) continue;
    const auto p = gui_phase_values(generator.p_a_mw, generator.p_b_mw,
                                    generator.p_c_mw);
    const auto q = gui_phase_values(generator.q_a_mvar, generator.q_b_mvar,
                                    generator.q_c_mvar);
    const bool explicit_phase =
        std::abs(generator.p_a_mw) + std::abs(generator.p_b_mw) +
        std::abs(generator.p_c_mw) + std::abs(generator.q_a_mvar) +
        std::abs(generator.q_b_mvar) + std::abs(generator.q_c_mvar) > 1.0e-12;
    const double phase_count = std::max(1, generator.phase_mask.count());
    for (int phase = 0; phase < 3; ++phase) {
      if (!generator.phase_mask.has(phase)) continue;
      const int node = model.bus_nodes[static_cast<std::size_t>(bus_it->second)]
                                      [static_cast<std::size_t>(phase)];
      if (node < 0) continue;
      const double pg = explicit_phase ? p[static_cast<std::size_t>(phase)]
                                       : generator.p_mw / phase_count;
      const double qg = explicit_phase ? q[static_cast<std::size_t>(phase)]
                                       : generator.q_mvar / phase_count;
      fixed_generation[node] += std::complex<double>(pg, qg) / opf.base_mva;
      PhaseGenerator item;
      item.phase_node = node;
      const bool has_p_bounds = generator.pmax_mw > generator.pmin_mw;
      const bool has_q_bounds = generator.qmax_mvar > generator.qmin_mvar;
      item.p_min_pu = (has_p_bounds ? generator.pmin_mw / phase_count : pg) / opf.base_mva;
      item.p_max_pu = (has_p_bounds ? generator.pmax_mw / phase_count : pg) / opf.base_mva;
      item.q_min_pu = (has_q_bounds ? generator.qmin_mvar / phase_count : qg) / opf.base_mva;
      item.q_max_pu = (has_q_bounds ? generator.qmax_mvar / phase_count : qg) / opf.base_mva;
      const auto rich = std::find_if(
          sys.ac.generators.begin(), sys.ac.generators.end(), [&](const auto& g) {
            return g.in_service && g.bus == generator.bus &&
                   (generator.name.empty() || g.name.empty() || g.name == generator.name);
          });
      if (rich != sys.ac.generators.end()) {
        item.cost_c2 = rich->cost_c2 * phase_count;
        item.cost_c1 = rich->cost_c1;
      } else {
        item.cost_c1 = 30.0;
      }
      opf.generators.push_back(item);
      model.generator_bindings.push_back(
          {generator.index, generator.bus, phase, generator.name,
           "three_phase_generator"});
    }
  }

  std::unordered_set<int> reference_nodes;
  const auto add_reference = [&](int bus_pos, hacdcpf::PhaseMask mask,
                                 const std::array<double, 3>& vm,
                                 const std::array<double, 3>& va) {
    for (int phase = 0; phase < 3; ++phase) {
      if (!mask.has(phase)) continue;
      const int node = model.bus_nodes[static_cast<std::size_t>(bus_pos)]
                                      [static_cast<std::size_t>(phase)];
      if (node < 0 || !reference_nodes.insert(node).second) continue;
      opf.reference_nodes.push_back(node);
      opf.reference_voltage.conservativeResize(opf.reference_voltage.size() + 1);
      opf.reference_voltage[opf.reference_voltage.size() - 1] =
          std::polar(vm[static_cast<std::size_t>(phase)],
                     va[static_cast<std::size_t>(phase)] * M_PI / 180.0);
    }
  };
  for (const auto& grid : tp.external_grids) {
    if (!grid.in_service) continue;
    const auto bus_it = tp_bus_pos.find(grid.bus);
    if (bus_it == tp_bus_pos.end()) continue;
    const std::array<double, 3> vm = grid.use_phase_voltage_setpoint
        ? gui_phase_values(grid.vm_a_pu, grid.vm_b_pu, grid.vm_c_pu)
        : gui_phase_values(grid.vm_pu, grid.vm_pu, grid.vm_pu);
    const std::array<double, 3> va = grid.use_phase_voltage_setpoint
        ? gui_phase_values(grid.va_a_deg, grid.va_b_deg, grid.va_c_deg)
        : gui_phase_values(grid.va_deg, grid.va_deg - 120.0, grid.va_deg + 120.0);
    add_reference(bus_it->second, grid.phase_mask, vm, va);
    for (int phase = 0; phase < 3; ++phase) {
      if (!grid.phase_mask.has(phase)) continue;
      const int node = model.bus_nodes[static_cast<std::size_t>(bus_it->second)]
                                      [static_cast<std::size_t>(phase)];
      if (node < 0) continue;
      PhaseGenerator source;
      source.phase_node = node;
      source.p_min_pu = -5.0 * total_load_mw / opf.base_mva;
      source.p_max_pu = 5.0 * total_load_mw / opf.base_mva;
      source.q_min_pu = -5.0 * total_load_mw / opf.base_mva;
      source.q_max_pu = 5.0 * total_load_mw / opf.base_mva;
      const auto rich = std::find_if(
          sys.ac.external_grids.begin(), sys.ac.external_grids.end(),
          [&](const auto& g) { return g.in_service && g.bus == grid.bus; });
      if (rich != sys.ac.external_grids.end()) {
        source.cost_c2 = rich->cost_c2 * 3.0;
        source.cost_c1 = rich->cost_c1;
      } else {
        source.cost_c1 = 30.0;
      }
      opf.generators.push_back(source);
      model.generator_bindings.push_back(
          {grid.index, grid.bus, phase, grid.name, "three_phase_external_grid"});
    }
  }
  if (opf.reference_nodes.empty()) {
    for (std::size_t pos = 0; pos < tp.buses.size(); ++pos) {
      const auto& bus = tp.buses[pos];
      if (!bus.in_service || bus.bus_type != hacdcpf::BusType::SLACK) continue;
      add_reference(static_cast<int>(pos), bus.phase_mask,
                    gui_phase_values(bus.vm_a_pu, bus.vm_b_pu, bus.vm_c_pu),
                    gui_phase_values(bus.va_a_deg, bus.va_b_deg, bus.va_c_deg));
      break;
    }
  }
  if (opf.reference_nodes.empty()) {
    throw std::invalid_argument(
        "Monolithic three-phase hybrid analysis requires an AC reference source");
  }

  std::unordered_map<int, int> dc_bus_pos;
  for (std::size_t pos = 0; pos < sys.dc.buses.size(); ++pos) {
    const auto& bus = sys.dc.buses[pos];
    if (!bus.in_service) continue;
    dc_bus_pos[bus.index] = static_cast<int>(model.dc_bus_ids.size());
    model.dc_bus_ids.push_back(bus.index);
  }
  const int ndc = static_cast<int>(model.dc_bus_ids.size());
  if (ndc == 0) throw std::invalid_argument("DC network has no in-service buses");
  opf.g_dc.resize(ndc, ndc);
  std::vector<Eigen::Triplet<double>> dc_triplets;
  for (const auto& branch : sys.dc.branches) {
    if (!branch.in_service) continue;
    const auto from = dc_bus_pos.find(branch.from_bus);
    const auto to = dc_bus_pos.find(branch.to_bus);
    if (from == dc_bus_pos.end() || to == dc_bus_pos.end()) continue;
    if (!(branch.r_pu > 0.0)) {
      throw std::invalid_argument(
          "Monolithic three-phase hybrid analysis requires positive DC branch r_pu");
    }
    const double conductance = std::max(1, branch.n_parallel) / branch.r_pu;
    dc_triplets.emplace_back(from->second, from->second, conductance);
    dc_triplets.emplace_back(to->second, to->second, conductance);
    dc_triplets.emplace_back(from->second, to->second, -conductance);
    dc_triplets.emplace_back(to->second, from->second, -conductance);
  }
  opf.g_dc.setFromTriplets(dc_triplets.begin(), dc_triplets.end());
  opf.g_dc.makeCompressed();
  opf.p_dc_load_pu = Eigen::VectorXd::Zero(ndc);
  opf.v_dc_start = Eigen::VectorXd::Ones(ndc);
  opf.v_dc_min_pu = Eigen::VectorXd::Constant(ndc, 0.9);
  opf.v_dc_max_pu = Eigen::VectorXd::Constant(ndc, 1.1);
  for (const auto& bus : sys.dc.buses) {
    const auto it = dc_bus_pos.find(bus.index);
    if (it == dc_bus_pos.end()) continue;
    opf.p_dc_load_pu[it->second] += bus.pd_mw / opf.base_mva;
    opf.v_dc_start[it->second] = bus.vm_pu > 0.0 ? bus.vm_pu : 1.0;
    opf.v_dc_min_pu[it->second] = bus.vmin_pu > 0.0 ? bus.vmin_pu : 0.9;
    opf.v_dc_max_pu[it->second] = bus.vmax_pu > 0.0 ? bus.vmax_pu : 1.1;
    if (bus.bus_type == hacdcpf::DCBusType::DC_V) {
      opf.dc_reference_terminals.push_back(it->second);
      opf.dc_reference_voltage_pu.conservativeResize(
          opf.dc_reference_voltage_pu.size() + 1);
      opf.dc_reference_voltage_pu[opf.dc_reference_voltage_pu.size() - 1] =
          opf.v_dc_start[it->second];
    }
  }
  for (const auto& load : sys.dc.loads) {
    if (!load.in_service) continue;
    const auto it = dc_bus_pos.find(load.bus);
    if (it != dc_bus_pos.end())
      opf.p_dc_load_pu[it->second] += load.p_mw * load.scaling / opf.base_mva;
  }
  for (const auto& source : sys.dc.dc_static_generators) {
    if (!source.in_service) continue;
    if (source.controllable) {
      throw std::invalid_argument(
          "Monolithic three-phase hybrid GUI adapter does not yet dispatch DC static generators");
    }
    const auto it = dc_bus_pos.find(source.bus);
    if (it != dc_bus_pos.end())
      opf.p_dc_load_pu[it->second] -= source.p_set_mw * source.scaling / opf.base_mva;
  }
  for (const auto& source : sys.dc.pv_arrays) {
    if (!source.in_service) continue;
    const auto it = dc_bus_pos.find(source.bus);
    if (it != dc_bus_pos.end())
      opf.p_dc_load_pu[it->second] -= source.p_set_mw / opf.base_mva;
  }
  for (const auto& storage : sys.dc.dc_storage) {
    if (!storage.in_service) continue;
    const auto it = dc_bus_pos.find(storage.bus);
    if (it != dc_bus_pos.end())
      opf.p_dc_load_pu[it->second] -= storage.p_mw / opf.base_mva;
  }

  bool pf_has_vdc_controller = false;
  for (std::size_t pos = 0; pos < sys.vsc_converters.size(); ++pos) {
    const auto& converter = sys.vsc_converters[pos];
    if (!converter.in_service) continue;
    const auto ac_bus = tp_bus_pos.find(converter.bus_ac);
    const auto dc_bus = dc_bus_pos.find(converter.bus_dc);
    if (ac_bus == tp_bus_pos.end() || dc_bus == dc_bus_pos.end()) continue;
    std::vector<int> phase_nodes;
    for (int phase = 0; phase < 3; ++phase) {
      const int node = model.bus_nodes[static_cast<std::size_t>(ac_bus->second)]
                                      [static_cast<std::size_t>(phase)];
      if (node >= 0) phase_nodes.push_back(node);
    }
    if (phase_nodes.size() != 3) {
      throw std::invalid_argument(
          "Sequence-aware monolithic hybrid VSC terminals require phases A/B/C");
    }
    PhaseVSC opf_converter;
    opf_converter.phase_nodes = phase_nodes;
    opf_converter.dc_terminal = dc_bus->second;
    opf_converter.efficiency = std::clamp(converter.eta, 0.01, 1.0);
    const double rated_mva = std::max(
        {converter.p_rated_mw, std::abs(converter.pmax_mw),
         std::abs(converter.pmin_mw), std::abs(converter.qmax_mvar),
         std::abs(converter.qmin_mvar), total_load_mw});
    opf_converter.s_max_pu = enforce_converter_capacity
        ? rated_mva / opf.base_mva : 1.0e6;
    opf_converter.phase_current_max_pu =
        enforce_converter_current && converter.i_ac_max_pu > 0.0
            ? converter.i_ac_max_pu : 1.0e6;
    opf_converter.control_mode = converter.ac_grid_forming ||
                                         converter.control_mode ==
                                             hacdcpf::ConverterMode::AC_GRID_FORMING
                                     ? PhaseVSCControlMode::GridFormingDroop
                                     : PhaseVSCControlMode::EqualPhasePower;
    opf_converter.virtual_r_pu = converter.r_conv_ac_pu > 0.0
                                     ? converter.r_conv_ac_pu : 0.01;
    opf_converter.virtual_x_pu = converter.x_sc_pu > 0.0
                                     ? converter.x_sc_pu : 0.10;
    opf_converter.voltage_reference_pu = converter.v_ac_set_pu > 0.0
                                              ? converter.v_ac_set_pu : 1.0;
    opf.converters.push_back(opf_converter);

    ThreePhaseHybridPFConverter pf_converter;
    pf_converter.phase_nodes = phase_nodes;
    pf_converter.dc_terminal = dc_bus->second;
    pf_converter.efficiency = opf_converter.efficiency;
    pf_converter.p_set_pu = converter.p_set_mw / opf.base_mva;
    pf_converter.q_set_pu = converter.q_set_mvar / opf.base_mva;
    pf_converter.v_dc_set_pu = converter.v_dc_set_pu > 0.0
                                   ? converter.v_dc_set_pu : opf.v_dc_start[dc_bus->second];
    pf_converter.virtual_r_pu = opf_converter.virtual_r_pu;
    pf_converter.virtual_x_pu = opf_converter.virtual_x_pu;
    pf_converter.internal_voltage_positive = std::polar(
        converter.v_ac_set_pu > 0.0 ? converter.v_ac_set_pu : 1.0,
        converter.v_ac_angle_set_deg * M_PI / 180.0);
    const bool vdc_control =
        converter.grid_forming || converter.control_mode == hacdcpf::ConverterMode::VDC_Q ||
        converter.control_mode == hacdcpf::ConverterMode::VDC_VAC ||
        converter.control_mode == hacdcpf::ConverterMode::DC_V_DROOP_AC_V;
    if (converter.ac_grid_forming) {
      pf_converter.control_mode = vdc_control
          ? ThreePhaseHybridPFControlMode::GridFormingVdc
          : ThreePhaseHybridPFControlMode::GridFormingVoltage;
    } else {
      pf_converter.control_mode = vdc_control
          ? ThreePhaseHybridPFControlMode::GridFollowingVdcQ
          : ThreePhaseHybridPFControlMode::GridFollowingPQ;
    }
    pf_has_vdc_controller = pf_has_vdc_controller || vdc_control;
    pf.converters.push_back(pf_converter);
    model.vsc_positions.push_back(static_cast<int>(pos));
  }
  if (pf.converters.empty()) {
    throw std::invalid_argument(
        "No in-service VSC has both a three-phase AC terminal and DC terminal");
  }
  if (!pf_has_vdc_controller) {
    pf.converters.front().control_mode =
        ThreePhaseHybridPFControlMode::GridFollowingVdcQ;
    pf.converters.front().v_dc_set_pu =
        opf.v_dc_start[pf.converters.front().dc_terminal];
    model.limitations.push_back(
        "No Vdc-forming VSC was declared; the first VSC was promoted to Vdc-Q for PF closure");
  }
  if (opf.dc_reference_terminals.empty()) {
    const int terminal = opf.converters.front().dc_terminal;
    opf.dc_reference_terminals.push_back(terminal);
    opf.dc_reference_voltage_pu = Eigen::VectorXd::Constant(
        1, opf.v_dc_start[terminal]);
    model.limitations.push_back(
        "No DC_V bus was declared; the first VSC terminal voltage anchors the OPF DC island");
  }

  pf.name = sys.name + "_gui_phase_hybrid_pf";
  pf.base_mva = opf.base_mva;
  pf.y_ac = opf.y_ac;
  pf.i_ac_fixed = opf.i_ac_fixed;
  pf.p_load_pu = opf.p_load_pu - fixed_generation.real();
  pf.q_load_pu = opf.q_load_pu - fixed_generation.imag();
  pf.voltage_start = opf.voltage_start;
  pf.ac_phase_index = opf.ac_phase_index;
  pf.reference_nodes = opf.reference_nodes;
  pf.reference_voltage = opf.reference_voltage;
  pf.g_dc = opf.g_dc;
  pf.p_dc_load_pu = opf.p_dc_load_pu;
  pf.v_dc_start = opf.v_dc_start;
  model.limitations.push_back(
      "GUI adapter supports constant-power wye phase loads, resistive DC branches, and direct VSC ports");
  return model;
}

json gui_phase_hybrid_bus_results(
    const hacdcpf::ThreePhaseACSystem& tp,
    const GuiPhaseHybridModel& model,
    const Eigen::VectorXcd& voltage) {
  json rows = json::array();
  for (std::size_t bus_pos = 0; bus_pos < tp.buses.size(); ++bus_pos) {
    const auto& bus = tp.buses[bus_pos];
    json row{{"bus_id", bus.index},
             {"bus", bus.index},
             {"name", bus.name},
             {"phases", hacdcpf::phase_mask_to_string(bus.phase_mask)}};
    for (int phase = 0; phase < 3; ++phase) {
      const int node = model.bus_nodes[bus_pos][static_cast<std::size_t>(phase)];
      const std::string suffix(1, static_cast<char>('a' + phase));
      if (node >= 0 && node < voltage.size()) {
        row["vm_" + suffix + "_pu"] = std::abs(voltage[node]);
        row["va_" + suffix + "_deg"] = std::arg(voltage[node]) * 180.0 / M_PI;
      } else {
        row["vm_" + suffix + "_pu"] = nullptr;
        row["va_" + suffix + "_deg"] = nullptr;
      }
    }
    rows.push_back(std::move(row));
  }
  return rows;
}

void gui_phase_hybrid_average_voltage(
    const GuiPhaseHybridModel& model,
    const Eigen::VectorXcd& voltage,
    json& vm,
    json& va) {
  vm = json::array();
  va = json::array();
  for (const auto& nodes : model.bus_nodes) {
    std::complex<double> positive{0.0, 0.0};
    int count = 0;
    const std::complex<double> a = std::polar(1.0, 2.0 * M_PI / 3.0);
    const std::complex<double> rotation[3] = {{1.0, 0.0}, a, a * a};
    for (int phase = 0; phase < 3; ++phase) {
      const int node = nodes[static_cast<std::size_t>(phase)];
      if (node < 0 || node >= voltage.size()) continue;
      positive += rotation[phase] * voltage[node];
      ++count;
    }
    if (count == 0) {
      vm.push_back(nullptr);
      va.push_back(nullptr);
    } else {
      positive /= static_cast<double>(count);
      vm.push_back(std::abs(positive));
      va.push_back(std::arg(positive));
    }
  }
}

json gui_phase_hybrid_dc_bus_results(
    const GuiPhaseHybridModel& model,
    const Eigen::VectorXd& voltage) {
  json rows = json::array();
  for (std::size_t pos = 0; pos < model.dc_bus_ids.size(); ++pos) {
    rows.push_back(json{{"position", pos},
                        {"index", model.dc_bus_ids[pos]},
                        {"canvas_type", "dc"},
                        {"canvas_index", model.dc_bus_ids[pos]},
                        {"vdc_pu", pos < static_cast<std::size_t>(voltage.size())
                                           ? voltage[static_cast<int>(pos)] : 0.0}});
  }
  return rows;
}

void apply_current_carbon_factors_to_snapshot(
    const hacdcpf::HybridPowerSystem& current,
    hacdcpf::HybridPowerSystem& snapshot) {
  auto match = [](int index, int bus, const std::string& name,
                  int ref_index, int ref_bus, const std::string& ref_name) {
    return index == ref_index ||
           bus == ref_bus ||
           (!name.empty() && name == ref_name);
  };

  for (auto& g : snapshot.ac.generators) {
    for (const auto& src : current.ac.generators) {
      if (!match(g.index, g.bus, g.name, src.index, src.bus, src.name)) continue;
      g.emission_factor_tco2_mwh = src.emission_factor_tco2_mwh;
      break;
    }
  }
  for (auto& sg : snapshot.ac.static_generators) {
    for (const auto& src : current.ac.static_generators) {
      if (!match(sg.index, sg.bus, sg.name, src.index, src.bus, src.name)) continue;
      sg.co2_emission_rate = src.co2_emission_rate;
      break;
    }
  }
  for (auto& eg : snapshot.ac.external_grids) {
    for (const auto& src : current.ac.external_grids) {
      if (!match(eg.index, eg.bus, eg.name, src.index, src.bus, src.name)) continue;
      eg.emission_factor_tco2_mwh = src.emission_factor_tco2_mwh;
      break;
    }
  }
}

void apply_current_carbon_factors_to_tspf(
    const hacdcpf::HybridPowerSystem& current,
    hacdcpf::TimeSeriesPFResult& ts_result) {
  for (auto& snapshot : ts_result.pf_system_snapshots) {
    apply_current_carbon_factors_to_snapshot(current, snapshot);
  }
}

double carbon_factor_scale_from_unit(const std::string& unit) {
  std::string u = unit;
  std::transform(u.begin(), u.end(), u.begin(),
                 [](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });
  if (u.find("kg") != std::string::npos && u.find("mwh") != std::string::npos) return 0.001;
  if (u.find("kg") != std::string::npos && u.find("kwh") != std::string::npos) return 1.0;
  return 1.0;
}

double carbon_factor_scale_from_json(const json& root, const json& row) {
  const json* unit = nullptr;
  if (row.contains("unit") && row["unit"].is_string()) unit = &row["unit"];
  else if (row.contains("units") && row["units"].is_string()) unit = &row["units"];
  else if (root.contains("unit") && root["unit"].is_string()) unit = &root["unit"];
  else if (root.contains("units") && root["units"].is_string()) unit = &root["units"];
  return unit ? carbon_factor_scale_from_unit(unit->get<std::string>()) : 1.0;
}

double json_emission_factor_value(const json& row, double scale = 1.0,
                                  double default_value = 0.0) {
  auto read = [default_value](const json& value) {
    if (value.is_number()) return value.get<double>();
    if (value.is_string()) {
      try { return std::stod(value.get<std::string>()); } catch (...) {}
    }
    return default_value;
  };
  if (row.contains("emission_factor_tco2_mwh")) return read(row["emission_factor_tco2_mwh"]);
  if (row.contains("co2_emission_rate")) return read(row["co2_emission_rate"]) * scale;
  if (row.contains("emission_factor")) return read(row["emission_factor"]) * scale;
  return default_value;
}

std::optional<std::vector<double>> json_emission_factor_profile(const json& row,
                                                                double scale = 1.0) {
  const json* arr = nullptr;
  bool already_tco2_mwh = false;
  if (row.contains("emission_factor_profile_tco2_mwh")) {
    arr = &row["emission_factor_profile_tco2_mwh"];
    already_tco2_mwh = true;
  } else if (row.contains("emission_factor_tco2_mwh_profile")) {
    arr = &row["emission_factor_tco2_mwh_profile"];
    already_tco2_mwh = true;
  } else if (row.contains("co2_emission_rate_profile")) {
    arr = &row["co2_emission_rate_profile"];
  } else if (row.contains("emission_factor_profile")) {
    arr = &row["emission_factor_profile"];
  }
  if (arr == nullptr || !arr->is_array()) return std::nullopt;

  std::vector<double> values;
  values.reserve(arr->size());
  for (const auto& v : *arr) {
    try {
      double raw = 0.0;
      if (v.is_number()) raw = v.get<double>();
      else if (v.is_string()) raw = std::stod(v.get<std::string>());
      else continue;
      values.push_back(raw * (already_tco2_mwh ? 1.0 : scale));
    } catch (...) {
    }
  }
  if (values.empty()) return std::nullopt;
  return values;
}

json emissions_summary_to_json(const hacdcpf::analysis::EmissionsSummary& s) {
  return json{{"total_generation_emissions_tco2", s.total_generation_emissions_tco2},
              {"total_load_emissions_tco2", s.total_load_emissions_tco2},
              {"total_loss_emissions_tco2", s.total_loss_emissions_tco2},
              {"balance_error_tco2", s.balance_error_tco2},
              {"balance_error_pct", s.balance_error_pct}};
}

json carbon_analysis_to_json(const hacdcpf::HybridPowerSystem& sys,
                             const hacdcpf::analysis::CarbonAnalysisResult& carbon) {
  auto storage_canvas_type = [&](const hacdcpf::analysis::StorageCarbonResult& s) {
    return s.is_dc ? "dc_storage" : "storage";
  };
  auto storage_source_type = [&](const hacdcpf::analysis::StorageCarbonResult& s) {
    if (!s.is_dc) return "storage";
    for (const auto& st : sys.dc.dc_storage) {
      if (st.index == s.storage_index) return "dc_storage";
    }
    return "storage";
  };
  auto load_display_label = [](const hacdcpf::analysis::LoadCarbonResult& l,
                               bool is_dc) {
    if (l.load_index >= 0) return std::to_string(l.load_index);
    const char* prefix = is_dc ? "DC Bus Load @" : "Bus Load @";
    return std::string(prefix) + std::to_string(l.bus);
  };

  auto ac_bus_sink_power = [&](int bus) {
    double p = 0.0;
    for (const auto& l : carbon.load_carbon)
      if (l.bus == bus) p += std::max(0.0, l.demand_mw);
    for (const auto& st : carbon.storage_carbon)
      if (!st.is_dc && st.bus == bus && st.p_mw < 0.0) p += -st.p_mw;
    return p;
  };
  auto dc_bus_sink_power = [&](int bus) {
    double p = 0.0;
    for (const auto& l : carbon.dc_load_carbon)
      if (l.bus == bus) p += std::max(0.0, l.demand_mw);
    for (const auto& st : carbon.storage_carbon)
      if (st.is_dc && st.bus == bus && st.p_mw < 0.0) p += -st.p_mw;
    return p;
  };

  json out;
  out["converged"] = carbon.tracing_verified;
  out["status"] = carbon.tracing_verified
                      ? "converged"
                      : (carbon.power_balance_verified
                             ? "carbon matrix or tracing verification failed"
                             : "power balance verification failed");
  out["matrix_solved"] = carbon.matrix_solved;
  out["tracing_verified"] = carbon.tracing_verified;
  out["matrix_residual"] = carbon.matrix_residual;
  out["matrix_relative_residual"] = carbon.matrix_relative_residual;
  out["matrix_condition_estimate"] = carbon.matrix_condition_estimate;
  out["matrix_rank"] = carbon.matrix_rank;
  out["power_balance_verified"] = carbon.power_balance_verified;
  out["max_node_power_balance_error_mw"] =
      carbon.max_node_power_balance_error_mw;
  out["total_power_balance_error_mw"] =
      carbon.total_power_balance_error_mw;
  out["total_external_export_mw"] = carbon.total_external_export_mw;
  out["total_external_export_emissions_tco2"] =
      carbon.total_external_export_emissions_tco2;
  out["node_power_balance_errors"] = json::array();
  for (const auto& error : carbon.node_power_balance_errors) {
    out["node_power_balance_errors"].push_back(
        {{"bus_index", error.bus_index},
         {"is_dc", error.is_dc},
         {"mismatch_mw", error.mismatch_mw},
         {"source_mw", error.source_mw},
         {"required_mw", error.required_mw}});
  }
  out["tracing_summary"] = emissions_summary_to_json(carbon.tracing_summary);
  out["matrix_summary"] = emissions_summary_to_json(carbon.matrix_summary);
  out["total_storage_charge_emissions_tco2"] =
      carbon.total_storage_charge_emissions_tco2;
  out["total_storage_discharge_emissions_tco2"] =
      carbon.total_storage_discharge_emissions_tco2;

  json bc = json::array();
  for (const auto& b : carbon.bus_carbon) {
    const double sink_power_mw = ac_bus_sink_power(b.bus_index);
    const bool has_sink = sink_power_mw > 1e-9;
    const bool sane_potential =
        std::isfinite(b.carbon_intensity_tco2_mwh) &&
        b.carbon_intensity_tco2_mwh >= 0.0 &&
        b.carbon_intensity_tco2_mwh <= 10.0;
    bc.push_back({{"bus_index", b.bus_index},
                  {"carbon_intensity_tco2_mwh", b.carbon_intensity_tco2_mwh},
                  {"sink_power_mw", sink_power_mw},
                  {"has_carbon_sink", has_sink},
                  {"carbon_potential_valid", sane_potential},
                  {"carbon_potential_outlier", !sane_potential}});
  }
  out["bus_carbon"] = bc;

  json dbc = json::array();
  for (const auto& b : carbon.dc_bus_carbon) {
    const double sink_power_mw = dc_bus_sink_power(b.bus_index);
    const bool has_sink = sink_power_mw > 1e-9;
    const bool sane_potential =
        std::isfinite(b.carbon_intensity_tco2_mwh) &&
        b.carbon_intensity_tco2_mwh >= 0.0 &&
        b.carbon_intensity_tco2_mwh <= 10.0;
    dbc.push_back({{"bus_index", b.bus_index},
                   {"carbon_intensity_tco2_mwh", b.carbon_intensity_tco2_mwh},
                   {"sink_power_mw", sink_power_mw},
                   {"has_carbon_sink", has_sink},
                   {"carbon_potential_valid", sane_potential},
                   {"carbon_potential_outlier", !sane_potential}});
  }
  out["dc_bus_carbon"] = dbc;

  auto mw_map_to_json = [](const std::unordered_map<int, double>& values) {
    json out_map;
    for (const auto& [sid, mw] : values) {
      out_map[std::to_string(sid)] = mw;
    }
    return out_map;
  };

  json lc = json::array();
  for (const auto& l : carbon.load_carbon)
    lc.push_back({{"load_index", l.load_index},
                  {"display_load", load_display_label(l, false)},
                  {"bus", l.bus},
                  {"demand_mw", l.demand_mw},
                  {"display_demand_mw", std::abs(l.demand_mw)},
                  {"carbon_intensity_tco2_mwh", l.carbon_intensity_tco2_mwh},
                  {"total_emissions_tco2", l.total_emissions_tco2},
                  {"generator_supply_mw", mw_map_to_json(l.generator_supply_mw)}});
  out["load_carbon"] = lc;

  json dlc = json::array();
  for (const auto& l : carbon.dc_load_carbon)
    dlc.push_back({{"load_index", l.load_index},
                   {"display_load", load_display_label(l, true)},
                   {"bus", l.bus},
                   {"demand_mw", l.demand_mw},
                   {"display_demand_mw", std::abs(l.demand_mw)},
                   {"carbon_intensity_tco2_mwh", l.carbon_intensity_tco2_mwh},
                   {"total_emissions_tco2", l.total_emissions_tco2},
                   {"generator_supply_mw", mw_map_to_json(l.generator_supply_mw)}});
  out["dc_load_carbon"] = dlc;

  json brcc = json::array();
  for (const auto& b : carbon.branch_carbon)
    brcc.push_back({{"branch_index", b.branch_index},
                    {"from_bus", b.from_bus},
                    {"to_bus", b.to_bus},
                    {"loss_mw", b.loss_mw},
                    {"carbon_intensity_tco2_mwh", b.carbon_intensity_tco2_mwh},
                    {"total_emissions_tco2", b.total_emissions_tco2},
                    {"generator_loss_mw", mw_map_to_json(b.generator_loss_mw)}});
  out["branch_carbon"] = brcc;

  json dbrcc = json::array();
  for (const auto& b : carbon.dc_branch_carbon)
    dbrcc.push_back({{"branch_index", b.branch_index},
                     {"from_bus", b.from_bus},
                     {"to_bus", b.to_bus},
                     {"loss_mw", b.loss_mw},
                     {"carbon_intensity_tco2_mwh", b.carbon_intensity_tco2_mwh},
                     {"total_emissions_tco2", b.total_emissions_tco2},
                     {"generator_loss_mw", mw_map_to_json(b.generator_loss_mw)}});
  out["dc_branch_carbon"] = dbrcc;

  json vcc = json::array();
  for (const auto& v : carbon.vsc_carbon)
    vcc.push_back({{"converter_index", v.converter_index},
                   {"bus_ac", v.bus_ac},
                   {"bus_dc", v.bus_dc},
                   {"loss_mw", v.loss_mw},
                   {"carbon_intensity_tco2_mwh", v.carbon_intensity_tco2_mwh},
                   {"total_emissions_tco2", v.total_emissions_tco2},
                   {"generator_loss_mw", mw_map_to_json(v.generator_loss_mw)}});
  out["vsc_carbon"] = vcc;

  json dcc = json::array();
  for (const auto& d : carbon.dcdc_carbon)
    dcc.push_back({{"converter_index", d.converter_index},
                   {"bus_in", d.bus_in},
                   {"bus_out", d.bus_out},
                   {"loss_mw", d.loss_mw},
                   {"carbon_intensity_tco2_mwh", d.carbon_intensity_tco2_mwh},
                   {"total_emissions_tco2", d.total_emissions_tco2},
                   {"generator_loss_mw", mw_map_to_json(d.generator_loss_mw)}});
  out["dcdc_carbon"] = dcc;

  json sc = json::array();
  for (const auto& s : carbon.storage_carbon)
    sc.push_back({{"storage_index", s.storage_index},
                  {"bus", s.bus},
                  {"is_dc", s.is_dc},
                  {"canvas_type", storage_canvas_type(s)},
                  {"canvas_index", s.storage_index},
                  {"source_type", storage_source_type(s)},
                  {"p_mw", s.p_mw},
                  {"soc", s.soc},
                  {"stored_energy_mwh", s.stored_energy_mwh},
                  {"soc_carbon_intensity_tco2_mwh", s.soc_carbon_intensity_tco2_mwh},
                  {"carbon_intensity_tco2_mwh", s.carbon_intensity_tco2_mwh},
                  {"total_emissions_tco2", s.total_emissions_tco2},
                  {"source_supply_mw", mw_map_to_json(s.source_supply_mw)}});
  out["storage_carbon"] = sc;

  json erc = json::array();
  for (const auto& er : carbon.energy_router_carbon) {
    erc.push_back({{"router_index", er.router_index},
                   {"input_power_mw", er.input_power_mw},
                   {"output_power_mw", er.output_power_mw},
                   {"loss_mw", er.loss_mw},
                   {"active_input_ports", er.active_input_ports},
                   {"active_output_ports", er.active_output_ports},
                   {"carbon_intensity_tco2_mwh", er.carbon_intensity_tco2_mwh},
                   {"total_emissions_tco2", er.total_emissions_tco2},
                   {"source_loss_mw", mw_map_to_json(er.source_loss_mw)}});
  }
  out["energy_router_carbon"] = erc;
  out["generator_loss_allocation"] = mw_map_to_json(carbon.generator_loss_allocation);

  json sk_labels = json::array(), sk_src = json::array(), sk_tgt = json::array(), sk_val = json::array();
  json source_meta = json::array();
  for (const auto& source : carbon.carbon_sources) {
    sk_labels.push_back(source.label);
    source_meta.push_back(
        json{{"source_id", source.source_id},
             {"label", source.label},
             {"source_type", source.source_type},
             {"component_index", source.component_index},
             {"bus", source.bus},
             {"is_dc", source.is_dc},
             {"scheduled_p_mw", source.scheduled_power_mw},
             {"p_mw", source.power_mw},
             {"traced_power_mw", 0.0},
             {"emission_factor_tco2_mwh",
              source.emission_factor_tco2_mwh},
             {"is_balancing", source.is_balancing}});
  }

  const int n_sources = static_cast<int>(carbon.carbon_sources.size());
  std::vector<double> source_traced_power(static_cast<size_t>(n_sources), 0.0);
  auto add_source_usage = [&](const std::unordered_map<int, double>& values) {
    for (const auto& [sid, mw] : values) {
      if (sid < 0 || sid >= n_sources || mw <= 0.0) continue;
      source_traced_power[static_cast<size_t>(sid)] += mw;
    }
  };
  for (const auto& l : carbon.load_carbon) add_source_usage(l.generator_supply_mw);
  for (const auto& l : carbon.dc_load_carbon) add_source_usage(l.generator_supply_mw);
  for (const auto& s : carbon.storage_carbon) {
    if (s.p_mw < -1e-9) add_source_usage(s.source_supply_mw);
  }
  for (const auto& b : carbon.branch_carbon) add_source_usage(b.generator_loss_mw);
  for (const auto& b : carbon.dc_branch_carbon) add_source_usage(b.generator_loss_mw);
  for (const auto& v : carbon.vsc_carbon) add_source_usage(v.generator_loss_mw);
  for (const auto& d : carbon.dcdc_carbon) add_source_usage(d.generator_loss_mw);
  for (const auto& er : carbon.energy_router_carbon) add_source_usage(er.source_loss_mw);
  for (int sid = 0; sid < n_sources; ++sid) {
    const double traced = source_traced_power[static_cast<size_t>(sid)];
    source_meta[static_cast<size_t>(sid)]["traced_power_mw"] = traced;
  }
  out["carbon_sources"] = source_meta;

  for (const auto& l : carbon.load_carbon) sk_labels.push_back("Load@Bus" + std::to_string(l.bus));
  const int n_ac_loads = static_cast<int>(carbon.load_carbon.size());
  for (const auto& l : carbon.dc_load_carbon) sk_labels.push_back("DCLoad@Bus" + std::to_string(l.bus));
  for (int li = 0; li < static_cast<int>(carbon.load_carbon.size()); ++li) {
    for (const auto& [gi, smw] : carbon.load_carbon.at(static_cast<size_t>(li)).generator_supply_mw) {
      if (smw < 1e-3 || gi < 0 || gi >= n_sources) continue;
      sk_src.push_back(gi); sk_tgt.push_back(n_sources + li); sk_val.push_back(smw);
    }
  }
  for (int li = 0; li < static_cast<int>(carbon.dc_load_carbon.size()); ++li) {
    for (const auto& [gi, smw] : carbon.dc_load_carbon.at(static_cast<size_t>(li)).generator_supply_mw) {
      if (smw < 1e-3 || gi < 0 || gi >= n_sources) continue;
      sk_src.push_back(gi); sk_tgt.push_back(n_sources + n_ac_loads + li); sk_val.push_back(smw);
    }
  }
  out["sankey_labels"] = sk_labels;
  out["sankey_sources"] = sk_src;
  out["sankey_targets"] = sk_tgt;
  out["sankey_values"] = sk_val;

  return out;
}

json annual_carbon_to_json(const hacdcpf::analysis::AnnualCarbonAnalysisResult& annual) {
  json out;
  out["num_steps"] = annual.num_steps;
  out["step_duration_hr"] = annual.step_duration_hr;
  out["num_pf_converged"] = annual.num_pf_converged;
  out["num_carbon_power_balance_verified"] =
      annual.num_carbon_power_balance_verified;
  out["num_carbon_matrix_solved"] = annual.num_carbon_matrix_solved;
  out["num_carbon_verified"] = annual.num_carbon_verified;
  out["all_carbon_verified"] =
      annual.num_steps > 0 && annual.num_carbon_verified == annual.num_steps;
  out["max_node_power_balance_error_mw"] =
      annual.max_node_power_balance_error_mw;
  out["max_matrix_relative_residual"] =
      annual.max_matrix_relative_residual;
  out["max_matrix_condition_estimate"] =
      annual.max_matrix_condition_estimate;
  out["total_generation_emissions_tco2"] = annual.total_generation_emissions_tco2;
  out["total_load_emissions_tco2"] = annual.total_load_emissions_tco2;
  out["total_loss_emissions_tco2"] = annual.total_loss_emissions_tco2;
  out["total_storage_charge_emissions_tco2"] =
      annual.total_storage_charge_emissions_tco2;
  out["total_storage_discharge_emissions_tco2"] =
      annual.total_storage_discharge_emissions_tco2;
  out["initial_storage_carbon_inventory_tco2"] =
      annual.initial_storage_carbon_inventory_tco2;
  out["terminal_storage_carbon_inventory_tco2"] =
      annual.terminal_storage_carbon_inventory_tco2;
  out["storage_carbon_inventory_delta_tco2"] =
      annual.storage_carbon_inventory_delta_tco2;
  out["storage_internal_loss_emissions_tco2"] =
      annual.storage_internal_loss_emissions_tco2;
  out["storage_charge_loss_emissions_tco2"] =
      annual.storage_charge_loss_emissions_tco2;
  out["storage_discharge_loss_emissions_tco2"] =
      annual.storage_discharge_loss_emissions_tco2;
  out["storage_self_discharge_loss_emissions_tco2"] =
      annual.storage_self_discharge_loss_emissions_tco2;
  out["storage_energy_balance_error_mwh"] =
      annual.storage_energy_balance_error_mwh;
  out["storage_energy_balance_abs_error_mwh"] =
      annual.storage_energy_balance_abs_error_mwh;
  out["max_storage_step_energy_balance_error_mwh"] =
      annual.max_storage_step_energy_balance_error_mwh;
  out["storage_inventory_balance_error_tco2"] =
      annual.storage_inventory_balance_error_tco2;
  out["storage_inventory_balance_abs_error_tco2"] =
      annual.storage_inventory_balance_abs_error_tco2;
  out["storage_inventory_balance_error_pct"] =
      annual.storage_inventory_balance_error_pct;
  const double balance_basic =
      annual.total_generation_emissions_tco2 -
      annual.total_load_emissions_tco2 -
      annual.total_loss_emissions_tco2;
  const double balance_storage_adjusted =
      annual.balance_error_storage_adjusted_tco2;
  out["balance_error_tco2"] = balance_basic;
  out["balance_error_storage_adjusted_tco2"] = balance_storage_adjusted;
  out["balance_error_pct"] =
      std::abs(balance_basic) /
      std::max(std::abs(annual.total_generation_emissions_tco2), 1e-12) * 100.0;
  out["balance_error_storage_adjusted_pct"] =
      annual.balance_error_storage_adjusted_pct;

  json steps = json::array();
  for (size_t i = 0; i < annual.step_results.size(); ++i) {
    const auto& s = annual.step_results[i];
    const double step_basic =
        s.total_generation_emissions_tco2 -
        s.total_load_emissions_tco2 -
        s.total_loss_emissions_tco2;
    steps.push_back({{"step", static_cast<int>(i)},
                     {"pf_converged", s.pf_converged},
                     {"carbon_power_balance_verified",
                      s.carbon_power_balance_verified},
                     {"carbon_matrix_solved", s.carbon_matrix_solved},
                     {"carbon_verified", s.carbon_verified},
                     {"max_node_power_balance_error_mw",
                      s.max_node_power_balance_error_mw},
                     {"matrix_relative_residual", s.matrix_relative_residual},
                     {"matrix_condition_estimate", s.matrix_condition_estimate},
                     {"matrix_rank", s.matrix_rank},
                     {"total_generation_emissions_tco2", s.total_generation_emissions_tco2},
                     {"total_load_emissions_tco2", s.total_load_emissions_tco2},
                     {"total_loss_emissions_tco2", s.total_loss_emissions_tco2},
                     {"total_storage_charge_emissions_tco2",
                      s.total_storage_charge_emissions_tco2},
                     {"total_storage_discharge_emissions_tco2",
                      s.total_storage_discharge_emissions_tco2},
                     {"balance_error_tco2", step_basic},
                     {"balance_error_storage_adjusted_tco2",
                      s.balance_error_storage_adjusted_tco2},
                     {"initial_storage_carbon_inventory_tco2",
                      s.initial_storage_carbon_inventory_tco2},
                     {"terminal_storage_carbon_inventory_tco2",
                      s.terminal_storage_carbon_inventory_tco2},
                     {"storage_carbon_inventory_delta_tco2",
                      s.storage_carbon_inventory_delta_tco2},
                     {"storage_charge_loss_emissions_tco2",
                      s.storage_charge_loss_emissions_tco2},
                     {"storage_discharge_loss_emissions_tco2",
                      s.storage_discharge_loss_emissions_tco2},
                     {"storage_self_discharge_loss_emissions_tco2",
                      s.storage_self_discharge_loss_emissions_tco2},
                     {"storage_internal_loss_emissions_tco2",
                      s.storage_internal_loss_emissions_tco2},
                     {"storage_energy_balance_error_mwh",
                      s.storage_energy_balance_error_mwh},
                     {"storage_energy_balance_abs_error_mwh",
                      s.storage_energy_balance_abs_error_mwh},
                     {"storage_inventory_balance_error_tco2",
                      s.storage_inventory_balance_error_tco2}});
  }
  out["step_results"] = steps;

  json buses = json::array();
  for (const auto& b : annual.bus_stats) {
    const bool has_sink = b.energy_mwh > 1e-9;
    const bool sane_potential =
        std::isfinite(b.average_intensity_tco2_mwh) &&
        std::isfinite(b.min_intensity_tco2_mwh) &&
        std::isfinite(b.max_intensity_tco2_mwh) &&
        b.min_intensity_tco2_mwh >= 0.0 &&
        b.max_intensity_tco2_mwh <= 10.0;
    buses.push_back({{"bus_index", b.bus_index},
                     {"is_dc", b.is_dc},
                     {"energy_mwh", b.energy_mwh},
                     {"emissions_tco2", b.emissions_tco2},
                     {"average_intensity_tco2_mwh", b.average_intensity_tco2_mwh},
                     {"min_intensity_tco2_mwh", b.min_intensity_tco2_mwh},
                     {"max_intensity_tco2_mwh", b.max_intensity_tco2_mwh},
                     {"has_carbon_sink", has_sink},
                     {"carbon_potential_valid", sane_potential},
                     {"carbon_potential_outlier", !sane_potential}});
  }
  out["bus_stats"] = buses;

  json loads = json::array();
  for (const auto& l : annual.load_stats)
    loads.push_back({{"load_index", l.load_index},
                     {"bus", l.bus},
                     {"is_dc", l.is_dc},
                     {"energy_mwh", l.energy_mwh},
                     {"emissions_tco2", l.emissions_tco2},
                     {"average_intensity_tco2_mwh", l.average_intensity_tco2_mwh}});
  out["load_stats"] = loads;

  json storage = json::array();
  for (const auto& st : annual.terminal_storage_states)
    storage.push_back({{"storage_index", st.storage_index},
                       {"bus", st.bus},
                       {"is_dc", st.is_dc},
                       {"soc", st.soc},
                       {"stored_energy_mwh", st.stored_energy_mwh},
                       {"soc_carbon_intensity_tco2_mwh", st.soc_carbon_intensity_tco2_mwh}});
  out["terminal_storage_states"] = storage;

  out["hourly_bus_intensity_tco2_mwh"] = annual.hourly_bus_intensity_tco2_mwh;
  out["hourly_load_emissions_tco2"] = annual.hourly_load_emissions_tco2;
  out["hourly_load_energy_mwh"] = annual.hourly_load_energy_mwh;
  return out;
}

const char* dynamic_solver_type_name(hacdcpf::dynamics::DynamicSolverType type) {
  using hacdcpf::dynamics::DynamicSolverType;
  switch (type) {
    case DynamicSolverType::PartitionedEuler: return "PartitionedEuler";
    case DynamicSolverType::PartitionedHeun: return "PartitionedHeun";
    case DynamicSolverType::PartitionedRK4: return "PartitionedRK4";
    case DynamicSolverType::BackwardEulerNewton: return "BackwardEulerNewton";
    case DynamicSolverType::TrapezoidalNewton: return "TrapezoidalNewton";
    case DynamicSolverType::RosenbrockEuler: return "RosenbrockEuler";
    case DynamicSolverType::MassMatrixDae: return "MassMatrixDae";
  }
  return "PartitionedHeun";
}

const char* dynamic_linear_solver_type_name(hacdcpf::dynamics::DynamicLinearSolverType type) {
  using hacdcpf::dynamics::DynamicLinearSolverType;
  switch (type) {
    case DynamicLinearSolverType::EigenSparseLU: return "EigenSparseLU";
    case DynamicLinearSolverType::EigenSparseQR: return "EigenSparseQR";
    case DynamicLinearSolverType::EigenBiCGSTAB: return "EigenBiCGSTAB";
    case DynamicLinearSolverType::KLU: return "KLU";
    case DynamicLinearSolverType::UMFPACK: return "UMFPACK";
    case DynamicLinearSolverType::Pardiso: return "Pardiso";
    case DynamicLinearSolverType::PETSc: return "PETSc";
  }
  return "EigenSparseLU";
}

const char* dynamic_dae_jacobian_mode_name(hacdcpf::dynamics::DynamicDaeJacobianMode mode) {
  using hacdcpf::dynamics::DynamicDaeJacobianMode;
  switch (mode) {
    case DynamicDaeJacobianMode::FiniteDifference: return "FiniteDifference";
    case DynamicDaeJacobianMode::HybridAnalytic: return "HybridAnalytic";
    case DynamicDaeJacobianMode::HybridAnalyticColored: return "HybridAnalyticColored";
  }
  return "HybridAnalytic";
}

hacdcpf::dynamics::DynamicLinearSolverType dynamic_linear_solver_type_from_json(const json& root) {
  using hacdcpf::dynamics::DynamicLinearSolverType;
  const std::string solver =
      root.value("linear_solver", std::string("EigenSparseLU"));
  if (solver == "klu" || solver == "KLU") return DynamicLinearSolverType::KLU;
  if (solver == "umfpack" || solver == "UMFPACK") return DynamicLinearSolverType::UMFPACK;
  if (solver == "bicgstab" || solver == "EigenBiCGSTAB") return DynamicLinearSolverType::EigenBiCGSTAB;
  if (solver == "sparseqr" || solver == "EigenSparseQR") return DynamicLinearSolverType::EigenSparseQR;
  if (solver == "pardiso" || solver == "Pardiso") return DynamicLinearSolverType::Pardiso;
  if (solver == "petsc" || solver == "PETSc") return DynamicLinearSolverType::PETSc;
  return DynamicLinearSolverType::EigenSparseLU;
}

hacdcpf::dynamics::DynamicDaeJacobianMode dynamic_dae_jacobian_mode_from_json(const json& root) {
  using hacdcpf::dynamics::DynamicDaeJacobianMode;
  const std::string mode =
      root.value("dae_jacobian_mode",
                 root.value("jacobian_mode", std::string("hybrid_analytic")));
  if (mode == "fd" || mode == "finite_difference" || mode == "FiniteDifference") {
    return DynamicDaeJacobianMode::FiniteDifference;
  }
  if (mode == "colored" ||
      mode == "hybrid_colored" ||
      mode == "hybrid_analytic_colored" ||
      mode == "HybridAnalyticColored") {
    return DynamicDaeJacobianMode::HybridAnalyticColored;
  }
  return DynamicDaeJacobianMode::HybridAnalytic;
}

hacdcpf::dynamics::DynamicSolverType dynamic_solver_type_from_json(const json& root) {
  using hacdcpf::dynamics::DynamicSolverType;
  const std::string solver =
      root.value("solver_type", root.value("solver", std::string("heun")));
  if (solver == "euler" || solver == "PartitionedEuler") {
    return DynamicSolverType::PartitionedEuler;
  }
  if (solver == "rk4" || solver == "PartitionedRK4") {
    return DynamicSolverType::PartitionedRK4;
  }
  if (solver == "backward_euler" || solver == "BackwardEulerNewton") {
    return DynamicSolverType::BackwardEulerNewton;
  }
  if (solver == "trapezoidal" || solver == "TrapezoidalNewton") {
    return DynamicSolverType::TrapezoidalNewton;
  }
  if (solver == "rosenbrock" || solver == "RosenbrockEuler") {
    return DynamicSolverType::RosenbrockEuler;
  }
  if (solver == "mass_matrix_dae" || solver == "dae" || solver == "MassMatrixDae") {
    return DynamicSolverType::MassMatrixDae;
  }
  return DynamicSolverType::PartitionedHeun;
}

hacdcpf::dynamics::DynamicEventType dynamic_event_type_from_json(const std::string& type) {
  using hacdcpf::dynamics::DynamicEventType;
  if (type == "ACBranchTrip") return DynamicEventType::ACBranchTrip;
  if (type == "ACBranchClose") return DynamicEventType::ACBranchClose;
  if (type == "ACBranchImpedanceScale") return DynamicEventType::ACBranchImpedanceScale;
  if (type == "DCBranchTrip") return DynamicEventType::DCBranchTrip;
  if (type == "DCBranchClose") return DynamicEventType::DCBranchClose;
  if (type == "ACLoadScale") return DynamicEventType::ACLoadScale;
  if (type == "DCLoadScale") return DynamicEventType::DCLoadScale;
  if (type == "GeneratorTrip") return DynamicEventType::GeneratorTrip;
  if (type == "VSCTrip") return DynamicEventType::VSCTrip;
  if (type == "DCDCTrip") return DynamicEventType::DCDCTrip;
  if (type == "StoragePowerStep") return DynamicEventType::StoragePowerStep;
  if (type == "DCStoragePowerStep") return DynamicEventType::DCStoragePowerStep;
  if (type == "FaultShunt") return DynamicEventType::FaultShunt;
  if (type == "ClearFault") return DynamicEventType::ClearFault;
  return DynamicEventType::Custom;
}

const char* dynamic_event_type_name(hacdcpf::dynamics::DynamicEventType type) {
  using hacdcpf::dynamics::DynamicEventType;
  switch (type) {
    case DynamicEventType::ACBranchTrip: return "ACBranchTrip";
    case DynamicEventType::ACBranchClose: return "ACBranchClose";
    case DynamicEventType::ACBranchImpedanceScale: return "ACBranchImpedanceScale";
    case DynamicEventType::DCBranchTrip: return "DCBranchTrip";
    case DynamicEventType::DCBranchClose: return "DCBranchClose";
    case DynamicEventType::ACLoadScale: return "ACLoadScale";
    case DynamicEventType::DCLoadScale: return "DCLoadScale";
    case DynamicEventType::GeneratorTrip: return "GeneratorTrip";
    case DynamicEventType::VSCTrip: return "VSCTrip";
    case DynamicEventType::DCDCTrip: return "DCDCTrip";
    case DynamicEventType::StoragePowerStep: return "StoragePowerStep";
    case DynamicEventType::DCStoragePowerStep: return "DCStoragePowerStep";
    case DynamicEventType::FaultShunt: return "FaultShunt";
    case DynamicEventType::ClearFault: return "ClearFault";
    case DynamicEventType::Custom: return "Custom";
  }
  return "Custom";
}

json dynamic_event_to_json(const hacdcpf::dynamics::DynamicEvent& event) {
  return json{{"time_s", event.time_s},
              {"type", dynamic_event_type_name(event.type)},
              {"component_index", event.component_index},
              {"target_id", event.target_id},
              {"bus", event.bus},
              {"phase", event.phase},
              {"value", event.value},
              {"duration_s", event.duration_s},
              {"component_type", event.component_type},
              {"target_type", event.target_type},
              {"params", event.params},
              {"label", event.label}};
}

