  svr.Post("/api/session/load_matpower",
           [&matpower_dir](const httplib::Request& req, httplib::Response& res) {
    try {
      const auto j = json::parse(req.body.empty() ? "{}" : req.body);
      std::string filename = j.value("filename", "");
      if (filename.empty()) throw std::runtime_error("No filename provided");
      if (filename.find('/') != std::string::npos ||
          filename.find('\\') != std::string::npos ||
          filename.find("..") != std::string::npos) {
        throw std::runtime_error("Invalid filename");
      }
      fs::path fpath = fs::path(matpower_dir) / filename;
      if (!fs::exists(fpath)) throw std::runtime_error("File not found: " + filename);
      auto sys = hacdcpf::io::parse_matpower(fpath.string());
      sys.name = filename;
	      std::lock_guard<std::mutex> lk(g_session.mu);
	      g_session.current_system = std::move(sys);
	      g_session.current_name = filename;
	      g_session.reliability_configuration = {};
	      clear_preserved_three_phase(g_session);
	      g_session.external_grid_carbon_profiles.clear();
	      clear_cached_analysis(g_session);
      // Large MATPOWER cases use one structured model payload.  Returning the
      // same model both as flattened arrays and as an escaped JSON string more
      // than doubles response size and forces an additional browser JSON parse.
      // Keep the legacy shape for smaller API clients that consume its flattened
      // component arrays directly.
      const bool compact_load = g_session.current_system->ac.buses.size() >= 5000;
      auto summary = compact_load
                         ? system_summary(*g_session.current_system, false, true)
                         : system_summary(*g_session.current_system);
      if (!compact_load) {
        summary["_raw_json"] =
            hacdcpf::io::to_json(*g_session.current_system, 2);
      }
      res.set_content(summary.dump(), "application/json");
    } catch (const std::exception& e) {
      res.status = 400;
      res.set_content(json{{"error", e.what()}}.dump(), "application/json");
    }
  });

  // ---- Session: import a browser-uploaded PSD-BPA / DSP .dat card file ----
  // The request body is intentionally raw binary: legacy files can be GBK and
  // decoding them as browser text would corrupt both names and fixed columns.
  svr.Post("/api/session/load_bpa_dat",
           [](const httplib::Request& req, httplib::Response& res) {
    try {
      if (req.body.empty()) throw std::runtime_error("Empty BPA/DSP DAT upload");
      auto imported = hacdcpf::io::parse_bpa_dat_string(req.body);
      if (imported.report.has_errors()) {
        std::string message = "BPA/DSP DAT import failed";
        for (const auto& record : imported.report.records) {
          if (record.severity == hacdcpf::io::ImportSeverity::Error) {
            message += ": " + record.message;
            break;
          }
        }
        throw std::runtime_error(message);
      }

      json warnings = json::array();
      json records = json::array();
      for (const auto& record : imported.report.records) {
        records.push_back({{"source_locator", record.source_locator},
                           {"disposition", hacdcpf::io::to_string(record.disposition)},
                           {"reason_code", hacdcpf::io::to_string(record.reason_code)},
                           {"severity", hacdcpf::io::to_string(record.severity)},
                           {"message", record.message}});
        if (record.severity == hacdcpf::io::ImportSeverity::Warning) {
          warnings.push_back(record.message);
        }
      }

      std::lock_guard<std::mutex> lk(g_session.mu);
      g_session.current_system = std::move(imported.system);
      g_session.current_name = g_session.current_system->name;
      g_session.reliability_configuration = {};
      clear_preserved_three_phase(g_session);
      g_session.external_grid_carbon_profiles.clear();
      clear_cached_analysis(g_session);
      auto summary = system_summary(*g_session.current_system);
      summary["_raw_json"] = hacdcpf::io::to_json(*g_session.current_system, 2);
      summary["_io_warnings"] = std::move(warnings);
      summary["_bpa_import_report"] = {
          {"binding_level", hacdcpf::io::to_string(imported.report.binding_level)},
          {"unit_assertion", hacdcpf::io::to_string(imported.report.unit_assertion)},
          {"accepted", imported.report.summary.accepted},
          {"coerced", imported.report.summary.coerced},
          {"rejected", imported.report.summary.rejected},
          {"skipped", imported.report.summary.skipped},
          {"records", std::move(records)}};
      res.set_content(summary.dump(), "application/json");
    } catch (const std::exception& e) {
      res.status = 400;
      res.set_content(json{{"error", e.what()}}.dump(), "application/json");
    }
  });

  svr.Post("/api/session/load_json_string",
           [](const httplib::Request& req, httplib::Response& res) {
    try {
      const auto j = json::parse(req.body.empty() ? "{}" : req.body);
      std::string js = j.value("json_string", "");
      if (js.empty()) throw std::runtime_error("Empty JSON string");
	      const bool preserve_reliability_configuration =
	          j.value("preserve_reliability_configuration", false);
	      auto sys = hacdcpf::io::from_json(js);

	      std::lock_guard<std::mutex> lk(g_session.mu);
	      if (!sys.three_phase_ac.has_value() && g_session.preserved_three_phase_ac.has_value()) {
	        sys.three_phase_ac = g_session.preserved_three_phase_ac;
	      } else if (sys.three_phase_ac.has_value()) {
	        g_session.preserved_three_phase_ac = sys.three_phase_ac;
	      } else {
	        clear_preserved_three_phase(g_session);
	      }
	      g_session.current_system = std::move(sys);
	      g_session.current_name = g_session.current_system->name;
	      if (!preserve_reliability_configuration)
	        g_session.reliability_configuration = {};
	      g_session.external_grid_carbon_profiles.clear();
      clear_cached_analysis(g_session);
      auto summary = system_summary(*g_session.current_system);
      summary["_raw_json"] = hacdcpf::io::to_json(*g_session.current_system, 2);
      res.set_content(summary.dump(), "application/json");
    } catch (const std::exception& e) {
      res.status = 400;
      res.set_content(json{{"error", e.what()}}.dump(), "application/json");
    }
  });

  svr.Post("/api/session/load_bpa_dat",
           [](const httplib::Request& req, httplib::Response& res) {
    try {
      // Two body forms: JSON {"dat_string": "..."} (UTF-8 text) or the raw
      // .dat bytes (octet-stream; may be GBK-encoded — the importer converts
      // bus names to UTF-8).
      std::string dat;
      if (!req.body.empty() && req.body.front() == '{') {
        const auto j = json::parse(req.body);
        dat = j.value("dat_string", "");
      } else {
        dat = req.body;
      }
      if (dat.empty()) throw std::runtime_error("Empty DAT content");
      auto imported = hacdcpf::io::parse_bpa_dat_string(dat);
      if (imported.report.has_errors()) {
        std::string msg = "BPA DAT import failed:";
        for (const auto& rec : imported.report.records)
          if (rec.severity == hacdcpf::io::ImportSeverity::Error)
            msg += " " + rec.message;
        throw std::runtime_error(msg);
      }
      auto sys = std::move(imported.system);

      std::lock_guard<std::mutex> lk(g_session.mu);
      if (!sys.three_phase_ac.has_value() && g_session.preserved_three_phase_ac.has_value()) {
        sys.three_phase_ac = g_session.preserved_three_phase_ac;
      } else if (sys.three_phase_ac.has_value()) {
        g_session.preserved_three_phase_ac = sys.three_phase_ac;
      } else {
        clear_preserved_three_phase(g_session);
      }
      g_session.current_system = std::move(sys);
      g_session.current_name = g_session.current_system->name;
      g_session.reliability_configuration = {};
      g_session.external_grid_carbon_profiles.clear();
      clear_cached_analysis(g_session);
      auto summary = system_summary(*g_session.current_system);
      summary["_raw_json"] = hacdcpf::io::to_json(*g_session.current_system, 2);
      // Surface non-fatal import notes (LCC approximation, skipped cards).
      json notes = json::array();
      for (const auto& rec : imported.report.records)
        if (rec.severity != hacdcpf::io::ImportSeverity::Info)
          notes.push_back(rec.source_locator + ": " + rec.message);
      summary["_import_notes"] = std::move(notes);
      res.set_content(summary.dump(), "application/json");
    } catch (const std::exception& e) {
      res.status = 400;
      res.set_content(json{{"error", e.what()}}.dump(), "application/json");
    }
  });

