  // ---- Session: export the current system as a MATPOWER .m case ----
  // MATPOWER is an AC steady-state format. The library exporter preserves the
  // bounded AC subset and emits a header note in the .m file when hybrid/rich
  // structures are outside that scope.
  svr.Post("/api/session/export_matpower",
           [](const httplib::Request&, httplib::Response& res) {
    try {
      std::lock_guard<std::mutex> lk(g_session.mu);
      if (!g_session.current_system) throw std::runtime_error("No system loaded");
      const auto& sys = *g_session.current_system;
      json warnings = json::array();
      hacdcpf::HybridPowerSystem export_sys = sys;
      const bool has_ac_rich_series = !sys.ac.transformers_2w.empty() ||
          !sys.ac.transformers_3w.empty() || !sys.ac.switches.empty() ||
          !sys.ac.circuit_breakers.empty();
      if (has_ac_rich_series) {
        try {
          export_sys = hacdcpf::project_to_canonical_models(sys, /*strip_dead=*/false);
          warnings.push_back(
              "AC 变压器/开关/断路器已按 canonical 等值模型导出为 MATPOWER branch 行；原始设备铭牌字段不属于 MATPOWER 格式。");
        } catch (const std::exception& e) {
          warnings.push_back(
              std::string("canonical 等值转换失败，已退回原始 AC 子集导出；部分 rich AC 串联设备可能被省略：") +
              e.what());
        }
      }
      const std::string matpower = hacdcpf::io::to_matpower(export_sys);
      std::string safe;
      for (char ch : g_session.current_name) {
        safe += (std::isalnum(static_cast<unsigned char>(ch)) || ch == '-' || ch == '_')
                    ? ch : '_';
      }
      if (safe.empty()) safe = "system";

      if (!sys.dc.buses.empty() || !sys.dc.branches.empty() ||
          !sys.vsc_converters.empty() || !sys.dc.dcdc_converters.empty() ||
          !sys.energy_routers.empty()) {
        warnings.push_back(
            "MATPOWER 导出当前为 AC 子集；DC 网络、换流器、DC/DC 和能量路由器不会写入 .m 文件。");
      }
      if (!sys.ac.static_generators.empty() || !sys.ac.renewable_gens.empty() ||
          !sys.ac.pv_systems.empty() || !sys.ac.external_grids.empty() ||
          !sys.ac.storage.empty()) {
        warnings.push_back(
            "静态电源、可再生电源、PV、外部电网和储能等 rich AC 元件未映射到 MATPOWER gen 矩阵。");
      }

      res.set_content(json{{"matpower_string", matpower},
                           {"name", safe},
                           {"warnings", warnings}}
                          .dump(),
                      "application/json");
    } catch (const std::exception& e) {
      res.status = 400;
      res.set_content(json{{"error", e.what()}}.dump(), "application/json");
    }
  });

  // ---- Session: export the BPA-representable steady-state subset ----
  svr.Post("/api/session/export_bpa_dat",
           [](const httplib::Request&, httplib::Response& res) {
    try {
      std::lock_guard<std::mutex> lk(g_session.mu);
      if (!g_session.current_system) throw std::runtime_error("No system loaded");
      const auto& sys = *g_session.current_system;
      hacdcpf::HybridPowerSystem export_sys = sys;
      json warnings = json::array();
      const bool has_rich_series = !sys.ac.transformers_2w.empty() ||
          !sys.ac.transformers_3w.empty() || !sys.ac.switches.empty() ||
          !sys.ac.circuit_breakers.empty();
      if (has_rich_series) {
        try {
          export_sys = hacdcpf::project_to_canonical_models(sys, /*strip_dead=*/false);
          warnings.push_back(
              "AC变压器、开关和断路器已按canonical等值支路导出；原始设备铭牌与控制字段不属于BPA基础卡片范围。");
        } catch (const std::exception& e) {
          warnings.push_back(std::string(
              "canonical等值转换失败，已退回原始支路子集；部分rich串联设备可能被省略：") + e.what());
        }
      }
      warnings.push_back(
          "BPA母线名限8字节；导出文件使用稳定ASCII标识A0000001...，原始UTF-8名称不写入固定列。");
      if (!sys.ac.static_generators.empty() || !sys.ac.renewable_gens.empty() ||
          !sys.ac.pv_systems.empty() || !sys.ac.external_grids.empty() ||
          !sys.ac.storage.empty()) {
        warnings.push_back(
            "部分rich AC电源/储能类型不能由BPA基础B卡完整表达；仅canonical发电机聚合值可导出。");
      }
      if (!sys.dc.loads.empty() || !sys.dc.static_generators.empty() ||
          !sys.dc.dc_static_generators.empty() || !sys.dc.pv_arrays.empty() ||
          !sys.dc.storage.empty() || !sys.dc.dc_storage.empty() ||
          !sys.dc.dcdc_converters.empty() || !sys.energy_routers.empty()) {
        warnings.push_back(
            "DAT导出仅表示两端直流线路及其AC/DC换流端；其他DC资产、DC/DC和能量路由器被省略。");
      }
      if (!sys.dc.branches.empty() && !sys.vsc_converters.empty()) {
        warnings.push_back(
            "两端直流链路按BPA BD/LD卡片导出；VSC控制、损耗和限值会退化为LCC式定功率/定直流电压近似。");
      }
      const std::string dat = hacdcpf::io::to_bpa_dat(export_sys);
      std::string safe;
      for (char ch : g_session.current_name) {
        safe += (std::isalnum(static_cast<unsigned char>(ch)) || ch == '-' || ch == '_')
                    ? ch : '_';
      }
      if (safe.empty()) safe = "system";
      res.set_content(json{{"dat_string", dat},
                           {"name", safe},
                           {"format", "PSD-BPA/DSP fixed-column DAT"},
                           {"warnings", warnings}}
                          .dump(),
                      "application/json");
    } catch (const std::exception& e) {
      res.status = 400;
      res.set_content(json{{"error", e.what()}}.dump(), "application/json");
    }
  });

  // ---- Session: export the current system as an ETAP-schema .xlsx workbook ----
  // Returns the raw binary workbook (one sheet per ETAP element class) so the
  // browser can download it directly.  save_etap() throws if ETAP support is not
  // compiled in (HACDCPF_ENABLE_ETAP off), which surfaces here as a 400 error.
  svr.Post("/api/session/export_etap",
           [](const httplib::Request&, httplib::Response& res) {
    std::string tmp;
    try {
      std::string name;
      {
        std::lock_guard<std::mutex> lk(g_session.mu);
        if (!g_session.current_system) throw std::runtime_error("No system loaded");
        name = g_session.current_name;
        // Write to a unique temp workbook, then read the bytes back out.
        static std::atomic<int> export_counter{0};
        tmp = (std::filesystem::temp_directory_path() /
               ("hacdcpf_gui_export_" +
                std::to_string(export_counter.fetch_add(1)) + ".xlsx"))
                  .string();
        hacdcpf::io::EtapIoReport rep;
        hacdcpf::io::save_etap(*g_session.current_system, tmp, rep);
      }
      std::ifstream ifs(tmp, std::ios::binary);
      if (!ifs) throw std::runtime_error("Failed to read generated ETAP workbook");
      std::string bytes((std::istreambuf_iterator<char>(ifs)),
                        std::istreambuf_iterator<char>());
      ifs.close();
      std::error_code ec;
      std::filesystem::remove(tmp, ec);

      // Sanitize the system name into a safe download filename.
      std::string safe;
      for (char ch : name) {
        safe += (std::isalnum(static_cast<unsigned char>(ch)) || ch == '-' || ch == '_')
                    ? ch : '_';
      }
      if (safe.empty()) safe = "system";
      res.set_header("Content-Disposition",
                     "attachment; filename=\"" + safe + ".xlsx\"");
      res.set_content(
          bytes,
          "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    } catch (const std::exception& e) {
      if (!tmp.empty()) { std::error_code ec; std::filesystem::remove(tmp, ec); }
      res.status = 400;
      res.set_content(json{{"error", e.what()}}.dump(), "application/json");
    }
  });

