    // ---- Real-time fixed-commitment market + two-settlement deviations ----
    svr.Post("/api/session/run_real_time_market",
             [](const httplib::Request& req, httplib::Response& res) {
      try {
        hacdcpf::HybridPowerSystem sys;
        {
          std::lock_guard<std::mutex> lk(g_session.mu);
          if (!g_session.current_system) {
            throw std::runtime_error("No system loaded");
          }
          sys = *g_session.current_system;
        }
        if (g_session.busy.exchange(true)) {
          res.status = 409;
          res.set_content(
              json{{"error", "Another analysis is already running"}}.dump(),
              "application/json");
          return;
        }
        const auto j = json::parse(req.body.empty() ? "{}" : req.body);
        const int num_periods = std::max(1, j.value("num_steps", 24));
        hacdcpf::TimeSeriesData day_ahead_series;
        {
          std::lock_guard<std::mutex> lk(g_session.mu);
          if (g_session.ts_data.num_steps != num_periods ||
              g_session.ts_data.profiles.empty()) {
            g_session.ts_data = make_default_ts_data(num_periods);
          }
          day_ahead_series = g_session.ts_data;
        }
        assign_available_default_profiles(sys, day_ahead_series);
        auto day_ahead_options = market_options_from_json(j, sys);
        const auto day_ahead = hacdcpf::market::run_day_ahead_market(
            sys, day_ahead_series, day_ahead_options);
        const auto realized_series = realized_market_time_series(
            day_ahead_series, j);

        json real_time_json = j;
        if (j.contains("real_time") && j["real_time"].is_object()) {
          for (auto it = j["real_time"].begin();
               it != j["real_time"].end(); ++it) {
            real_time_json[it.key()] = it.value();
          }
        }
        hacdcpf::market::RealTimeMarketOptions real_time_options;
        real_time_options.market_options =
            market_options_from_json(real_time_json, sys);
        real_time_options.ancillary_services =
            ancillary_options_from_json(j, sys);
        const auto real_time = hacdcpf::market::run_real_time_market(
            sys, day_ahead_series, realized_series, day_ahead,
            real_time_options);
        res.set_content(
            real_time_market_json(day_ahead, real_time).dump(),
            "application/json");
        g_session.busy.store(false);
      } catch (const std::exception& error) {
        g_session.busy.store(false);
        res.status = 400;
        res.set_content(json{{"error", error.what()}}.dump(),
                        "application/json");
      }
    });

    // ---- Repeated participant best-response game ----
    svr.Post("/api/session/run_repeated_market_game",
             [](const httplib::Request& req, httplib::Response& res) {
      try {
        hacdcpf::HybridPowerSystem sys;
        {
          std::lock_guard<std::mutex> lk(g_session.mu);
          if (!g_session.current_system) {
            throw std::runtime_error("No system loaded");
          }
          sys = *g_session.current_system;
        }
        if (g_session.busy.exchange(true)) {
          res.status = 409;
          res.set_content(
              json{{"error", "Another analysis is already running"}}.dump(),
              "application/json");
          return;
        }
        const auto j = json::parse(req.body.empty() ? "{}" : req.body);
        const int num_periods = std::max(1, j.value("num_steps", 1));
        hacdcpf::TimeSeriesData day_ahead_series;
        {
          std::lock_guard<std::mutex> lk(g_session.mu);
          if (g_session.ts_data.num_steps != num_periods ||
              g_session.ts_data.profiles.empty()) {
            g_session.ts_data = make_default_ts_data(num_periods);
          }
          day_ahead_series = g_session.ts_data;
        }
        assign_available_default_profiles(sys, day_ahead_series);
        const auto realized_series = realized_market_time_series(
            day_ahead_series, j);

        hacdcpf::market::RepeatedGameOptions game_options;
        game_options.day_ahead_options = market_options_from_json(j, sys);
        json real_time_json = j;
        if (j.contains("real_time") && j["real_time"].is_object()) {
          for (auto it = j["real_time"].begin();
               it != j["real_time"].end(); ++it) {
            real_time_json[it.key()] = it.value();
          }
        }
        game_options.real_time_options.market_options =
            market_options_from_json(real_time_json, sys);
        game_options.real_time_options.ancillary_services =
            ancillary_options_from_json(j, sys);
        const auto game = j.value("game", json::object());
        game_options.max_rounds =
            std::max(1, game.value("max_rounds", 4));
        game_options.markup_step_fraction = std::max(
            0.0, game.value("markup_step_fraction", 0.05));
        game_options.withholding_step_fraction = std::max(
            0.0, game.value("withholding_step_fraction", 0.05));
        game_options.maximum_markup_fraction = std::max(
            0.0, game.value("maximum_markup_fraction", 1.0));
        game_options.maximum_withholding_fraction = std::clamp(
            game.value("maximum_withholding_fraction", 0.50), 0.0, 0.95);
        game_options.profit_improvement_tolerance = std::max(
            0.0, game.value("profit_improvement_tolerance", 1e-4));
        game_options.include_cost_based_participants =
            game.value("include_cost_based_participants", false);
        game_options.run_real_time = game.value("run_real_time", true);
        const auto result = hacdcpf::market::run_repeated_market_game(
            sys, day_ahead_series, realized_series, game_options);
        res.set_content(repeated_game_json(result).dump(),
                        "application/json");
        g_session.busy.store(false);
      } catch (const std::exception& error) {
        g_session.busy.store(false);
        res.status = 400;
        res.set_content(json{{"error", error.what()}}.dump(),
                        "application/json");
      }
    });

    // ---- Carbon Flow Analysis ----
    svr.Post("/api/session/run_carbon",
             [](const httplib::Request&, httplib::Response& res) {
      try {
        const auto request_started = std::chrono::steady_clock::now();
        hacdcpf::HybridPowerSystem sys;
        {
          std::lock_guard<std::mutex> lk(g_session.mu);
          if (!g_session.current_system) throw std::runtime_error("No system loaded");
          sys = *g_session.current_system;
        }
        if (g_session.busy.exchange(true)) {
          res.status = 409;
          res.set_content(json{{"error","Another analysis is already running"}}.dump(), "application/json");
          return;
        }
        g_session.cancel.store(false);
        hacdcpf::analysis::CarbonAnalysisOptions ca_opt; ca_opt.verbose = false;
        hacdcpf::analysis::CarbonAnalysisResult carbon;
        {
          std::lock_guard<std::mutex> lk(g_session.mu);
          if (!g_session.last_pf_result || !g_session.last_pf_result->converged) {
            throw std::runtime_error(
                "请先运行潮流计算，并确保潮流收敛后再进行静态碳流分析");
          }
          if (g_session.last_pf_system) {
            sys = *g_session.last_pf_system;
          }
          carbon = hacdcpf::analysis::compute_carbon_analysis(
              sys, *g_session.last_pf_result, ca_opt);
        }
        json out = carbon_analysis_to_json(sys, carbon);
        { std::lock_guard<std::mutex> lk(g_session.mu);
          out["pf_source"] = g_session.last_pf_method;
          out["requires_pf"] = true;
        }
        out["execution_time_sec"] = elapsed_seconds(request_started);
        res.set_content(out.dump(), "application/json");
        g_session.busy.store(false);
      } catch (const std::exception& e) {
        g_session.busy.store(false);
        res.status = 400;
        res.set_content(json{{"error", e.what()}}.dump(), "application/json");
      }
    });

    // ---- Dynamic Carbon Flow Analysis (TS-PF snapshots + storage carbon recursion) ----
    svr.Post("/api/session/run_dynamic_carbon",
             [materialize_loads_and_apply_binding]
             (const httplib::Request& req, httplib::Response& res) {
      try {
        const auto request_started = std::chrono::steady_clock::now();
        hacdcpf::TimeSeriesData ts_data;
        hacdcpf::TimeSeriesPFResult ts_result;
        hacdcpf::HybridPowerSystem current_sys;
        bool skip_uc = true;
        bool run_opf = false;
        int n_remat = 0;
        bool ts_binding_active = false;
        std::vector<Session::ExternalGridCarbonProfile> grid_carbon_profiles;
        const auto j = json::parse(req.body.empty() ? "{}" : req.body);
        const bool use_last_tspf = j.value("use_last_tspf", true);
        const bool request_has_num_steps =
            j.contains("num_steps") && j["num_steps"].is_number_integer();
        const int requested_num_steps =
            request_has_num_steps ? j["num_steps"].get<int>() : -1;
        {
          std::lock_guard<std::mutex> lk(g_session.mu);
          if (!g_session.current_system) throw std::runtime_error("No system loaded");
          current_sys = *g_session.current_system;
          if (use_last_tspf) {
            if (!g_session.last_tspf_result) {
              throw std::runtime_error(
                  "请先在“时序潮流”模块运行时序潮流或时序OPF，再进行动态碳流分析");
            }
            ts_result = *g_session.last_tspf_result;
            ts_data = g_session.last_tspf_data;
            skip_uc = g_session.last_tspf_skip_uc;
            run_opf = g_session.last_tspf_run_opf;
            n_remat = -1;
            ts_binding_active = g_session.ts_binding.valid;
            if (request_has_num_steps && requested_num_steps != ts_result.num_steps) {
              throw std::runtime_error(
                  "动态碳流请求步数与最近一次时序潮流结果不一致，请先重新运行时序潮流后再做动态碳流，或把 num_steps 设为最近一次时序潮流步数。");
            }
          }
          grid_carbon_profiles = g_session.external_grid_carbon_profiles;
        }

        if (g_session.busy.exchange(true)) {
          res.status = 409;
          res.set_content(json{{"error","Another analysis is already running"}}.dump(), "application/json");
          return;
        }
        g_session.cancel.store(false);

        if (!use_last_tspf) {
          hacdcpf::HybridPowerSystem sys_ts;
          Session::TsBindingSpec spec;
          {
            std::lock_guard<std::mutex> lk(g_session.mu);
            if (!g_session.current_system) throw std::runtime_error("No system loaded");
            const int ns = request_has_num_steps ? requested_num_steps : 24;
            if (g_session.ts_data.num_steps != ns || g_session.ts_data.profiles.empty())
              g_session.ts_data = make_default_ts_data(ns);
            sys_ts = *g_session.current_system;
            ts_data = g_session.ts_data;
            spec = g_session.ts_binding;
          }
          n_remat = materialize_loads_and_apply_binding(sys_ts, spec);
          ts_binding_active = spec.valid;
          skip_uc = j.value("skip_uc", false);
          run_opf = j.value("run_opf", false);

          assign_available_default_profiles(sys_ts, ts_data);

          hacdcpf::TimeSeriesPFOptions ts_opts;
          ts_opts.skip_uc = skip_uc;
          ts_opts.run_opf = run_opf;
          ts_opts.keep_system_snapshots = true;
          ts_opts.verbose = false;
          ts_result = hacdcpf::solve_time_series_pf(sys_ts, ts_data, ts_opts);
        }
        if (ts_result.num_steps != ts_data.num_steps) {
          throw std::runtime_error(
              "动态碳流缓存/结果步数与时序数据步数不一致，请重新运行时序潮流后再做动态碳流。");
        }
        apply_current_carbon_factors_to_tspf(current_sys, ts_result);
        int applied_grid_carbon_profiles = 0;
        for (size_t t = 0; t < ts_result.pf_system_snapshots.size(); ++t) {
          auto& snapshot = ts_result.pf_system_snapshots[t];
          for (auto& eg : snapshot.ac.external_grids) {
            for (const auto& profile : grid_carbon_profiles) {
              const bool matches =
                  (profile.index == eg.index) ||
                  (profile.bus == eg.bus) ||
                  (!profile.name.empty() && profile.name == eg.name);
              if (!matches || profile.values_tco2_mwh.empty()) continue;
              const size_t pos = std::min(t, profile.values_tco2_mwh.size() - 1);
              eg.emission_factor_tco2_mwh = profile.values_tco2_mwh[pos];
              ++applied_grid_carbon_profiles;
              break;
            }
          }
        }

        hacdcpf::analysis::AnnualCarbonAnalysisOptions ca_opts;
        ca_opts.keep_hourly_bus_intensity = true;
        ca_opts.keep_hourly_load_emissions = true;
        ca_opts.keep_hourly_load_energy = true;
        auto annual = hacdcpf::analysis::compute_annual_carbon_analysis(
            ts_result, ts_data.step_duration_hr, ca_opts);

        json out = annual_carbon_to_json(annual);
        if (out.contains("step_results") && out["step_results"].is_array()) {
          for (size_t i = 0; i < out["step_results"].size(); ++i) {
            const bool has_opf =
                run_opf &&
                i < ts_result.opf_results.size();
            out["step_results"][i]["opf_converged"] =
                has_opf ? json(ts_result.opf_results[i].converged) : json(nullptr);
          }
        }
        out["num_loads_materialized"] = n_remat;
        out["ts_binding_active"] = ts_binding_active;
        out["result_source"] = use_last_tspf ? "last_tspf" : "recomputed_tspf";
        out["skip_uc"] = skip_uc;
        out["run_opf"] = run_opf;
        out["storage_dispatch_source"] =
            run_opf ? "opf" :
            ((!skip_uc && ts_result.uc_schedule.feasible) ? "uc" : "fixed_or_fallback");
        out["num_converged"] = ts_result.num_converged;
        out["num_pf_converged"] = ts_result.num_converged;
        out["num_opf_converged"] = ts_result.num_opf_converged;
        out["uc_feasible"] = ts_result.uc_schedule.feasible;
        out["uc_solver_name"] = ts_result.uc_schedule.solver_name;
        out["dynamic_storage_enabled"] =
            ts_result.pf_system_snapshots.size() == ts_result.pf_results.size();
        out["external_grid_carbon_profiles"] =
            static_cast<int>(grid_carbon_profiles.size());
        out["external_grid_carbon_profile_applications"] =
            applied_grid_carbon_profiles;
        out["execution_time_sec"] = elapsed_seconds(request_started);

        res.set_content(out.dump(), "application/json");
        g_session.busy.store(false);
      } catch (const std::exception& e) {
        g_session.busy.store(false);
        res.status = 400;
        res.set_content(json{{"error", e.what()}}.dump(), "application/json");
      } catch (...) {
        g_session.busy.store(false);
        res.status = 500;
        res.set_content(json{{"error", "Unknown internal error in dynamic carbon flow"}}.dump(), "application/json");
      }
    });

    // ---- Reactive Power Optimization input inventory ----
    svr.Post("/api/session/rpo_inputs",
             [](const httplib::Request& req, httplib::Response& res) {
      try {
        hacdcpf::HybridPowerSystem sys;
        {
          std::lock_guard<std::mutex> lk(g_session.mu);
          if (!g_session.current_system)
            throw std::runtime_error("No system loaded");
          sys = *g_session.current_system;
        }
        const auto j = json::parse(req.body.empty() ? "{}" : req.body);
        hacdcpf::opf::RPOOptions opt;
        opt.max_tap_move = std::clamp(j.value("max_tap_move", 2), -1, 1000);
        opt.restrict_tap_indices = j.value("restrict_tap_indices", false);
        if (j.contains("enabled_tap_indices") &&
            j["enabled_tap_indices"].is_array()) {
          for (const auto& value : j["enabled_tap_indices"])
            if (value.is_number_integer())
              opt.enabled_tap_indices.push_back(value.get<int>());
        }
        res.set_content(rpo_control_inventory_json(sys, opt).dump(),
                        "application/json");
      } catch (const std::exception& e) {
        res.status = 400;
        res.set_content(json{{"error", e.what()}}.dump(),
                        "application/json");
      }
    });

    // ---- Reactive Power Optimization (local discrete search + AC/DC NLP) ----
    svr.Post("/api/session/run_rpo",
             [](const httplib::Request& req, httplib::Response& res) {
      try {
        hacdcpf::HybridPowerSystem sys;
        {
          std::lock_guard<std::mutex> lk(g_session.mu);
          if (!g_session.current_system) throw std::runtime_error("No system loaded");
          sys = *g_session.current_system;
        }
        if (g_session.busy.exchange(true)) {
          res.status = 409;
          res.set_content(json{{"error","Another analysis is already running"}}.dump(), "application/json");
          return;
        }
        g_session.cancel.store(false);
        const auto j = json::parse(req.body.empty() ? "{}" : req.body);
        const std::string obj_type = j.value("objective", std::string("voltage"));

        hacdcpf::opf::RPOOptions rpo_opt;
        if (obj_type == "loss")
          rpo_opt.objective = hacdcpf::opf::RPOObjective::MinActiveLoss;
        else if (obj_type == "combined")
          rpo_opt.objective = hacdcpf::opf::RPOObjective::Combined;
        else
          rpo_opt.objective = hacdcpf::opf::RPOObjective::MinVoltageDeviation;
        rpo_opt.vdev_weight    = j.value("vdev_weight", 1.0);
        rpo_opt.loss_weight    = j.value("loss_weight", 1.0);
        rpo_opt.v_target       = j.value("v_target", 1.0);
        rpo_opt.gap_tol        = j.value("mip_gap", 0.01);
        rpo_opt.time_limit_sec = j.value("time_limit_s", 120.0);
        rpo_opt.max_nodes      = std::max(1, j.value("max_evaluations", 50000));
        rpo_opt.max_ipm_iter   = std::max(1, j.value("max_ipm_iter", 2000));
        rpo_opt.ipm_tol        = std::max(1e-12, j.value("ipm_tol", 1e-6));
        rpo_opt.stationarity_tol =
            std::max(1e-12, j.value("stationarity_tol", 1e-3));
        rpo_opt.max_tap_move =
            std::clamp(j.value("max_tap_move", 2), -1, 1000);
        rpo_opt.restrict_tap_indices =
            j.value("restrict_tap_indices", false);
        if (j.contains("enabled_tap_indices") &&
            j["enabled_tap_indices"].is_array()) {
          for (const auto& value : j["enabled_tap_indices"])
            if (value.is_number_integer())
              rpo_opt.enabled_tap_indices.push_back(value.get<int>());
        }
        rpo_opt.enforce_branch_limits = j.value("branch_limits", true);
        rpo_opt.enforce_converter_capacity =
            j.value("converter_capacity", true);
        rpo_opt.enforce_converter_current_limits =
            j.value("converter_current", true);
        rpo_opt.enforce_converter_modulation_limits =
            j.value("converter_modulation", true);

        if (j.value("relax_only", false)) {
          rpo_opt.max_nodes = 1;   // root relaxation only
        }

        auto result = hacdcpf::solve_rpo(sys, rpo_opt);

        // Rebuild the optimized authored system, then solve an independent OPF
        // and replay the optimized operating point through PF.  This is kept
        // separate from the RPO's inner solves so agreement is auditable.
        hacdcpf::HybridPowerSystem optimized_sys = sys;
        hacdcpf::opf::apply_rpo_discrete_solution(optimized_sys, result);
        const bool independent_uses_unit_cost =
            result.effective_inner_nlp_objective ==
            hacdcpf::opf::RPOInnerObjective::LossEconomic;
        if (independent_uses_unit_cost) {
          for (auto& generator : optimized_sys.ac.generators) {
            generator.cost_c0 = 0.0;
            generator.cost_c1 = 1.0;
            generator.cost_c2 = 0.0;
          }
        }

        hacdcpf::opf::ACOPFOptions independent_opt;
        independent_opt.ac_solver_backend =
            hacdcpf::opf::ACOPFSolverBackend::Auto;
        independent_opt.enable_primal_dual = true;
        independent_opt.use_parity_ipm = true;
        independent_opt.allow_fallback = true;
        if (independent_uses_unit_cost) {
          independent_opt.objective = hacdcpf::opf::ACOPFObjective::Economic;
        } else if (rpo_opt.objective == hacdcpf::opf::RPOObjective::MinActiveLoss) {
          independent_opt.objective = hacdcpf::opf::ACOPFObjective::ActiveLoss;
        } else if (rpo_opt.objective == hacdcpf::opf::RPOObjective::Combined) {
          independent_opt.objective =
              hacdcpf::opf::ACOPFObjective::VoltageDeviationAndLoss;
        } else {
          independent_opt.objective =
              hacdcpf::opf::ACOPFObjective::VoltageDeviation;
        }
        independent_opt.voltage_target_pu = rpo_opt.v_target;
        independent_opt.voltage_deviation_weight = rpo_opt.vdev_weight;
        independent_opt.active_loss_weight = rpo_opt.loss_weight;
        independent_opt.max_inner_iterations = rpo_opt.max_ipm_iter;
        independent_opt.max_outer_iterations = 1;
        independent_opt.feasibility_tol = rpo_opt.ipm_tol;
        independent_opt.stationarity_tol = rpo_opt.stationarity_tol;
        independent_opt.warm_start = result.converged
            ? &result.optimized_opf : nullptr;
        independent_opt.enforce_branch_limits = rpo_opt.enforce_branch_limits;
        independent_opt.enforce_converter_capacity =
            rpo_opt.enforce_converter_capacity;
        independent_opt.enforce_converter_current_limits =
            rpo_opt.enforce_converter_current_limits;
        independent_opt.enforce_converter_modulation_limits =
            rpo_opt.enforce_converter_modulation_limits;
        auto independent_opf = hacdcpf::solve_ac_opf(optimized_sys, independent_opt);
        hacdcpf::verify_opf_result(optimized_sys, independent_opf);

        const auto max_abs_difference = [](const std::vector<double>& lhs,
                                           const std::vector<double>& rhs) {
          const size_t n = std::min(lhs.size(), rhs.size());
          if (n == 0 || lhs.size() != rhs.size())
            return std::numeric_limits<double>::infinity();
          double value = 0.0;
          for (size_t i = 0; i < n; ++i)
            value = std::max(value, std::abs(lhs[i] - rhs[i]));
          return value;
        };
        const double opf_vm_difference = max_abs_difference(
            result.optimized_opf.vm, independent_opf.vm);
        const double opf_pg_difference = max_abs_difference(
            result.optimized_opf.pg_mw, independent_opf.pg_mw);
        const double opf_qg_difference = max_abs_difference(
            result.optimized_opf.qg_mvar, independent_opf.qg_mvar);
        const double opf_objective_difference = std::abs(
            result.optimized_opf.objective - independent_opf.objective);
        const double opf_objective_scale = std::max(
            {1.0, std::abs(result.optimized_opf.objective),
             std::abs(independent_opf.objective)});
        const double opf_objective_relative_difference =
            opf_objective_difference / opf_objective_scale;

        hacdcpf::HybridPowerSystem replay_sys = optimized_sys;
        const auto& optimized_opf = result.optimized_opf;
        for (size_t i = 0; i < optimized_opf.pg_mw.size() &&
                           i < replay_sys.ac.generators.size(); ++i) {
          replay_sys.ac.generators[i].pg_mw = optimized_opf.pg_mw[i];
          if (i < optimized_opf.qg_mvar.size())
            replay_sys.ac.generators[i].qg_mvar = optimized_opf.qg_mvar[i];
        }
        for (size_t k = 0; k < optimized_opf.pren_mw.size() &&
                           k < optimized_opf.ren_map.size(); ++k) {
          const int pos = optimized_opf.ren_map[k].original_index;
          if (optimized_opf.ren_map[k].source_type == 0 && pos >= 0 &&
              pos < static_cast<int>(replay_sys.ac.renewable_gens.size())) {
            replay_sys.ac.renewable_gens[static_cast<size_t>(pos)].p_mw =
                optimized_opf.pren_mw[k];
            if (k < optimized_opf.qren_mvar.size())
              replay_sys.ac.renewable_gens[static_cast<size_t>(pos)].q_mvar =
                  optimized_opf.qren_mvar[k];
          } else if (optimized_opf.ren_map[k].source_type == 1 && pos >= 0 &&
                     pos < static_cast<int>(replay_sys.ac.pv_systems.size())) {
            replay_sys.ac.pv_systems[static_cast<size_t>(pos)].p_mw =
                optimized_opf.pren_mw[k];
            if (k < optimized_opf.qren_mvar.size())
              replay_sys.ac.pv_systems[static_cast<size_t>(pos)].q_mvar =
                  optimized_opf.qren_mvar[k];
          }
        }
        for (size_t k = 0; k < optimized_opf.pstor_mw.size() &&
                           k < optimized_opf.stor_map.size(); ++k) {
          const int pos = optimized_opf.stor_map[k].original_index;
          if (optimized_opf.stor_map[k].source_type == 0 && pos >= 0 &&
              pos < static_cast<int>(replay_sys.ac.storage.size())) {
            replay_sys.ac.storage[static_cast<size_t>(pos)].p_mw =
                optimized_opf.pstor_mw[k];
            if (k < optimized_opf.qstor_mvar.size())
              replay_sys.ac.storage[static_cast<size_t>(pos)].q_mvar =
                  optimized_opf.qstor_mvar[k];
          }
        }
        for (size_t k = 0; k < optimized_opf.pflex_mw.size() &&
                           k < optimized_opf.flex_map.size(); ++k) {
          const int pos = optimized_opf.flex_map[k].original_index;
          if (pos >= 0 && pos < static_cast<int>(replay_sys.ac.flexible_loads.size()))
            replay_sys.ac.flexible_loads[static_cast<size_t>(pos)].p_mw =
                optimized_opf.pflex_mw[k];
        }
        constexpr double kRadToDeg = 57.2957795130823208768;
        for (size_t i = 0; i < optimized_opf.vm.size() &&
                           i < replay_sys.ac.buses.size(); ++i) {
          replay_sys.ac.buses[i].vm_pu = optimized_opf.vm[i];
          if (i < optimized_opf.va.size())
            replay_sys.ac.buses[i].va_deg = optimized_opf.va[i] * kRadToDeg;
        }
        hacdcpf::PowerFlowOptions replay_pf_opt;
        replay_pf_opt.max_iter = 100;
        replay_pf_opt.tol = 1e-8;
        const auto baseline_pf = hacdcpf::solve_power_flow(sys, replay_pf_opt);
        const auto replay_pf = hacdcpf::solve_power_flow(replay_sys, replay_pf_opt);
        const double pf_vm_difference = max_abs_difference(
            optimized_opf.vm, replay_pf.vm);
        const auto pf_loss = [](const hacdcpf::PowerFlowResult& pf) {
          double loss = 0.0;
          for (const auto& branch : pf.branch_flows)
            loss += branch.pf_mw + branch.pt_mw;
          for (const auto& converter : pf.vsc_transfers)
            loss += converter.loss_mw;
          for (const auto& converter : pf.dcdc_transfers)
            loss += converter.loss_mw;
          return loss;
        };

        const bool hybrid_replay_partial =
            !sys.dc.buses.empty() || !sys.vsc_converters.empty() ||
            !sys.dc.dcdc_converters.empty() || !sys.energy_routers.empty();
        // A non-convex OPF may have multiple equivalent control dispatches.
        // Cross-validation therefore compares feasibility, objective and the
        // electrical voltage state; Pg/Qg differences remain visible as
        // diagnostics but are not treated as a false failure by themselves.
        const double opf_vm_agreement_tol =
            std::max(5e-4, 10.0 * rpo_opt.ipm_tol);
        const double opf_objective_agreement_tol =
            std::max(1e-3, 10.0 * rpo_opt.stationarity_tol);
        const bool opf_agrees = result.converged && independent_opf.converged &&
            independent_opf.audit.feasible() &&
            std::isfinite(opf_vm_difference) &&
            opf_vm_difference <= opf_vm_agreement_tol &&
            std::isfinite(opf_objective_relative_difference) &&
            opf_objective_relative_difference <= opf_objective_agreement_tol;
        const bool pf_agrees = result.converged && replay_pf.converged &&
            std::isfinite(pf_vm_difference) && pf_vm_difference <= 1e-3 &&
            !hybrid_replay_partial;
        const bool pf_check_applicable = !hybrid_replay_partial;
        const bool available_checks_pass = opf_agrees && replay_pf.converged &&
            (!pf_check_applicable || pf_agrees);

        // Build JSON response
        json out;
        out["converged"]       = result.converged;
        out["objective"]       = result.objective;
        out["objective_type"]  = obj_type;
        out["gap"]             = result.gap;
        out["nodes_explored"]  = result.nodes_explored;
        out["nlp_solves"]      = result.nlp_solves;
        out["runtime_sec"]     = result.runtime_sec;
        out["vm_before"]       = result.vm_before;
        out["vm_after"]        = result.vm_after;
        out["va_before"]       = result.va_before;
        out["va_after"]        = result.va_after;
        out["pg_before"]       = result.pg_mw_before;
        out["pg_after"]        = result.pg_mw_after;
        out["qg_before"]       = result.qg_mvar_before;
        out["qg_after"]        = result.qg_mvar_after;
        out["total_loss_before"] = result.total_loss_before_mw;
        out["total_loss_after"]  = result.total_loss_after_mw;
        out["max_vdev_before"]   = result.max_vdev_before;
        out["max_vdev_after"]    = result.max_vdev_after;
        out["status"]            = result.status;
        out["algorithm"]         = result.algorithm;
        out["globally_certified"] = result.globally_certified;
	        out["optimality_gap_available"] = result.optimality_gap_available;
	        out["terminated_by_time_limit"] = result.terminated_by_time_limit;
	        out["terminated_by_evaluation_limit"] =
	            result.terminated_by_evaluation_limit;
	        out["model_limitations"] = result.model_limitations;
        out["v_min"] = 0.95;
        out["v_max"] = 1.05;
        out["model_statement"] =
            "离散坐标搜索(两绕组OLTC/可投切并联补偿)+以所选电压/网损"
            "目标直接求解的连续AC/DC OPF；"
            "返回可行局部最优点，不提供全局MINLP最优性证明。";
        out["inner_objective_effective"] = independent_uses_unit_cost
            ? "unit_cost_economic"
            : "match_rpo";
        out["control_inventory"] = rpo_control_inventory_json(sys, rpo_opt);

        out["cross_validation"] = json{
            {"rpo_converged", result.converged},
            {"independent_opf_converged", independent_opf.converged},
            {"opf_agrees", opf_agrees},
            {"opf_max_vm_difference_pu",
             std::isfinite(opf_vm_difference) ? json(opf_vm_difference) : json(nullptr)},
            {"opf_max_pg_difference_mw",
             std::isfinite(opf_pg_difference) ? json(opf_pg_difference) : json(nullptr)},
            {"opf_max_qg_difference_mvar",
             std::isfinite(opf_qg_difference) ? json(opf_qg_difference) : json(nullptr)},
            {"opf_objective_difference",
             std::isfinite(opf_objective_difference)
                 ? json(opf_objective_difference) : json(nullptr)},
            {"opf_objective_relative_difference",
             std::isfinite(opf_objective_relative_difference)
                 ? json(opf_objective_relative_difference) : json(nullptr)},
            {"opf_vm_agreement_tolerance_pu", opf_vm_agreement_tol},
            {"opf_objective_agreement_tolerance",
             opf_objective_agreement_tol},
            {"opf_status", independent_opf.status},
            {"opf_audit_feasible", independent_opf.audit.feasible()},
            {"opf_audit_violations", independent_opf.audit.violations},
            {"baseline_pf_converged", baseline_pf.converged},
            {"optimized_pf_converged", replay_pf.converged},
            {"pf_agrees", pf_agrees},
            {"pf_check_applicable", pf_check_applicable},
            {"pf_max_vm_difference_pu",
             std::isfinite(pf_vm_difference) ? json(pf_vm_difference) : json(nullptr)},
            {"baseline_pf_loss_mw", baseline_pf.converged ? json(pf_loss(baseline_pf)) : json(nullptr)},
            {"optimized_pf_loss_mw", replay_pf.converged ? json(pf_loss(replay_pf)) : json(nullptr)},
            {"pf_residual", replay_pf.residual},
            {"pf_termination_reason", replay_pf.diagnostics.termination_reason},
            {"hybrid_dispatch_replay_partial", hybrid_replay_partial},
            {"overall_pass", available_checks_pass},
            {"validation_summary",
             available_checks_pass
                 ? (hybrid_replay_partial
                        ? "可用数值检查通过；富混合AC/DC的PF调度回放为部分覆盖"
                        : "RPO、独立OPF与PF全过程一致")
                 : "至少一项可用数值检查未通过"}};

        const auto active_count = [](const auto& items) {
          return static_cast<int>(std::count_if(
              items.begin(), items.end(), [](const auto& item) {
                return item.in_service;
              }));
        };
        json coverage = json::array();
        const auto add_coverage = [&](const std::string& type,
                                      const std::string& label, int count,
                                      const std::string& treatment,
                                      bool cross_validated,
                                      const std::string& note) {
          if (count <= 0) return;
          coverage.push_back(json{{"component_type", type}, {"label", label},
                                  {"count", count}, {"treatment", treatment},
                                  {"cross_validated", cross_validated},
                                  {"note", note}});
        };
        add_coverage("ac_bus", "交流母线", active_count(sys.ac.buses),
                     "连续状态", true, "Vm/Va进入OPF并由PF回放");
        add_coverage("ac_branch", "交流线路", active_count(sys.ac.branches),
                     rpo_opt.enforce_branch_limits ? "约束建模" : "建模但未限额",
                     true, "AC潮流方程与热稳约束");
        add_coverage("generator", "同步机组", active_count(sys.ac.generators),
                     "连续协同优化", true, "Pg/Qg及能力上下限");
        add_coverage("external_grid", "外部电网",
                     active_count(sys.ac.external_grids), "连续边界电源", true,
                     "参与OPF边界平衡；PF重新闭合Slack功率");
        add_coverage("transformer_2w", "两绕组变压器",
                     active_count(sys.ac.transformers_2w), "离散/固定混合", true,
                     "有有效档位范围的OLTC直接离散优化，其余固定建模");
        add_coverage("transformer_3w", "三绕组变压器",
                     active_count(sys.ac.transformers_3w), "固定投影建模", true,
                     "潮流参与；三绕组分接头尚非RPO离散变量");
        add_coverage("shunt", "并联补偿", active_count(sys.ac.shunts),
                     "离散/固定混合", true,
                     "可投切步数直接优化；固定电纳作为网络参数");
        add_coverage("load", "交流负荷", active_count(sys.ac.loads),
                     "固定需求", true, "计入节点功率平衡和损耗核算");
        add_coverage("asymmetric_load", "不对称负荷",
                     active_count(sys.ac.asymmetric_loads), "平衡投影固定需求",
                     true, "三相总量进入平衡聚合模型");
        add_coverage("static_generator", "静态电源",
                     active_count(sys.ac.static_generators), "固定注入", true,
                     "不作为RPO决策变量但进入功率平衡");
        add_coverage("flexible_load", "柔性负荷",
                     active_count(sys.ac.flexible_loads), "连续协同优化", true,
                     "沿用OPF柔性负荷上下限");
        add_coverage("renewable_generator", "新能源机组",
                     active_count(sys.ac.renewable_gens), "连续/固定混合", true,
                     "可控P/Q进入OPF；不可控资源作为固定注入");
        add_coverage("pv_system", "光伏系统", active_count(sys.ac.pv_systems),
                     "连续/固定混合", true, "可控逆变器P/Q进入OPF");
        add_coverage("storage", "交流储能", active_count(sys.ac.storage),
                     "Q连续、P按计划", true,
                     "单时段无SOC转移，P固定在计划附近，Q参与优化");
        add_coverage("switch", "交流开关", active_count(sys.ac.switches),
                     "固定拓扑", true, "保持当前开合状态");
        add_coverage("circuit_breaker", "交流断路器",
                     active_count(sys.ac.circuit_breakers), "固定拓扑", true,
                     "保持当前开合状态");
        add_coverage("charging_station", "充电站",
                     active_count(sys.ac.charging_stations), "固定需求", true,
                     "进入聚合功率平衡，不参与无功决策");
        add_coverage("motor", "异步电动机", active_count(sys.ac.motors),
                     "固定需求模型", true, "进入潮流回放，不参与RPO控制");
        add_coverage("vsc_converter", "VSC换流器",
                     active_count(sys.vsc_converters), "连续协同优化",
                     !hybrid_replay_partial,
                     "容量/电流/调制约束可启用；当前RPO-PF富模型回放为部分映射");
        add_coverage("dc_bus", "直流母线", active_count(sys.dc.buses),
                     "连续状态", !hybrid_replay_partial,
                     "Vdc进入混合OPF；当前RPO-PF富模型回放为部分映射");
        add_coverage("dc_branch", "直流线路", active_count(sys.dc.branches),
                     "约束建模", !hybrid_replay_partial, "参与混合OPF/PF");
        add_coverage("dc_load", "直流负荷", active_count(sys.dc.loads),
                     "固定需求", !hybrid_replay_partial, "进入直流节点平衡");
        add_coverage("dc_storage", "直流储能",
                     active_count(sys.dc.storage) + active_count(sys.dc.dc_storage),
                     "P按计划", !hybrid_replay_partial,
                     "单时段无SOC转移；直流侧无无功变量");
        add_coverage("dc_static_generator", "直流静态电源",
                     active_count(sys.dc.static_generators) +
                         active_count(sys.dc.dc_static_generators),
                     "固定注入", !hybrid_replay_partial,
                     "进入直流节点功率平衡");
        add_coverage("dc_pv_array", "直流光伏", active_count(sys.dc.pv_arrays),
                     "固定注入", !hybrid_replay_partial,
                     "直流侧无无功变量");
        add_coverage("dcdc_converter", "DC/DC换流器",
                     active_count(sys.dc.dcdc_converters), "连续有功协同",
                     !hybrid_replay_partial, "无功不适用；占空比约束由OPF处理");
        add_coverage("energy_router", "能量路由器",
                     active_count(sys.energy_routers), "端口投影协同",
                     !hybrid_replay_partial, "当前RPO-PF富模型回放为部分映射");
        add_coverage("mobile_storage", "移动储能",
                     active_count(sys.mobile_storage), "固定/投影注入", true,
                     "尚非RPO独立调压决策变量");
        add_coverage("vpp", "虚拟电厂", active_count(sys.vpps),
                     "固定/投影注入", true, "尚非RPO独立无功决策变量");
        add_coverage("microgrid", "微网", active_count(sys.microgrids),
                     "固定/投影交换", true, "尚非RPO独立无功决策变量");
        add_coverage("regulator_control", "调压控制器",
                     static_cast<int>(sys.ac.regulator_controls.size()),
                     "未作为独立决策", false,
                     "控制器逻辑尚未进入RPO离散变量集");
        if (sys.three_phase_ac.has_value()) {
          add_coverage("three_phase_ac", "三相不平衡子系统", 1,
                       "未进入单体RPO", false,
                       "当前RPO采用平衡聚合AC/DC模型");
        }
        const bool coverage_complete = std::none_of(
            coverage.begin(), coverage.end(), [](const auto& row) {
              return row.value("treatment", "").find("未") == 0 ||
                     !row.value("cross_validated", false);
            });
        out["component_coverage"] = std::move(coverage);
        out["component_coverage_complete"] = coverage_complete;

        json tap_names = json::array(), tap_indices = json::array();
        json tap_ratio_before = json::array(), tap_ratio_after = json::array();
        json electrical_tap_before = json::array(), electrical_tap_after = json::array();
        json tap_pos_before = json::array(), tap_pos_after = json::array();
        for (const auto& t : result.taps) {
          tap_names.push_back(t.name);
          tap_indices.push_back(t.trafo_index);
          tap_ratio_before.push_back(t.ratio_before);
          tap_ratio_after.push_back(t.ratio_after);
          electrical_tap_before.push_back(t.electrical_tap_before);
          electrical_tap_after.push_back(t.electrical_tap_after);
          tap_pos_before.push_back(t.tap_before);
          tap_pos_after.push_back(t.tap_after);
        }
        out["tap_names"]        = tap_names;
        out["tap_indices"]      = tap_indices;
        out["tap_before"]       = tap_ratio_before;
        out["tap_after"]        = tap_ratio_after;
        out["electrical_tap_before"] = electrical_tap_before;
        out["electrical_tap_after"] = electrical_tap_after;
        out["tap_pos_before"]   = tap_pos_before;
        out["tap_pos_after"]    = tap_pos_after;

        json sh_names = json::array(), sh_indices = json::array();
        json sh_before = json::array(), sh_after = json::array();
        json sh_mvar_before = json::array(), sh_mvar_after = json::array();
        for (const auto& s : result.shunts) {
          sh_names.push_back(s.name);
          sh_indices.push_back(s.shunt_index);
          sh_before.push_back(s.step_before);
          sh_after.push_back(s.step_after);
          sh_mvar_before.push_back(s.bs_mvar_before);
          sh_mvar_after.push_back(s.bs_mvar_after);
        }
        out["shunt_names"]       = sh_names;
        out["shunt_indices"]     = sh_indices;
        out["shunt_before"]      = sh_before;
        out["shunt_after"]       = sh_after;
        out["shunt_mvar_before"] = sh_mvar_before;
        out["shunt_mvar_after"]  = sh_mvar_after;
        out["n_taps"]   = (int)result.taps.size();
        out["n_shunts"] = (int)result.shunts.size();

        json gn = json::array();
        for (size_t i = 0; i < sys.ac.generators.size(); ++i)
          gn.push_back(sys.ac.generators[i].name.empty()
                         ? "Gen" + std::to_string(i)
                         : sys.ac.generators[i].name);
        out["gen_names"] = gn;

        res.set_content(out.dump(), "application/json");
        g_session.busy.store(false);
      } catch (const std::exception& e) {
        g_session.busy.store(false);
        res.status = 400;
        res.set_content(json{{"error", e.what()}}.dump(), "application/json");
      }
    });

    // ---- Network Reconfiguration (TS-TR MILP) ----
    svr.Post("/api/session/run_reconfig",
             [](const httplib::Request& req, httplib::Response& res) {
      try {
        hacdcpf::HybridPowerSystem sys_tr;
        hacdcpf::TimeSeriesData ts_data;
        {
          std::lock_guard<std::mutex> lk(g_session.mu);
          if (!g_session.current_system) throw std::runtime_error("No system loaded");
          const auto j2 = json::parse(req.body.empty() ? "{}" : req.body);
          const int ns = j2.value("num_steps", 4);
          if (g_session.ts_data.num_steps != ns || g_session.ts_data.profiles.empty())
            g_session.ts_data = make_default_ts_data(ns);
          sys_tr = *g_session.current_system;
          ts_data = g_session.ts_data;
        }
        if (g_session.busy.exchange(true)) {
          res.status = 409;
          res.set_content(json{{"error","Another analysis is already running"}}.dump(), "application/json");
          return;
        }
        g_session.cancel.store(false);
        const auto j = json::parse(req.body.empty() ? "{}" : req.body);
        int num_steps = j.value("num_steps", 4);
        assign_available_default_profiles(sys_tr, ts_data);

        // ========== Step 1: Baseline loss (original topology) ==========
        double base_loss_mw = 0.0;
        bool base_pf_converged = false;
        int base_pf_iterations = 0;
        auto ac_topology = [](const hacdcpf::ACSystem& ac) {
          std::unordered_map<int, int> pos;
          for (size_t i = 0; i < ac.buses.size(); ++i) pos[ac.buses[i].index] = static_cast<int>(i);
          std::vector<std::vector<int>> adj(ac.buses.size());
          int edges = 0;
          for (const auto& br : ac.branches) {
            if (!br.in_service || !pos.count(br.from_bus) || !pos.count(br.to_bus)) continue;
            const int u = pos[br.from_bus], v = pos[br.to_bus];
            adj[u].push_back(v); adj[v].push_back(u); ++edges;
          }
          int islands = 0;
          std::vector<char> seen(ac.buses.size(), false);
          for (size_t s = 0; s < ac.buses.size(); ++s) {
            if (seen[s]) continue;
            ++islands;
            std::vector<int> stack{static_cast<int>(s)}; seen[s] = true;
            while (!stack.empty()) {
              const int u = stack.back(); stack.pop_back();
              for (int v : adj[u]) if (!seen[v]) { seen[v] = true; stack.push_back(v); }
            }
          }
          const bool connected = ac.buses.empty() || islands == 1;
          const bool radial = ac.buses.empty() || edges == static_cast<int>(ac.buses.size()) - islands;
          return std::tuple<bool, bool, int, int>{radial, connected, islands, edges};
        };
        auto dc_topology = [](const hacdcpf::DCSystem& dc) {
          std::unordered_map<int, int> pos;
          for (size_t i = 0; i < dc.buses.size(); ++i) pos[dc.buses[i].index] = static_cast<int>(i);
          std::vector<std::vector<int>> adj(dc.buses.size());
          int edges = 0;
          for (const auto& br : dc.branches) {
            if (!br.in_service || !pos.count(br.from_bus) || !pos.count(br.to_bus)) continue;
            const int u = pos[br.from_bus], v = pos[br.to_bus];
            adj[u].push_back(v); adj[v].push_back(u); ++edges;
          }
          int islands = 0;
          std::vector<char> seen(dc.buses.size(), false);
          for (size_t s = 0; s < dc.buses.size(); ++s) {
            if (seen[s]) continue;
            ++islands;
            std::vector<int> stack{static_cast<int>(s)}; seen[s] = true;
            while (!stack.empty()) {
              const int u = stack.back(); stack.pop_back();
              for (int v : adj[u]) if (!seen[v]) { seen[v] = true; stack.push_back(v); }
            }
          }
          const bool connected = dc.buses.empty() || islands == 1;
          const bool radial = dc.buses.empty() || edges == static_cast<int>(dc.buses.size()) - islands;
          return std::tuple<bool, bool, int, int>{radial, connected, islands, edges};
        };
        auto hybrid_topology = [](const hacdcpf::HybridPowerSystem& sys) {
          const auto graph = hacdcpf::graph::build_power_system_graph(sys);
          return std::pair<bool, int>{hacdcpf::graph::is_connected(graph),
                                      hacdcpf::graph::count_islands(graph)};
        };
        const auto [base_ac_radial, base_ac_connected, base_ac_islands, base_ac_closed] = ac_topology(sys_tr.ac);
        const auto [base_dc_radial, base_dc_connected, base_dc_islands, base_dc_closed] = dc_topology(sys_tr.dc);
        const auto [base_is_connected, base_islands] = hybrid_topology(sys_tr);
        const bool base_is_radial = base_ac_radial && base_dc_radial;
        {
          hacdcpf::PowerFlowOptions pf_opt;
          pf_opt.max_iter = 200; pf_opt.tol = 1e-6;
          auto pf_base = hacdcpf::solve_power_flow(sys_tr, pf_opt);
          base_pf_converged = pf_base.converged;
          base_pf_iterations = pf_base.iterations;
          if (pf_base.converged) {
            // Sum branch losses: loss = pf_from + pt_to for each branch
            for (const auto& bf : pf_base.branch_flows) {
              double loss = bf.pf_mw + bf.pt_mw;  // sending + receiving end
              if (loss > 0.0) base_loss_mw += loss;
            }
          }
        }

        // Keep the rich model authoritative. The core reconfiguration solver
        // performs a dedicated projection that preserves switch branches, so
        // device capabilities and protection bindings remain available for
        // hard candidate filtering and ordered action validation.
        const hacdcpf::HybridPowerSystem rich_sys_tr = sys_tr;
        hacdcpf::ProjectionOptions reconfig_projection;
        reconfig_projection.strip_dead_islands = false;
        reconfig_projection.preserve_switch_branches = true;
        auto reconfig_model =
            hacdcpf::projection::RichToCanonicalOperator::apply(
                rich_sys_tr, reconfig_projection)
                .canonical;

        // ========== Step 2: Run topology reconfiguration (single snapshot) ==========
        // The SIM backend exposes a single-snapshot MILP reconfiguration
        // (run_topology_reconfiguration) rather than the time-series schedule
        // used in HybridACDCPowerSystemsPlanning. Run it once and present the
        // result below as a one-step schedule (num_steps == 1).
        hacdcpf::analysis::TopoReconfOptions tr_opts;
        const auto& opts = j.contains("options") ? j["options"] : j;
        tr_opts.v_min_pu  = opts.value("v_min_pu", opts.value("v_min", 0.95));
        tr_opts.v_max_pu  = opts.value("v_max_pu", opts.value("v_max", 1.05));
        tr_opts.mip_gap   = opts.value("mip_gap", 0.01);
        tr_opts.max_time_s = opts.value("max_time_s", 60);
        tr_opts.enable_pf = opts.value("enable_pf", true);
        tr_opts.enable_voltage = opts.value("enable_voltage", true);
        tr_opts.enable_thermal = opts.value("enable_thermal", true);
        tr_opts.split_domain_trees = opts.value("split_domain_trees", false);
        tr_opts.allow_dc_mesh = opts.value("allow_dc_mesh", false);
        tr_opts.loss_aware = opts.value("loss_aware", true);  // I²R-aware so ties are used
        // Faulted lines (ACBranch.index) are forced open so the MILP must close
        // a tie to restore downstream load — gives a visible reconfiguration.
        if (opts.contains("line_failures") && opts["line_failures"].is_array())
          for (const auto& f : opts["line_failures"]) tr_opts.line_failures.push_back(f.get<int>());
        tr_opts.lambda_switch = opts.value("lambda_switch", 1.0);
        tr_opts.lambda_loss   = opts.value("lambda_loss", 10.0);
        tr_opts.lambda_shed   = opts.value("lambda_shed", 1e4);
        tr_opts.lambda_island = opts.value("lambda_island", 1e5);
        // Arbitrary device faults: AC lines via line_failures, plus structured
        // AC/DC/VSC faults so any device can be forced out of service.
        auto add_faults = [&](const char* key, hacdcpf::graph::EdgeCategory cat) {
          if (opts.contains(key) && opts[key].is_array())
            for (const auto& f : opts[key]) tr_opts.faulted_branches.push_back({cat, f.get<int>()});
        };
        add_faults("fault_ac", hacdcpf::graph::EdgeCategory::AC_Line);
        add_faults("fault_dc", hacdcpf::graph::EdgeCategory::DC_Line);
        add_faults("fault_vsc", hacdcpf::graph::EdgeCategory::VSC_Coupling);
        tr_opts.max_switch_ops = opts.value("max_switch_ops", 0);
        tr_opts.solver = opts.value("solver", std::string("auto"));
        tr_opts.skip_heuristic = opts.value("skip_heuristic", false);
        tr_opts.verbose   = false;
        // Candidate switching decisions are derived inside the core from rich
        // SwitchType/role/capabilities/locks. Do not expose every equivalent
        // AC branch as a switching variable: that previously authorized fuse,
        // transformer and physical-line operations.
        // Auto-enable split-domain radiality when the case is hybrid (has DC
        // buses + converters) unless the caller overrode it.
        if (!opts.contains("split_domain_trees") && !rich_sys_tr.dc.buses.empty() && !rich_sys_tr.vsc_converters.empty())
          tr_opts.split_domain_trees = true;
        auto recon = hacdcpf::analysis::run_topology_reconfiguration(
            rich_sys_tr, tr_opts);
        // Response topology rows use the same preserved-switch canonical index
        // space as the solver result.
        sys_tr = std::move(reconfig_model);

        // Per-branch closed flag (1 = in service) derived from the open-branch set,
        // then exposed as a single-step [branch][1] matrix for the response code below.
        std::vector<std::vector<int>> ac_branch_closed_ts(
            sys_tr.ac.branches.size(), std::vector<int>(1, 1));
        {
          std::set<int> open_ac;
          for (const auto& br : recon.open_branches)
            if (br.category == hacdcpf::graph::EdgeCategory::AC_Line) open_ac.insert(br.index);
          for (size_t b = 0; b < sys_tr.ac.branches.size(); ++b)
            ac_branch_closed_ts[b][0] = open_ac.count(sys_tr.ac.branches[b].index) ? 0 : 1;
        }
        // Single-step schedule view consumed by the response builder below.
        struct ReconSchedView {
          bool feasible;
          double total_objective;
          double total_shed_mw;
          std::string solver_name;
          std::vector<std::vector<int>>& ac_branch_closed;
          std::vector<std::vector<int>> ac_switch_on;
          std::vector<std::vector<int>> ac_switch_off;
          std::vector<std::vector<double>> storage_ac_soc_mwh;
          std::vector<std::vector<double>> ren_ac_curtail_mw;
        } sched{recon.feasible, recon.milp_objective, 0.0,
                recon.solver_backend.empty() ? recon.solver_status : recon.solver_backend,
                ac_branch_closed_ts, {}, {}, {}, {}};
        // Single-step switch counts.
        sched.ac_switch_on.assign(1, std::vector<int>(1, recon.n_switch_on));
        sched.ac_switch_off.assign(1, std::vector<int>(1, recon.n_switch_off));
        num_steps = 1;

        // ========== Step 3: Reconfigured loss + radiality check ==========
        double reconfig_loss_mw = 0.0;
        bool reconfig_pf_converged = false;
        int reconfig_pf_iterations = 0;
        bool opf_converged = false; double opf_objective = 0.0;
        double reconfig_pf_residual = 0.0;
        bool reconfig_is_radial = false;
        bool reconfig_is_connected = false;
        int reconfig_islands = 0;
        bool reconfig_ac_radial = false, reconfig_ac_connected = false;
        bool reconfig_dc_radial = false, reconfig_dc_connected = false;
        int reconfig_ac_islands = 0, reconfig_dc_islands = 0;
        int reconfig_dc_closed_count = 0, reconfig_vsc_closed_count = 0;
        int reconfig_closed_count = 0;
        int reconfig_open_count = 0;
        bool actions_applied_to_rich_model = false;
        std::string validation_message;
        if (sched.feasible) {
          // Apply the canonical final state to a display copy only. Electrical
          // validation below is performed from rich-device actions.
          auto sys_reconfig = sys_tr;
          std::set<int> closed_ac, closed_dc, closed_vsc;
          for (const auto& ref : recon.closed_branches) {
            if (ref.category == hacdcpf::graph::EdgeCategory::AC_Line) closed_ac.insert(ref.index);
            else if (ref.category == hacdcpf::graph::EdgeCategory::DC_Line) closed_dc.insert(ref.index);
            else if (ref.category == hacdcpf::graph::EdgeCategory::VSC_Coupling) closed_vsc.insert(ref.index);
          }
          for (auto& br : sys_reconfig.ac.branches) {
            br.in_service = closed_ac.count(br.index) != 0;
            if (br.in_service) ++reconfig_closed_count; else ++reconfig_open_count;
          }
          for (auto& br : sys_reconfig.dc.branches) {
            br.in_service = closed_dc.count(br.index) != 0;
            if (br.in_service) ++reconfig_dc_closed_count;
          }
          for (auto& vsc : sys_reconfig.vsc_converters) {
            vsc.in_service = closed_vsc.count(vsc.index) != 0;
            if (vsc.in_service) ++reconfig_vsc_closed_count;
          }
          // Apply faults and final device actions back to the rich model.
          auto rich_reconfig = rich_sys_tr;
          bool action_mapping_ok = true;
          const auto set_ac_branch = [&](int index, bool in_service) {
            auto it = std::find_if(rich_reconfig.ac.branches.begin(),
                                   rich_reconfig.ac.branches.end(),
                                   [&](const auto& branch) {
                                     return branch.index == index;
                                   });
            if (it == rich_reconfig.ac.branches.end()) return false;
            it->in_service = in_service;
            return true;
          };
          for (int index : tr_opts.line_failures)
            action_mapping_ok = set_ac_branch(index, false) && action_mapping_ok;
          for (const auto& fault : tr_opts.faulted_branches) {
            bool found = false;
            if (fault.category == hacdcpf::graph::EdgeCategory::AC_Line) {
              found = set_ac_branch(fault.index, false);
            } else if (fault.category == hacdcpf::graph::EdgeCategory::DC_Line) {
              auto it = std::find_if(rich_reconfig.dc.branches.begin(),
                                     rich_reconfig.dc.branches.end(),
                                     [&](const auto& branch) {
                                       return branch.index == fault.index;
                                     });
              found = it != rich_reconfig.dc.branches.end();
              if (found) it->in_service = false;
            } else if (fault.category ==
                       hacdcpf::graph::EdgeCategory::VSC_Coupling) {
              auto it = std::find_if(rich_reconfig.vsc_converters.begin(),
                                     rich_reconfig.vsc_converters.end(),
                                     [&](const auto& converter) {
                                       return converter.index == fault.index;
                                     });
              found = it != rich_reconfig.vsc_converters.end();
              if (found) it->in_service = false;
            }
            action_mapping_ok = found && action_mapping_ok;
          }
          for (const auto& operation : recon.switch_operations) {
            bool found = false;
            if (operation.kind ==
                hacdcpf::analysis::TopoReconfResult::DeviceKind::Switch) {
              auto it = std::find_if(rich_reconfig.ac.switches.begin(),
                                     rich_reconfig.ac.switches.end(),
                                     [&](const auto& sw) {
                                       return sw.index == operation.index;
                                     });
              found = it != rich_reconfig.ac.switches.end();
              if (found) it->closed = operation.close;
            } else if (operation.kind ==
                       hacdcpf::analysis::TopoReconfResult::DeviceKind::CircuitBreaker) {
              auto it = std::find_if(
                  rich_reconfig.ac.circuit_breakers.begin(),
                  rich_reconfig.ac.circuit_breakers.end(),
                  [&](const auto& breaker) {
                    return breaker.index == operation.index;
                  });
              found = it != rich_reconfig.ac.circuit_breakers.end();
              if (found) it->closed = operation.close;
            } else if (operation.category ==
                       hacdcpf::graph::EdgeCategory::AC_Line) {
              found = set_ac_branch(operation.index, operation.close);
            } else if (operation.category ==
                       hacdcpf::graph::EdgeCategory::DC_Line) {
              auto it = std::find_if(rich_reconfig.dc.branches.begin(),
                                     rich_reconfig.dc.branches.end(),
                                     [&](const auto& branch) {
                                       return branch.index == operation.index;
                                     });
              found = it != rich_reconfig.dc.branches.end();
              if (found) it->in_service = operation.close;
            } else if (operation.category ==
                       hacdcpf::graph::EdgeCategory::VSC_Coupling) {
              auto it = std::find_if(rich_reconfig.vsc_converters.begin(),
                                     rich_reconfig.vsc_converters.end(),
                                     [&](const auto& converter) {
                                       return converter.index == operation.index;
                                     });
              found = it != rich_reconfig.vsc_converters.end();
              if (found) it->in_service = operation.close;
            }
            action_mapping_ok = found && action_mapping_ok;
          }

          // Re-project from rich device state before every electrical audit.
          try {
            hacdcpf::ProjectionOptions final_projection_options;
            final_projection_options.strip_dead_islands = false;
            const auto final_projection =
                hacdcpf::projection::RichToCanonicalOperator::apply(
                    rich_reconfig, final_projection_options);
            const auto& validated_system = final_projection.canonical;
            actions_applied_to_rich_model = action_mapping_ok;
            recon.validity.post_action_reprojection_validated =
                action_mapping_ok;

            int reconfig_ac_closed_unused = 0;
            std::tie(reconfig_ac_radial, reconfig_ac_connected,
                     reconfig_ac_islands, reconfig_ac_closed_unused) =
                ac_topology(validated_system.ac);
            std::tie(reconfig_dc_radial, reconfig_dc_connected,
                     reconfig_dc_islands, reconfig_dc_closed_count) =
                dc_topology(validated_system.dc);
            std::tie(reconfig_is_connected, reconfig_islands) =
                hybrid_topology(validated_system);
            reconfig_is_radial = reconfig_ac_radial &&
                (tr_opts.allow_dc_mesh || reconfig_dc_radial);

            hacdcpf::PowerFlowOptions pf_opt;
            pf_opt.max_iter = 200;
            pf_opt.tol = 1e-6;
            auto pf_reconfig = hacdcpf::solve_power_flow(
                rich_reconfig, pf_opt);
            reconfig_pf_converged = pf_reconfig.converged;
            reconfig_pf_iterations = pf_reconfig.iterations;
            reconfig_pf_residual = pf_reconfig.residual;
            if (pf_reconfig.converged) {
              for (const auto& bf : pf_reconfig.branch_flows) {
                const double loss = bf.pf_mw + bf.pt_mw;
                if (loss > 0.0) reconfig_loss_mw += loss;
              }
            }
            try {
              hacdcpf::opf::ACOPFOptions oo;
              auto opf_r = hacdcpf::solve_ac_opf(rich_reconfig, oo);
              opf_converged = opf_r.converged;
              opf_objective = opf_r.objective;
            } catch (const std::exception& error) {
              validation_message = std::string("OPF validation failed: ") +
                                   error.what();
            }
          } catch (const std::exception& error) {
            validation_message = std::string("post-action projection failed: ") +
                                 error.what();
          }
          recon.validity.post_power_flow_validated = reconfig_pf_converged;
          recon.validity.full_hybrid_opf_validated = opf_converged;
          recon.validity.executable =
              actions_applied_to_rich_model &&
              recon.switch_sequence_valid &&
              recon.validity.post_action_reprojection_validated &&
              reconfig_pf_converged && opf_converged;
          if (validation_message.empty() && !recon.validity.executable) {
            validation_message =
                "candidate failed rich-model action, sequence, PF, or OPF validation";
          }
        }

        // ========== Build JSON response ==========
        json out;
        out["feasible"] = sched.feasible;
        out["milp_feasible"] = sched.feasible;
        out["executable"] = recon.validity.executable;
        out["zero_load_loss_valid"] = recon.validity.executable &&
            recon.total_shed_mw <= 1e-6;
        out["validation_message"] = validation_message;
        out["switch_sequence_valid"] = recon.switch_sequence_valid;
        out["switch_sequence_message"] = recon.switch_sequence_message;
        out["device_action_count"] = recon.ordered_switch_actions.size();
        out["total_objective"] = sched.total_objective;
        out["obj_terms"] = json{{"loss", recon.obj_terms.loss}, {"switching", recon.obj_terms.switching},
                                {"shed", recon.obj_terms.shed}, {"island", recon.obj_terms.island}};
        out["opf_converged"] = opf_converged;
        out["opf_objective"] = opf_objective;
        out["total_shed_mw"] = recon.total_shed_mw;
        out["total_shed_mvar"] = recon.total_shed_mvar;
        out["milp_objective"] = sched.total_objective;
        out["estimated_loss_mw"] = sched.total_objective * sys_tr.base_mva;
        out["solver_name"] = sched.solver_name;
        out["solver_status"] = recon.solver_status;
        out["model_scope"] = recon.model_scope;
        out["validity"] = json{{"radial_topology_enforced", recon.validity.radial_topology_enforced},
                                {"device_capability_constraints_enforced", recon.validity.device_capability_constraints_enforced},
                                {"protection_interlocks_enforced", recon.validity.protection_interlocks_enforced},
                                {"switch_sequence_validated", recon.validity.switch_sequence_validated},
                                {"post_action_reprojection_validated", recon.validity.post_action_reprojection_validated},
                                {"ac_lindistflow_enforced", recon.validity.ac_lindistflow_enforced},
                                {"dc_network_modelled", recon.validity.dc_network_modelled},
                                {"dc_source_dispatch_modelled", recon.validity.dc_source_dispatch_modelled},
                                {"vsc_active_transfer_modelled", recon.validity.vsc_active_transfer_modelled},
                                {"vsc_reactive_power_approximated", recon.validity.vsc_reactive_power_approximated},
                                {"post_power_flow_validated", recon.validity.post_power_flow_validated},
                                {"full_hybrid_opf_validated", recon.validity.full_hybrid_opf_validated},
                                {"executable", recon.validity.executable}};
        out["num_steps"] = num_steps;

        // Loss comparison (before vs after reconfiguration)
        out["base_loss_mw"] = base_loss_mw;
        out["base_pf_converged"] = base_pf_converged;
        out["base_pf_iterations"] = base_pf_iterations;
        out["reconfig_loss_mw"] = reconfig_loss_mw;
        out["reconfig_pf_converged"] = reconfig_pf_converged;
        out["reconfig_pf_iterations"] = reconfig_pf_iterations;
        out["reconfig_pf_residual"] = reconfig_pf_residual;
        double loss_reduction_mw = base_loss_mw - reconfig_loss_mw;
        double loss_reduction_pct = (base_loss_mw > 1e-9) ? (loss_reduction_mw / base_loss_mw * 100.0) : 0.0;
        out["loss_reduction_mw"] = loss_reduction_mw;
        out["loss_reduction_pct"] = loss_reduction_pct;

        // Topology verification
        out["base_is_radial"] = base_is_radial;
        out["base_is_connected"] = base_is_connected;
        out["base_islands"] = base_islands;
        out["base_ac_is_radial"] = base_ac_radial;
        out["base_ac_is_connected"] = base_ac_connected;
        out["base_ac_islands"] = base_ac_islands;
        out["base_ac_closed_count"] = base_ac_closed;
        out["base_dc_is_radial"] = base_dc_radial;
        out["base_dc_is_connected"] = base_dc_connected;
        out["base_dc_islands"] = base_dc_islands;
        out["base_dc_closed_count"] = base_dc_closed;
        out["reconfig_is_radial"] = reconfig_is_radial;
        out["reconfig_is_connected"] = reconfig_is_connected;
        out["reconfig_islands"] = reconfig_islands;
        out["reconfig_ac_is_radial"] = reconfig_ac_radial;
        out["reconfig_ac_is_connected"] = reconfig_ac_connected;
        out["reconfig_ac_islands"] = reconfig_ac_islands;
        out["reconfig_dc_is_radial"] = reconfig_dc_radial;
        out["reconfig_dc_is_connected"] = reconfig_dc_connected;
        out["reconfig_dc_islands"] = reconfig_dc_islands;
        out["reconfig_closed_count"] = reconfig_closed_count;
        out["reconfig_open_count"] = reconfig_open_count;
        out["reconfig_dc_closed_count"] = reconfig_dc_closed_count;
        out["reconfig_vsc_closed_count"] = reconfig_vsc_closed_count;
        out["num_buses"] = (int)(sys_tr.ac.buses.size() + sys_tr.dc.buses.size());
        out["num_ac_buses"] = (int)sys_tr.ac.buses.size();
        out["num_dc_buses"] = (int)sys_tr.dc.buses.size();

        // Verification PF
        json vf;
        vf["converged"] = reconfig_pf_converged;
        vf["iterations"] = reconfig_pf_iterations;
        vf["residual"] = reconfig_pf_residual;
        out["verification_pf"] = vf;

        json sw_on = json::array(), sw_off = json::array();
        for (int t = 0; t < num_steps; ++t) {
          int on_cnt = 0, off_cnt = 0;
          for (const auto& bv : sched.ac_switch_on) if (t < (int)bv.size()) on_cnt += bv.at((size_t)t);
          for (const auto& bv : sched.ac_switch_off) if (t < (int)bv.size()) off_cnt += bv.at((size_t)t);
          sw_on.push_back(on_cnt); sw_off.push_back(off_cnt);
        }
        out["sw_on_per_step"] = sw_on; out["sw_off_per_step"] = sw_off;
        out["ac_branch_closed"] = sched.ac_branch_closed;
        // Derive open/closed branch ID lists from last timestep for frontend display
        {
          json open_ids = json::array(), closed_ids = json::array();
          json branch_details = json::array();
          const int last_t = std::max(0, num_steps - 1);
          for (size_t b = 0; b < sys_tr.ac.branches.size(); ++b) {
            const auto& br = sys_tr.ac.branches[b];
            const int br_id = br.index;
            int closed = 0;
            if (b < sched.ac_branch_closed.size() && last_t < (int)sched.ac_branch_closed[b].size())
              closed = sched.ac_branch_closed[b][(size_t)last_t];
            if (closed) closed_ids.push_back(br_id);
            else        open_ids.push_back(br_id);
            // Detailed branch info for the table
            json bd;
            bd["id"] = br_id;
            bd["from_bus"] = br.from_bus;
            bd["to_bus"] = br.to_bus;
            bd["closed"] = closed != 0;
            bd["name"] = br.name;
            branch_details.push_back(bd);
          }
          out["open_branch_ids"] = open_ids;
          out["closed_branch_ids"] = closed_ids;
          out["branch_details"] = branch_details;
        }
        {
          std::set<int> closed_dc, closed_vsc;
          for (const auto& ref : recon.closed_branches) {
            if (ref.category == hacdcpf::graph::EdgeCategory::DC_Line) closed_dc.insert(ref.index);
            else if (ref.category == hacdcpf::graph::EdgeCategory::VSC_Coupling) closed_vsc.insert(ref.index);
          }
          json dc_details = json::array(), vsc_details = json::array();
          for (const auto& br : sys_tr.dc.branches) {
            dc_details.push_back(json{{"domain", "DC"}, {"id", br.index},
                                      {"from_bus", br.from_bus}, {"to_bus", br.to_bus},
                                      {"closed", closed_dc.count(br.index) != 0}, {"name", br.name}});
          }
          for (const auto& vsc : sys_tr.vsc_converters) {
            vsc_details.push_back(json{{"domain", "VSC"}, {"id", vsc.index},
                                       {"bus_ac", vsc.bus_ac}, {"bus_dc", vsc.bus_dc},
                                       {"closed", closed_vsc.count(vsc.index) != 0}, {"name", vsc.name}});
          }
          out["dc_branch_details"] = dc_details;
          out["vsc_details"] = vsc_details;
        }
        // Tie-switch / circuit-breaker operations projected back to physical
        // devices from canonical branches (BranchExpandMap). This restores the
        // device-space actions lost when switches/CBs are flattened to ACBranches.
        {
          json sw_ops = json::array();
          int sw_close = 0, sw_open = 0, cb_close = 0, cb_open = 0;
          auto category_name = [](hacdcpf::graph::EdgeCategory category) {
            if (category == hacdcpf::graph::EdgeCategory::DC_Line) return "dc_branch";
            if (category == hacdcpf::graph::EdgeCategory::VSC_Coupling) return "vsc";
            return "ac_branch";
          };
          for (const auto& op : recon.switch_operations) {
            const char* kind = op.kind == hacdcpf::analysis::TopoReconfResult::DeviceKind::CircuitBreaker
                                   ? "circuit_breaker"
                                   : (op.kind == hacdcpf::analysis::TopoReconfResult::DeviceKind::Switch
                                          ? "switch" : "branch");
            sw_ops.push_back(json{{"kind", kind}, {"category", category_name(op.category)}, {"index", op.index},
                                  {"from_bus", op.bus_from}, {"to_bus", op.bus_to},
                                  {"close", op.close}});
            if (op.kind == hacdcpf::analysis::TopoReconfResult::DeviceKind::CircuitBreaker)
              (op.close ? cb_close : cb_open)++;
            else if (op.kind == hacdcpf::analysis::TopoReconfResult::DeviceKind::Switch)
              (op.close ? sw_close : sw_open)++;
          }
          out["switch_operations"] = sw_ops;
          json ordered_actions = json::array();
          for (const auto& action : recon.ordered_switch_actions) {
            const char* kind =
                action.kind == hacdcpf::analysis::TopoReconfResult::DeviceKind::CircuitBreaker
                    ? "circuit_breaker"
                    : (action.kind == hacdcpf::analysis::TopoReconfResult::DeviceKind::Switch
                           ? "switch"
                           : "branch");
            ordered_actions.push_back(
                json{{"order", action.order}, {"kind", kind},
                     {"index", action.index}, {"action", action.action},
                     {"reason", action.reason}});
          }
          out["ordered_switch_actions"] = std::move(ordered_actions);
          out["switch_op_summary"] = json{{"switch_close", sw_close}, {"switch_open", sw_open},
                                          {"cb_close", cb_close}, {"cb_open", cb_open}};
          out["applied_faults"] = json{{"ac", opts.value("line_failures", json::array())},
                                       {"dc", opts.value("fault_dc", json::array())},
                                       {"vsc", opts.value("fault_vsc", json::array())}};
        }
        // Per-step per-branch topology for detailed display
        {
          json steps_arr = json::array();
          for (int t = 0; t < num_steps; ++t) {
            json step_open = json::array(), step_closed = json::array();
            for (size_t b = 0; b < sys_tr.ac.branches.size(); ++b) {
              const int br_id = sys_tr.ac.branches[b].index;
              int closed = 0;
              if (b < sched.ac_branch_closed.size() && t < (int)sched.ac_branch_closed[b].size())
                closed = sched.ac_branch_closed[b][(size_t)t];
              if (closed) step_closed.push_back(br_id);
              else        step_open.push_back(br_id);
            }
            steps_arr.push_back(json{{"open", step_open}, {"closed", step_closed}});
          }
          out["steps_topology"] = steps_arr;
        }
        const int n_ess = (int)sched.storage_ac_soc_mwh.size();
        out["num_branches"] = (int)sched.ac_branch_closed.size();
        out["num_ess"] = n_ess;
        json soc_j = json::array();
        for (int t = 0; t < num_steps; ++t) {
          json row = json::array();
          for (int s = 0; s < n_ess; ++s) {
            double soc = 0.0;
            const auto& sv = sched.storage_ac_soc_mwh.at((size_t)s);
            if (t < (int)sv.size()) {
              double cap = (s < (int)sys_tr.ac.storage.size())
                             ? sys_tr.ac.storage.at((size_t)s).e_rated_mwh : 1.0;
              soc = (cap > 0.0) ? sv.at((size_t)t) / cap : 0.0;
            }
            row.push_back(soc);
          }
          soc_j.push_back(row);
        }
        out["ess_soc_by_step"] = soc_j;
        json curt_j = json::array();
        for (int t = 0; t < num_steps; ++t) {
          double curt = 0.0;
          for (const auto& rv : sched.ren_ac_curtail_mw)
            if (t < (int)rv.size()) curt += rv.at((size_t)t);
          curt_j.push_back(curt);
        }
        out["curt_per_step"] = curt_j;
        res.set_content(out.dump(), "application/json");
        g_session.busy.store(false);
      } catch (const std::exception& e) {
        g_session.busy.store(false);
        res.status = 400;
        res.set_content(json{{"error", e.what()}}.dump(), "application/json");
      } catch (...) {
        g_session.busy.store(false);
        res.status = 500;
        res.set_content(json{{"error", "Unknown internal error in topology reconfiguration"}}.dump(), "application/json");
      }
    });

    // ---- EV power-traffic coupling ----
    svr.Post("/api/session/run_ev_traffic",
             [](const httplib::Request& req, httplib::Response& res) {
      bool owns_busy = false;
      try {
        const auto j = json::parse(req.body.empty() ? "{}" : req.body);
        const std::string scenario_source =
            j.value("scenario_source", std::string("evpt_demo_small"));

        hacdcpf::evpt::EVPowerTrafficProblem problem;
        if (scenario_source == "custom") {
          {
            std::lock_guard<std::mutex> lk(g_session.mu);
            if (!g_session.current_system) {
              throw std::runtime_error(
                  "Custom EV-traffic scenarios require a power system in the GUI session");
            }
            problem.system = *g_session.current_system;
          }
          if (!j.contains("scenario") || !j.at("scenario").is_object()) {
            throw std::runtime_error("Custom EV-traffic scenario JSON is missing");
          }
          json scenario = j.at("scenario");
          // Exported GUI scenarios keep nodes/links at the root, while the
          // public parser uses {traffic:{nodes,links}}. Accept both shapes.
          if (!scenario.contains("traffic") && scenario.contains("nodes") &&
              scenario.contains("links")) {
            scenario["traffic"] = {
                {"nodes", scenario.at("nodes")},
                {"links", scenario.at("links")}};
          }
          hacdcpf::io::evpt_problem_from_json(scenario, problem);
        } else {
          problem = hacdcpf::io::build_evpt_demo_case(scenario_source);
        }

        if (problem.traffic.nodes.empty() || problem.traffic.links.empty()) {
          throw std::runtime_error("EV-traffic scenario must contain traffic nodes and links");
        }
        if (problem.routes.empty() || problem.demands.empty()) {
          throw std::runtime_error("EV-traffic scenario must contain routes and EV demands");
        }
        if (problem.system.ac.charging_stations.empty()) {
          throw std::runtime_error(
              "The selected power system has no AC charging stations for route stops");
        }

        if (g_session.busy.exchange(true)) {
          res.status = 409;
          res.set_content(
              json{{"error", "Another analysis is already running"}}.dump(),
              "application/json");
          return;
        }
        owns_busy = true;
        g_session.cancel.store(false);

        const std::string formulation =
            j.value("formulation", std::string("ctm_due"));
        const json model_j =
            j.contains("model_options") && j.at("model_options").is_object()
                ? j.at("model_options")
                : json::object();
        const json ctm_j =
            j.contains("ctm_options") && j.at("ctm_options").is_object()
                ? j.at("ctm_options")
                : json::object();
        const json due_j =
            j.contains("due_options") && j.at("due_options").is_object()
                ? j.at("due_options")
                : json::object();

        const auto ev_opts = hacdcpf::io::evpt_options_from_json(model_j);
        const auto ctm_opts = hacdcpf::io::evpt_ctm_options_from_json(ctm_j);
        const auto due_opts = hacdcpf::io::evpt_due_options_from_json(due_j);
        if (ev_opts.num_steps <= 0 || ev_opts.num_steps > 8760 ||
            !(ev_opts.time_step_hr > 0.0)) {
          throw std::runtime_error(
              "EV-traffic horizon must use 1..8760 steps and a positive time step");
        }
        if (ctm_opts.dt_ctm_hr < 0.0 || ctm_opts.n_cells_per_link < 0 ||
            due_opts.max_iterations <= 0 || due_opts.convergence_tol <= 0.0) {
          throw std::runtime_error("Invalid CTM/DUE algorithm parameters");
        }

        json result;
        if (formulation == "assignment") {
          result = hacdcpf::io::evpt_result_to_json(
              hacdcpf::evpt::simulate_ev_power_traffic(problem, ev_opts));
        } else if (formulation == "ctm_due") {
          result = hacdcpf::io::evpt_ctm_due_result_to_json(
              hacdcpf::evpt::simulate_ev_power_traffic_ctm_due(
                  problem, ev_opts, ctm_opts, due_opts));
        } else if (formulation == "ctm_joint") {
          json coordination_j =
              j.contains("coordination_options") &&
                      j.at("coordination_options").is_object()
                  ? j.at("coordination_options")
                  : json::object();
          coordination_j["evpt_options"] = model_j;
          coordination_j["ctm_options"] = ctm_j;
          coordination_j["due_options"] = due_j;
          auto opts =
              hacdcpf::io::evpt_ctm_joint_options_from_json(coordination_j);
          if (opts.max_iterations <= 0 ||
              opts.price_convergence_tol <= 0.0 ||
              !(opts.price_update_step > 0.0 && opts.price_update_step <= 1.0)) {
            throw std::runtime_error("Invalid CTM-DUE/DC-OPF coordination parameters");
          }
          opts.dcopf_opts.compute_lmp = true;
          opts.dcopf_opts.load_shedding = true;
          result = hacdcpf::io::evpt_ctm_joint_result_to_json(
              hacdcpf::evpt::simulate_ev_power_traffic_ctm_joint(problem, opts));
        } else if (formulation == "joint_optimizer") {
          json optimizer_j =
              j.contains("optimizer_options") &&
                      j.at("optimizer_options").is_object()
                  ? j.at("optimizer_options")
                  : json::object();
          // Core model controls are shared in the GUI and override optimizer
          // defaults unless an optimizer-specific value was explicitly sent.
          for (const char* key : {"num_steps", "time_step_hr", "allow_v2g",
                                  "enforce_road_capacity",
                                  "enforce_generation_capacity",
                                  "value_of_time_per_hr",
                                  "station_energy_cost_weight",
                                  "default_station_price_per_kwh",
                                  "default_charging_efficiency",
                                  "default_route_stop_power_kw_per_vehicle",
                                  "default_station_power_kw"}) {
            if (!optimizer_j.contains(key) && model_j.contains(key)) {
              optimizer_j[key] = model_j.at(key);
            }
          }
          optimizer_j["ctm_options"] = ctm_j;
          const auto opts =
              hacdcpf::io::evpt_joint_optimizer_options_from_json(optimizer_j);
          if (opts.num_steps <= 0 || opts.num_steps > 8760 ||
              !(opts.time_step_hr > 0.0) || opts.mip_gap < 0.0 ||
              opts.time_limit_sec <= 0.0 || opts.max_nodes <= 0) {
            throw std::runtime_error("Invalid joint-optimizer parameters");
          }
          result = hacdcpf::io::evpt_joint_optimizer_result_to_json(
              hacdcpf::evpt::solve_joint_optimizer(problem, opts));
        } else {
          throw std::runtime_error("Unsupported EV-traffic formulation: " +
                                   formulation);
        }

        json out;
        out["module"] = "ev_power_traffic";
        out["formulation"] = formulation;
        out["scenario_source"] = scenario_source;
        if (scenario_source == "evpt_demo_comprehensive") {
          out["verification_profile"] = "comprehensive_joint_v1";
          out["expected_signals"] = {
              {"traffic_nodes", 25}, {"traffic_links", 40},
              {"routes", 7}, {"demands", 4}, {"charging_stations", 3},
              {"dynamic_capacity_links", 2}, {"num_steps", 8}};
        }
        auto scenario_out = hacdcpf::io::evpt_scenario_to_json(problem);
        if (scenario_source == "custom" && j.contains("scenario") &&
            j.at("scenario").is_object()) {
          scenario_out["name"] =
              j.at("scenario").value("name", scenario_out.value("name", ""));
        }
        out["scenario"] = std::move(scenario_out);
        out["parameters"] = j;
        out["result"] = std::move(result);
        g_session.busy.store(false);
        owns_busy = false;
        res.set_content(out.dump(), "application/json");
      } catch (const std::exception& e) {
        if (owns_busy) g_session.busy.store(false);
        res.status = 400;
        res.set_content(json{{"error", e.what()}}.dump(), "application/json");
      } catch (...) {
        if (owns_busy) g_session.busy.store(false);
        res.status = 500;
        res.set_content(
            json{{"error", "Unknown internal error in EV power-traffic analysis"}}
                .dump(),
            "application/json");
      }
    });

    // ---- Annual Production Simulation ----
    svr.Post("/api/session/run_annual_sim",
             [materialize_loads_and_apply_binding]
             (const httplib::Request& req, httplib::Response& res) {
      try {
        const auto request_started = std::chrono::steady_clock::now();
        const auto j = json::parse(req.body.empty() ? "{}" : req.body);
        const double step_hr =
            (j.value("resolution", std::string("6h")) == "1h") ? 1.0 : 6.0;
        const bool use_session_ts =
            j.value("use_session_time_series", false);
        hacdcpf::HybridPowerSystem sys_ann;
        hacdcpf::TimeSeriesData session_ts;
        Session::TsBindingSpec session_binding;
        {
          std::lock_guard<std::mutex> lk(g_session.mu);
          if (!g_session.current_system) throw std::runtime_error("No system loaded");
          sys_ann = *g_session.current_system;
          if (use_session_ts) {
            session_ts = g_session.ts_data;
            session_binding = g_session.ts_binding;
          }
        }
        if (g_session.busy.exchange(true)) {
          res.status = 409;
          res.set_content(json{{"error","Another analysis is already running"}}.dump(), "application/json");
          return;
        }
        g_session.cancel.store(false);
        const bool has_session_profiles =
            use_session_ts &&
            std::any_of(session_ts.profiles.begin(), session_ts.profiles.end(),
                        [](const auto& profile) {
                          return !profile.values.empty();
                        });
        auto ts_data = has_session_profiles
                           ? make_periodic_annual_ts_data(session_ts, step_hr)
                           : make_annual_ts_data(step_hr);
        const int n_rematerialized = has_session_profiles
            ? materialize_loads_and_apply_binding(sys_ann, session_binding)
            : 0;
        assign_available_default_profiles(sys_ann, ts_data);
        hacdcpf::analysis::AnnualProductionSimOptions opts;
        opts.block_type = (j.value("block_type", std::string("monthly")) == "weekly")
            ? hacdcpf::analysis::AnnualBlockType::Weekly
            : hacdcpf::analysis::AnnualBlockType::Monthly;
        opts.ts_pf_options.run_opf = j.value("run_opf", true);
        opts.ts_pf_options.verbose = false;
        // MILP solver + constraint-set selection (shared with run_ts_pf).
        const hacdcpf::UCSolverChoice uc_solver =
            parse_uc_solver_choice(j.value("uc_solver", std::string("auto")));
        const bool enable_net = j.value("enable_network_constraints", false);
        const bool enable_dc_net = j.value("enable_dc_network_constraints", false);
        const double reserve_frac = j.value("reserve_fraction", 0.0);
        opts.ts_pf_options.uc_solver = uc_solver;
        opts.ts_pf_options.enable_network_constraints = enable_net;
        opts.ts_pf_options.enable_dc_network_constraints = enable_dc_net && enable_net;
        opts.ts_pf_options.reserve_requirement_fraction = std::max(0.0, reserve_frac);
        apply_uc_objective(opts.ts_pf_options, j);
        opts.ts_pf_options.enable_external_grid = j.value("enable_external_grid", true);
        opts.ts_pf_options.enable_demand_response = j.value("enable_demand_response", false);
        opts.ts_pf_options.dr_shiftable = j.value("dr_shiftable", false);
        opts.ts_pf_options.w_demand_response = j.value("dr_penalty", 20.0);
        opts.ts_pf_options.enable_dispatchable_pv = j.value("enable_dispatchable_pv", false);
        opts.ts_pf_options.pv_curtail_penalty = j.value("pv_curtail_penalty", 50.0);
        opts.ts_pf_options.enable_microgrid = j.value("enable_microgrid", false);
        opts.ts_pf_options.w_microgrid_island = j.value("microgrid_island_penalty", 100.0);
        opts.ts_pf_options.enable_dc_branch_flows = j.value("enable_dc_branch_flows", false);
        opts.ts_pf_options.enable_storage_degradation = j.value("enable_storage_degradation", false);
        opts.ts_pf_options.enable_vpp = j.value("enable_vpp", false);
        opts.ts_pf_options.enable_energy_router = j.value("enable_energy_router", false);
        opts.ts_pf_options.enable_mobile_storage = j.value("enable_mobile_storage", false);
        opts.ts_pf_options.mobile_storage_corelocate = j.value("mobile_storage_corelocate", false);
        opts.skip_replay = j.value("skip_replay", false);
        opts.enforce_cyclic_soc = j.value("cyclic_soc", true);
        opts.pf_snapshot_interval = j.value("snapshot_interval", 24);
        // Parallel daily decomposition: split the year into independent calendar
        // days (cyclic SOC) solved concurrently; per-day mode SCUC/SCED/DOPF.
        opts.enable_parallel_daily = j.value("parallel_daily", false);
        {
          std::string dm = j.value("daily_mode", std::string("scuc"));
          std::transform(dm.begin(), dm.end(), dm.begin(),
                         [](unsigned char ch){ return static_cast<char>(std::tolower(ch)); });
          if (dm == "sced" || dm == "dynamic_sced")
            opts.daily_mode = hacdcpf::analysis::DailySimMode::DynamicSCED;
          else if (dm == "dopf" || dm == "dynamic_opf" || dm == "opf")
            opts.daily_mode = hacdcpf::analysis::DailySimMode::DynamicOPF;
          else
            opts.daily_mode = hacdcpf::analysis::DailySimMode::SCUC;
        }
        opts.parallel_threads = j.value("parallel_threads", 0);
        opts.enforce_daily_cyclic_soc = j.value("daily_cyclic_soc", true);
        opts.sced_reuse_scuc_commitment = j.value("sced_reuse_scuc_commitment", true);
        opts.verbose = false;
        auto result = hacdcpf::analysis::solve_annual_production_simulation(sys_ann, ts_data, opts);
        json out;
        out["feasible"] = result.feasible;
        out["num_steps"] = result.num_steps;
        out["step_duration_hr"] = result.step_duration_hr;
        out["profile_source"] =
            has_session_profiles ? "imported_scenario" : "built_in_annual";
        out["scenario_profile_binding_active"] =
            has_session_profiles && session_binding.valid;
        out["scenario_profiles_rematerialized"] = n_rematerialized;
        out["imported_profile_period_steps"] =
            has_session_profiles ? session_ts.num_steps : 0;
        out["imported_profile_step_duration_hr"] =
            has_session_profiles ? session_ts.step_duration_hr : 0.0;
        out["imported_profile_period_hr"] =
            has_session_profiles
                ? session_ts.step_duration_hr * session_ts.num_steps
                : 0.0;
        out["profile_expansion_method"] = has_session_profiles
            ? "periodic_interval_average_energy_preserving"
            : "built_in_seasonal_profiles";
        out["total_cost"] = result.total_cost;
        // Echo back the requested solver + active constraint set + objective.
        out["uc_solver_requested"] = uc_solver_choice_label(uc_solver);
        out["solver_name"] = result.solver_name;
        out["parallel_daily"] = opts.enable_parallel_daily;
        out["parallel_daily_effective"] = result.parallel_daily_effective;
        out["parallel_workers"] = result.parallel_workers;
        out["parallel_mode"] = result.parallel_mode;
        out["parallel_execution"] =
            parallel_execution_json(result.parallel_execution);
        out["objective_value"] = result.total_cost;
        out["objective_label"] = "年总运行成本 ($)";
        out["objective_mode"] = uc_objective_label(opts.ts_pf_options.objective_mode);
        {
          const std::string basis =
              opts.enable_parallel_daily
                  ? ((opts.daily_mode == hacdcpf::analysis::DailySimMode::SCUC)
                         ? "parallel daily SCUC dispatch with OPF/PF replay"
                         : (opts.daily_mode == hacdcpf::analysis::DailySimMode::DynamicSCED)
                               ? "parallel daily dynamic SCED dispatch"
                               : "parallel daily dynamic OPF dispatch")
                  : (opts.skip_replay ? "hierarchical UC schedule-only dispatch"
                                      : "hierarchical UC with OPF/PF replay");
          out["cost_formula"] =
              cost_formula_json(opts.ts_pf_options, basis, result.step_duration_hr);
          out["objective_formula"] = out["cost_formula"];
        }
        out["constraints"] = json{
            {"network_constraints", enable_net},
            {"dc_network_constraints", enable_dc_net && enable_net},
            {"reserve_fraction", std::max(0.0, reserve_frac)},
            {"economic_dispatch_opf", opts.ts_pf_options.run_opf},
            {"cyclic_soc", opts.enforce_cyclic_soc}};
        out["total_gen_mwh"] = result.total_gen_mwh;
        out["total_load_mwh"] = result.total_load_mwh;
        out["total_renewable_mwh"] = result.total_renewable_mwh;
        out["total_curtailment_mwh"] = result.total_curtailment_mwh;
        {
          double dr_up_mwh = 0.0;
          double dr_down_mwh = 0.0;
          for (const auto& window : result.weekly_schedules) {
            for (const auto& row : window.uc.flexible_load_up)
              for (double value : row)
                dr_up_mwh += std::max(0.0, value) * result.step_duration_hr;
            for (const auto& row : window.uc.flexible_load_down)
              for (double value : row)
                dr_down_mwh += std::max(0.0, value) * result.step_duration_hr;
          }
          out["demand_response_resource_count"] =
              static_cast<int>(sys_ann.ac.flexible_loads.size());
          out["demand_response_up_mwh"] = dr_up_mwh;
          out["demand_response_down_mwh"] = dr_down_mwh;
          out["demand_response_net_shift_mwh"] = dr_up_mwh - dr_down_mwh;
          const double renewable_available_mwh =
              result.total_renewable_mwh + result.total_curtailment_mwh;
          out["renewable_utilization_pct"] =
              renewable_available_mwh > 1e-9
                  ? 100.0 * result.total_renewable_mwh / renewable_available_mwh
                  : 0.0;
        }
        out["storage_discharge_mwh"] = result.storage_discharge_mwh;
        out["storage_charge_mwh"] = result.storage_charge_mwh;
        out["external_grid_import_mwh"] = result.external_grid_import_mwh;
        out["external_grid_export_mwh"] = result.external_grid_export_mwh;
        out["total_supply_mwh"] = result.total_supply_mwh;
        out["total_demand_mwh"] = result.total_demand_mwh;
        out["power_balance_error_mwh"] = result.power_balance_error_mwh;
        out["total_ens_mwh"] = result.total_ens_mwh;
        out["total_loss_mwh"] = result.total_loss_mwh;
        out["num_pf_converged"] = result.num_pf_converged;
        out["num_opf_converged"] = result.num_opf_converged;
        // Per-step timeline (subsample for large data)
        const int max_timeline = 1000;
        const int stride = std::max(1, (int)result.step_results.size() / max_timeline);
        json tl_gen = json::array(), tl_load = json::array(), tl_ren = json::array(),
             tl_curt = json::array(), tl_ess = json::array(), tl_loss = json::array(),
             tl_supply = json::array(), tl_demand = json::array(),
             tl_balance = json::array(), tl_hours = json::array();
        for (size_t i = 0; i < result.step_results.size(); i += static_cast<size_t>(stride)) {
          const auto& s = result.step_results[i];
          tl_hours.push_back(static_cast<double>(i) * result.step_duration_hr);
          tl_gen.push_back(s.total_gen_mw);
          tl_load.push_back(s.total_load_mw);
          tl_ren.push_back(s.total_renewable_mw);
          tl_curt.push_back(s.total_curtailment_mw);
          tl_ess.push_back(s.total_ess_mw);
          tl_loss.push_back(s.total_loss_mw);
          tl_supply.push_back(s.total_supply_mw);
          tl_demand.push_back(s.total_demand_mw);
          tl_balance.push_back(s.power_balance_error_mw);
        }
        out["timeline_hours"] = tl_hours;
        out["timeline_gen"] = tl_gen;
        out["timeline_load"] = tl_load;
        out["timeline_ren"] = tl_ren;
        out["timeline_curt"] = tl_curt;
        out["timeline_ess"] = tl_ess;
        out["timeline_loss"] = tl_loss;
        out["timeline_supply"] = tl_supply;
        out["timeline_demand"] = tl_demand;
        out["timeline_balance_error"] = tl_balance;
        // Representative days (1-based) for quick drill-down presets: global
        // peak-load / min-load / peak-net-load, plus the peak-net-load day in
        // each season.  Computed from the full per-step results (not the
        // subsampled timeline) so they are exact.
        {
          const int spd = std::max(1, static_cast<int>(std::lround(
              24.0 / std::max(1e-9, result.step_duration_hr))));
          const int nsteps = static_cast<int>(result.step_results.size());
          const int ndays = (nsteps + spd - 1) / spd;
          auto day_month = [](int d0) {
            static const int md[12] = {31,28,31,30,31,30,31,31,30,31,30,31};
            int rem = d0;
            for (int m = 0; m < 12; ++m) { if (rem < md[m]) return m; rem -= md[m]; }
            return 11;
          };
          auto season_of = [](int month) {
            if (month >= 2 && month <= 4) return 0;   // spring
            if (month >= 5 && month <= 7) return 1;   // summer
            if (month >= 8 && month <= 10) return 2;  // autumn
            return 3;                                 // winter
          };
          int peak_load_day = 0, min_load_day = 0, peak_net_day = 0;
          double peak_load = -1e30, min_load = 1e30, peak_net = -1e30;
          int season_day[4] = {-1, -1, -1, -1};
          double season_net[4] = {-1e30, -1e30, -1e30, -1e30};
          for (int d = 0; d < ndays; ++d) {
            const int g0 = d * spd, g1 = std::min(g0 + spd, nsteps);
            if (g1 <= g0) continue;
            double load_sum = 0.0, net_peak = -1e30;
            for (int t = g0; t < g1; ++t) {
              const auto& s = result.step_results[static_cast<size_t>(t)];
              load_sum += s.total_load_mw;
              net_peak = std::max(net_peak, s.total_load_mw - s.total_renewable_mw);
            }
            if (load_sum > peak_load) { peak_load = load_sum; peak_load_day = d; }
            if (load_sum < min_load) { min_load = load_sum; min_load_day = d; }
            if (net_peak > peak_net) { peak_net = net_peak; peak_net_day = d; }
            const int se = season_of(day_month(d));
            if (net_peak > season_net[se]) { season_net[se] = net_peak; season_day[se] = d; }
          }
          json rep = json::array();
          auto add_rep = [&](const char* label, int d0) {
            if (d0 >= 0 && d0 < ndays) rep.push_back({{"label", label}, {"day", d0 + 1}});
          };
          add_rep("峰荷日", peak_load_day);
          add_rep("谷荷日", min_load_day);
          add_rep("峰净荷日", peak_net_day);
          static const char* sn[4] = {"春季代表日", "夏季代表日", "秋季代表日", "冬季代表日"};
          for (int s = 0; s < 4; ++s) add_rep(sn[s], season_day[s]);
          out["representative_days"] = rep;
        }
        // Monthly summaries
        json ms = json::array();
        for (const auto& m : result.monthly_summaries) {
          ms.push_back({{"block_id", m.block_id}, {"total_gen_mwh", m.total_gen_mwh},
                        {"total_load_mwh", m.total_load_mwh},
                        {"total_renewable_mwh", m.total_renewable_mwh},
                        {"total_curtailment_mwh", m.total_curtailment_mwh},
                        {"storage_discharge_mwh", m.storage_discharge_mwh},
                        {"storage_charge_mwh", m.storage_charge_mwh},
                        {"external_grid_import_mwh", m.external_grid_import_mwh},
                        {"external_grid_export_mwh", m.external_grid_export_mwh},
                        {"total_supply_mwh", m.total_supply_mwh},
                        {"total_demand_mwh", m.total_demand_mwh},
                        {"power_balance_error_mwh", m.power_balance_error_mwh},
                        {"total_loss_mwh", m.total_loss_mwh},
                        {"total_ens_mwh", m.total_ens_mwh},
                        {"total_cost", m.total_cost},
                        {"cost", m.total_cost},
                        {"production_cost", m.total_cost},
                        {"objective_value", m.total_cost},
                        {"num_pf_converged", m.num_pf_converged},
                        {"num_steps", m.num_steps}});
        }
        out["monthly_summaries"] = ms;
        // Generator stats
        json gs = json::array();
        for (size_t i = 0; i < result.gen_stats.size(); ++i) {
          const auto& g = result.gen_stats[i];
          gs.push_back({{"name", g.name}, {"gen_index", g.gen_index},
                        {"component_index", g.gen_index},
                        {"canvas_type", "gen"}, {"canvas_index", g.gen_index},
                        {"component_type", "generator"},
                        {"component_domain", "AC"}, {"position", i},
                        {"total_energy_mwh", g.total_energy_mwh},
                        {"capacity_factor", g.capacity_factor},
                        {"total_startups", g.total_startups},
                        {"total_hours_online", g.total_hours_online}});
        }
        out["gen_stats"] = gs;
        // Storage stats
        json ss = json::array();
        for (size_t i = 0; i < result.storage_stats.size(); ++i) {
          const auto& s = result.storage_stats[i];
          ss.push_back({{"name", s.name}, {"storage_index", s.storage_index},
                        {"is_dc", s.is_dc},
                        {"component_index", s.storage_index},
                        {"canvas_type", s.is_dc ? "dcStorage" : "storage"},
                        {"canvas_index", s.storage_index},
                        {"component_type", s.is_dc ? "dc_storage" : "storage"},
                        {"component_domain", s.is_dc ? "DC" : "AC"},
                        {"position", i},
                        {"total_charge_mwh", s.total_charge_mwh},
                        {"total_discharge_mwh", s.total_discharge_mwh},
                        {"cycles", s.cycles}});
        }
        out["storage_stats"] = ss;
        // Renewable stats
        json rs = json::array();
        for (size_t i = 0; i < result.renewable_stats.size(); ++i) {
          const auto& r = result.renewable_stats[i];
          rs.push_back({{"name", r.name}, {"ren_index", r.ren_index},
                        {"component_index", r.ren_index},
                        {"canvas_type", "renGen"}, {"canvas_index", r.ren_index},
                        {"component_type", "renewable_gen"},
                        {"component_domain", "AC"}, {"position", i},
                        {"total_energy_mwh", r.total_energy_mwh},
                        {"total_curtailed_mwh", r.total_curtailed_mwh},
                        {"capacity_factor", r.capacity_factor},
                        {"curtailment_rate", r.curtailment_rate}});
        }
        out["renewable_stats"] = rs;
        // PF voltage snapshots (subsampled vm for heatmap)
        json snap_hours = json::array(), snap_vm = json::array();
        for (const auto& snap : result.pf_snapshots) {
          if (!snap.converged || snap.vm.empty()) continue;
          snap_hours.push_back(static_cast<double>(snap.global_step) * result.step_duration_hr);
          snap_vm.push_back(snap.vm);
        }
        out["snapshot_hours"] = snap_hours;
        out["snapshot_vm"] = snap_vm;
        json snapshot_ac_bus_ids = json::array();
        json snapshot_dc_bus_ids = json::array();
        json snapshot_ac_bus_series = json::array();
        json snapshot_dc_bus_series = json::array();
        for (size_t i = 0; i < sys_ann.ac.buses.size(); ++i) {
          const auto& bus = sys_ann.ac.buses[i];
          json values = json::array();
          for (const auto& snap : result.pf_snapshots) {
            if (!snap.converged || snap.vm.empty()) continue;
            values.push_back(i < snap.vm.size() ? json(snap.vm[i]) : json(nullptr));
          }
          snapshot_ac_bus_ids.push_back(bus.index);
          snapshot_ac_bus_series.push_back(
              json{{"canvas_type", "ac"}, {"canvas_index", bus.index},
                   {"component_type", "ac_bus"}, {"component_domain", "AC"},
                   {"position", i}, {"name", bus.name}, {"bus", bus.index},
                   {"values", values}});
        }
        for (size_t i = 0; i < sys_ann.dc.buses.size(); ++i) {
          const auto& bus = sys_ann.dc.buses[i];
          json values = json::array();
          for (const auto& snap : result.pf_snapshots) {
            if (!snap.converged || snap.vm.empty()) continue;
            values.push_back(i < snap.vdc.size() ? json(snap.vdc[i]) : json(nullptr));
          }
          snapshot_dc_bus_ids.push_back(bus.index);
          snapshot_dc_bus_series.push_back(
              json{{"canvas_type", "dc"}, {"canvas_index", bus.index},
                   {"component_type", "dc_bus"}, {"component_domain", "DC"},
                   {"position", i}, {"name", bus.name}, {"bus", bus.index},
                   {"values", values}});
        }
        out["snapshot_ac_bus_ids"] = snapshot_ac_bus_ids;
        out["snapshot_dc_bus_ids"] = snapshot_dc_bus_ids;
        out["snapshot_ac_bus_series"] = snapshot_ac_bus_series;
        out["snapshot_dc_bus_series"] = snapshot_dc_bus_series;
        out["component_results"] = json::array();
        for (const auto& row : gs) out["component_results"].push_back(row);
        for (const auto& row : ss) out["component_results"].push_back(row);
        for (const auto& row : rs) out["component_results"].push_back(row);
        VoltageQualificationMetrics voltage_metrics;
        for (const auto& snap : result.pf_snapshots) {
          if (!snap.converged) continue;
          accumulate_voltage_qualification(
              voltage_metrics, sys_ann, snap.vm, snap.vdc);
        }
        out["voltage_qualification"] = voltage_qualification_json(voltage_metrics);
        out["voltage_qualification"]["basis"] = "converged_sampled_pf_snapshots";
        out["execution_time_sec"] = elapsed_seconds(request_started);
        // Geo data for animation map
        json geo_buses = json::array();
        for (const auto& bus : sys_ann.ac.buses) {
          geo_buses.push_back({{"id", bus.index}, {"name", bus.name}, {"type", "ac"},
                               {"lat", bus.latitude}, {"lon", bus.longitude}});
        }
        for (const auto& bus : sys_ann.dc.buses) {
          geo_buses.push_back({{"id", bus.index}, {"name", bus.name}, {"type", "dc"},
                               {"lat", bus.latitude}, {"lon", bus.longitude}});
        }
        out["geo_buses"] = geo_buses;
        json geo_ac_branches = json::array();
        for (const auto& br : sys_ann.ac.branches) {
          auto it_from = std::find_if(sys_ann.ac.buses.begin(), sys_ann.ac.buses.end(),
                                      [&](const auto& b){ return b.index == br.from_bus; });
          auto it_to = std::find_if(sys_ann.ac.buses.begin(), sys_ann.ac.buses.end(),
                                    [&](const auto& b){ return b.index == br.to_bus; });
          double from_lat = 0, from_lon = 0, to_lat = 0, to_lon = 0;
          if (it_from != sys_ann.ac.buses.end()) { from_lat = it_from->latitude; from_lon = it_from->longitude; }
          if (it_to != sys_ann.ac.buses.end()) { to_lat = it_to->latitude; to_lon = it_to->longitude; }
          geo_ac_branches.push_back({{"from_bus", br.from_bus}, {"to_bus", br.to_bus},
                                     {"from_lat", from_lat}, {"from_lon", from_lon},
                                     {"to_lat", to_lat}, {"to_lon", to_lon}});
        }
        out["geo_ac_branches"] = geo_ac_branches;
        res.set_content(out.dump(), "application/json");
        g_session.busy.store(false);
      } catch (const std::exception& e) {
        g_session.busy.store(false);
        res.status = 400;
        res.set_content(json{{"error", e.what()}}.dump(), "application/json");
      }
    });

    // ---- Lifecycle Simulation ----
    svr.Post("/api/session/run_lifecycle_sim",
             [](const httplib::Request& req, httplib::Response& res) {
      try {
        hacdcpf::HybridPowerSystem sys_lc;
        {
          std::lock_guard<std::mutex> lk(g_session.mu);
          if (!g_session.current_system) throw std::runtime_error("No system loaded");
          sys_lc = *g_session.current_system;
        }
        if (g_session.busy.exchange(true)) {
          res.status = 409;
          res.set_content(json{{"error","Another analysis is already running"}}.dump(), "application/json");
          return;
        }
        g_session.cancel.store(false);
        const auto j = json::parse(req.body.empty() ? "{}" : req.body);
        const double step_hr = (j.value("resolution", std::string("6h")) == "1h") ? 1.0 : 6.0;
        auto ts_data = make_annual_ts_data(step_hr);
        assign_available_default_profiles(sys_lc, ts_data);

        hacdcpf::analysis::LifecycleSimOptions opts;
        opts.num_years = j.value("num_years", 20);
        opts.discount_rate = j.value("discount_rate", 0.05);
        opts.load_growth_rate = j.value("load_growth_rate", 0.02);
        opts.pv_annual_derating = j.value("pv_annual_derating", 0.005);
        opts.calendar_degradation_per_year = j.value("calendar_degradation", 0.02);
        opts.step_duration_hr = step_hr;
        opts.verbose = false;

        // Apply capacity scaling
        hacdcpf::analysis::CapacityScaling cap_scaling;
        cap_scaling.pv_scale = j.value("pv_scale", 1.0);
        cap_scaling.wind_scale = j.value("wind_scale", 1.0);
        cap_scaling.bess_power_scale = j.value("bess_power_scale", 1.0);
        cap_scaling.bess_energy_scale = j.value("bess_energy_scale", 1.0);
        cap_scaling.diesel_scale = j.value("diesel_scale", 1.0);
        hacdcpf::analysis::apply_capacity_scaling(sys_lc, cap_scaling);

        auto result = hacdcpf::analysis::run_lifecycle_simulation(sys_lc, ts_data, opts);

        json out;
        out["feasible"] = result.feasible;
        out["num_years"] = result.num_years;
        out["npv_total_cost"] = result.npv_total_cost;
        out["total_carbon_tco2"] = result.total_carbon_tco2;
        out["total_replacement_cost"] = result.total_replacement_cost;
        out["total_replacements"] = result.total_replacements;

        // Per-year data
        json years_arr = json::array();
        for (const auto& yr : result.year_results) {
          json yj;
          yj["year"] = yr.year;
          yj["load_growth_factor"] = yr.load_growth_factor;
          yj["annual_cost"] = yr.annual_cost;
          yj["annual_gen_mwh"] = yr.annual_gen_mwh;
          yj["annual_load_mwh"] = yr.annual_load_mwh;
          yj["annual_renewable_mwh"] = yr.annual_renewable_mwh;
          yj["annual_curtailment_mwh"] = yr.annual_curtailment_mwh;
          yj["annual_ens_mwh"] = yr.annual_ens_mwh;
          yj["annual_carbon_tco2"] = yr.annual_carbon_tco2;
          yj["avg_carbon_intensity"] = yr.avg_carbon_intensity;
          yj["feasible"] = yr.feasible;

          // Bounds
          json bj;
          bj["total_bound_tco2"] = yr.bounds.total_bound_tco2;
          bj["dispatch_bound_tco2"] = yr.bounds.dispatch.bound_tco2;
          bj["sampling_bound_tco2"] = yr.bounds.sampling.bound_tco2;
          bj["storage_carbon_bound_tco2"] = yr.bounds.storage_carbon.bound_tco2;
          yj["bounds"] = bj;

          // Cross-validation
          json cvj;
          cvj["dense_carbon_tco2"] = yr.cross_validation.dense_carbon_tco2;
          cvj["sampled_carbon_tco2"] = yr.cross_validation.sampled_carbon_tco2;
          cvj["sampling_gap_tco2"] = yr.cross_validation.sampling_gap_tco2;
          cvj["sampling_gap_pct"] = yr.cross_validation.sampling_gap_pct;
          cvj["total_bound_pct"] = yr.cross_validation.total_bound_pct;
          cvj["dispatch_bound_pct"] = yr.cross_validation.dispatch_bound_pct;
          cvj["sampling_bound_pct"] = yr.cross_validation.sampling_bound_pct;
          cvj["storage_bound_pct"] = yr.cross_validation.storage_bound_pct;
          yj["cross_validation"] = cvj;

          // Storage states
          json ss_arr = json::array();
          for (const auto& ss : yr.storage_states) {
            ss_arr.push_back({
              {"storage_index", ss.storage_index},
              {"name", ss.name},
              {"soh", ss.soh},
              {"soh_cycle", ss.soh_cycle},
              {"soh_calendar", ss.soh_calendar},
              {"effective_capacity_mwh", ss.effective_capacity_mwh},
              {"cycles_this_year", ss.cycles_this_year},
              {"cumulative_cycles", ss.cumulative_cycles},
              {"replaced", ss.replaced},
            });
          }
          yj["storage_states"] = ss_arr;

          // Renewable states
          json rs_arr = json::array();
          for (const auto& rs : yr.renewable_states) {
            rs_arr.push_back({
              {"ren_index", rs.ren_index},
              {"name", rs.name},
              {"derated_capacity_mw", rs.derated_capacity_mw},
              {"original_capacity_mw", rs.original_capacity_mw},
              {"derating_factor", rs.derating_factor},
            });
          }
          yj["renewable_states"] = rs_arr;

          years_arr.push_back(yj);
        }
        out["years"] = years_arr;

        // Replacement events
        json repl_arr = json::array();
        for (const auto& re : result.all_replacements) {
          repl_arr.push_back({
            {"year", re.year},
            {"storage_index", re.storage_index},
            {"storage_name", re.storage_name},
            {"old_soh", re.old_soh},
            {"replacement_cost_usd", re.replacement_cost_usd},
          });
        }
        out["replacements"] = repl_arr;

        res.set_content(out.dump(), "application/json");
        g_session.busy.store(false);
      } catch (const std::exception& e) {
        g_session.busy.store(false);
        res.status = 400;
        res.set_content(json{{"error", e.what()}}.dump(), "application/json");
      }
    });

    // ---- Lifecycle Capacity Comparison ----
    svr.Post("/api/session/run_lifecycle_compare",
             [](const httplib::Request& req, httplib::Response& res) {
      try {
        hacdcpf::HybridPowerSystem sys_base;
        {
          std::lock_guard<std::mutex> lk(g_session.mu);
          if (!g_session.current_system) throw std::runtime_error("No system loaded");
          sys_base = *g_session.current_system;
        }
        if (g_session.busy.exchange(true)) {
          res.status = 409;
          res.set_content(json{{"error","Another analysis is already running"}}.dump(), "application/json");
          return;
        }
        g_session.cancel.store(false);
        const auto j = json::parse(req.body.empty() ? "{}" : req.body);
        const double step_hr = (j.value("resolution", std::string("6h")) == "1h") ? 1.0 : 6.0;
        auto ts_data = make_annual_ts_data(step_hr);
        assign_available_default_profiles(sys_base, ts_data);

        hacdcpf::analysis::LifecycleSimOptions opts;
        opts.num_years = j.value("num_years", 20);
        opts.discount_rate = j.value("discount_rate", 0.05);
        opts.load_growth_rate = j.value("load_growth_rate", 0.02);
        opts.pv_annual_derating = j.value("pv_annual_derating", 0.005);
        opts.calendar_degradation_per_year = j.value("calendar_degradation", 0.02);
        opts.step_duration_hr = step_hr;
        opts.verbose = false;

        // Base capacity scaling
        hacdcpf::analysis::CapacityScaling base_scaling;
        base_scaling.pv_scale = j.value("pv_scale", 1.0);
        base_scaling.wind_scale = j.value("wind_scale", 1.0);
        base_scaling.bess_power_scale = j.value("bess_power_scale", 1.0);
        base_scaling.bess_energy_scale = j.value("bess_energy_scale", 1.0);
        base_scaling.diesel_scale = j.value("diesel_scale", 1.0);

        // Sweep configuration
        const std::string sweep_param = j.value("sweep_param", std::string("bess_energy"));
        const double sweep_min = j.value("sweep_min", 0.5);
        const double sweep_max = j.value("sweep_max", 3.0);
        const int sweep_steps = std::min(j.value("sweep_steps", 6), 20);

        std::vector<double> scale_values;
        for (int i = 0; i < sweep_steps; ++i) {
          double sv = (sweep_steps <= 1) ? sweep_min :
              sweep_min + (sweep_max - sweep_min) * i / (sweep_steps - 1);
          scale_values.push_back(sv);
        }

        auto cmp = hacdcpf::analysis::run_lifecycle_comparison(
            sys_base, ts_data, opts, sweep_param, scale_values, base_scaling);

        json out;
        out["sweep_parameter"] = cmp.sweep_parameter;
        out["num_scenarios"] = cmp.num_scenarios;
        json scens_arr = json::array();
        for (const auto& sc : cmp.scenarios) {
          json sj;
          sj["label"] = sc.label;
          sj["npv_total_cost"] = sc.npv_total_cost;
          sj["total_carbon_tco2"] = sc.total_carbon_tco2;
          sj["total_replacement_cost"] = sc.total_replacement_cost;
          sj["total_replacements"] = sc.total_replacements;
          sj["feasible"] = sc.feasible;
          sj["yearly_carbon"] = sc.yearly_carbon;
          sj["yearly_cost"] = sc.yearly_cost;
          sj["total_pv_mw"] = sc.total_pv_mw;
          sj["total_wind_mw"] = sc.total_wind_mw;
          sj["total_bess_mw"] = sc.total_bess_mw;
          sj["total_bess_mwh"] = sc.total_bess_mwh;
          sj["total_diesel_mw"] = sc.total_diesel_mw;
          scens_arr.push_back(sj);
        }
        out["scenarios"] = scens_arr;

        res.set_content(out.dump(), "application/json");
        g_session.busy.store(false);
      } catch (const std::exception& e) {
        g_session.busy.store(false);
        res.status = 400;
        res.set_content(json{{"error", e.what()}}.dump(), "application/json");
      }
    });

